/* FINALE — 어휘요약문 로드맵 STEP 3 (tools: /home/claude/work/export_fin.py 로 생성) */
window.FIN = {"seasons":[{"id":"s1","name":"Season 1","sub":"1학기","rounds":[{"r":1,"qs":[{"id":"q01","no":1,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":null,"pas":"Sometimes we understand things only from a small part. We see one side of a story and think we know the truth. But one piece is not the full picture. When we put the pieces together, everything starts to make more sense. To see clearly, we must look at both the parts and everything together.","sum":"Our understanding is (A) until we see the (B) picture.","gloss":"","bl":{"A":[{"first":"p","len":7,"sfx":""}],"B":[{"first":"w","len":5,"sfx":""}]},"key":{"A":{"w":"partial","acc":["partial"],"freq":true,"src":["[1학년] 2025년 1학기 중간 서답형 4번","[1학년] 2022년 2학기 기말 객관식 8번"],"note":""},"B":{"w":"whole","acc":["whole"],"freq":true,"src":["[1학년] 2024년 1학기 중간 서답형 1번"],"note":""}},"tr":"우리는 때때로 작은 일부만 보고 어떤 것을 이해하려고 한다. 이야기의 한쪽 면만 보고서 진실을 안다고 착각하기도 한다. 하지만 한 조각은 전체 그림이 아니다. 조각들을 모두 맞춰야 비로소 의미가 분명해진다. 명확히 보기 위해서는 부분과 전체를 함께 모두 봐야 한다.","ex":{"flow":"지문은 \"일부만 보면 진실을 다 안다고 착각하지만, 조각을 모아 전체를 봐야 분명해진다\"는 내용. 요약문은 부분 ↔ 전체의 대비로 정리한다.","b":{"A":["partial 형) 부분적인, 불완전한","only from a small part / one piece is not the full picture","part(부분)+-ial. \"편파적인\"이라는 뜻도 있으니 문맥으로 구분. 반의어 complete, whole"],"B":["whole 형) 전체의, 온전한","the full picture / everything together","see the whole picture = 큰 그림을 보다. hole(구멍)과 철자 혼동 주의"]}}},{"id":"q02","no":2,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Importance of Asking","pas":"Progress in any field begins not with answers but with questions. The importance of asking lies in how it directs our attention and challenges what we take for granted. A single question can open a new path of thought, turning uncertainty into discovery.","sum":"The (A) of asking lies in its power to guide thought and (B) doubt into discovery.","gloss":"질문의 중요성은 생각을 유도하고 의심을 발견으로 전환하는 힘에 있습니다.","bl":{"A":[{"first":"r","len":9,"sfx":""}],"B":[{"first":"t","len":9,"sfx":""}]},"key":{"A":{"w":"relevance","acc":["relevance"],"freq":true,"src":["[1학년] 2023년 1학기 기말 서답형 9번","[1학년] 2021년 2학기 중간 객관식 17번"],"note":""},"B":{"w":"transform","acc":["transform"],"freq":true,"src":["[1학년] 2024년 2학기 중간 객관식 9번"],"note":""}},"tr":"어떤 분야에서든 진보는 답이 아니라 질문에서 시작된다. 질문을 던지는 것의 중요성(importance)은 우리의 주의를 이끌고, 당연하게 여겼던 것을 다시 생각하게 만드는 데 있다. 단 하나의 질문이 새로운 생각의 길을 열어, 불확실성을 발견으로 바꿀 수 있다.","ex":{"flow":"지문의 \"The importance of asking lies in ~\"을 요약문이 그대로 받으면서 importance를 다른 말로, turning uncertainty into discovery의 turn A into B를 동사로 바꿔 쓴 문제.","b":{"A":["relevance 명) 관련성, (당면 문제에 대한) 중요성·적절성","The importance of asking","importance를 그대로 쓰지 않고 패러프레이즈한 단어. 형용사 relevant(관련 있는) ↔ irrelevant"],"B":["transform 동) 변형시키다, 바꾸다","turning uncertainty into discovery","transform A into B = A를 B로 바꾸다. 요약문의 doubt = uncertainty, discovery는 그대로. 명사 transformation"]}}},{"id":"q03","no":3,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"When Memory Fades","pas":"As people get older, they sometimes forget things more easily. They may not remember names or faces as well as before. This change can feel sad, but it is a natural part of life. Even when memory becomes weaker, kindness and love still remain.","sum":"Even if the mind is (A) and memory (B)s, human kindness does not disappear.","gloss":"","bl":{"A":[{"first":"i","len":8,"sfx":""}],"B":[{"first":"d","len":7,"sfx":""}]},"key":{"A":{"w":"impaired","acc":["impaired"],"freq":false,"src":[],"note":""},"B":{"w":"decline(s)","acc":["decline(s)"],"freq":false,"src":[],"note":""}},"tr":"사람들이 나이가 들면, 더 쉽게 어떤 것을 잊어버리기도 한다. 이전만큼 이름이나 얼굴을 잘 기억하지 못할 수도 있다. 이런 변화는 슬프게 느껴질 수 있지만, 삶의 자연스러운 부분이다. 기억이 약해져도, 친절과 사랑은 여전히 남아 있다.","ex":{"flow":"나이가 들며 기억력이 약해져도 친절과 사랑은 남는다는 내용. 요약문은 \"정신이 손상되고 기억이 쇠퇴해도\"로 압축한다.","b":{"A":["impaired 형) 손상된, (기능이) 약해진","forget things more easily / may not remember","impair(손상시키다)의 과거분사. hearing-impaired(청각 장애가 있는)처럼 쓰임"],"B":["decline 동) 감소하다, 쇠퇴하다","memory becomes weaker","빈칸 뒤 s가 주어져 있으니 동사 원형 decline을 써서 declines를 완성. 명사로도 쓰임(a decline in ~)"]}}},{"id":"q04","no":4,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Finding Balance","pas":"Life is full of opposite feelings. We want to be alone, but we also want to be with others. We want to rest, but we also want to move forward. These wishes may seem different, but they can live together. Peace comes when we accept both sides instead of choosing only one.","sum":"Our feelings often (A) each other, and (B) them helps us stay peaceful.","gloss":"","bl":{"A":[{"first":"c","len":10,"sfx":""}],"B":[{"first":"b","len":9,"sfx":""}]},"key":{"A":{"w":"contradict","acc":["contradict"],"freq":false,"src":[],"note":""},"B":{"w":"balancing","acc":["balancing"],"freq":false,"src":[],"note":""}},"tr":"삶은 서로 반대되는 감정들로 가득하다. 우리는 혼자 있고 싶지만, 또 누군가와 함께 있고 싶기도 하다. 쉬고 싶지만, 동시에 앞으로 나아가고 싶다. 이런 바람들은 서로 달라 보이지만 함께 공존할 수 있다. 한쪽만 고르려 하지 않고 두 면을 받아들일 때 평화가 찾아온다.","ex":{"flow":"\"혼자 있고 싶지만 함께 있고 싶다\"처럼 반대 감정이 공존하고, 한쪽만 고르지 말고 둘 다 받아들일 때 평화가 온다는 내용.","b":{"A":["contradict 동) 모순되다, 반박하다","opposite feelings / These wishes may seem different","주어 Our feelings(복수) → 동사 원형. contra(반대)+dict(말하다). 형용사 contradictory"],"B":["balancing 명) 균형 잡기 (동명사)","accept both sides instead of choosing only one","빈칸이 문장의 주어 자리(… them helps us) → 동명사 balancing. 동사 balance, 형용사 balanced"]}}},{"id":"q05","no":5,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"The Art of Adapting","pas":"A tool is only as valuable as the number of situations it can respond to. A mind works the same way — when faced with change, it grows by learning to shift shape. Those who can see from many angles, and think beyond fixed methods, turn challenges into opportunities with quiet creativity.","sum":"A (A) mind adapts to change by viewing problems from many perspectives.","gloss":"","bl":{"A":[{"first":"v","len":9,"sfx":""}]},"key":{"A":{"w":"versatile","acc":["versatile"],"freq":true,"src":["[1학년] 2024년 2학기 기말 서답형 5번"],"note":""}},"tr":"도구의 가치는 얼마나 다양한 상황에 대응할 수 있는가에 달려 있다. 우리의 마음도 마찬가지다 — 변화에 직면할 때, 형태를 바꾸며 배우는 법을 통해 성장한다. 여러 관점에서 보고, 고정된 방식을 넘어 생각할 줄 아는 사람은 도전을 조용한 창의력으로 기회로 바꾼다.","ex":{"flow":"도구의 가치가 대응할 수 있는 상황 수에 달려 있듯, 여러 각도로 보고 고정된 방식을 넘어 생각하는 마음이 변화에 강하다는 내용.","b":{"A":["versatile 형) 다재다능한, 다용도의, 융통성 있는","see from many angles, think beyond fixed methods / learning to shift shape","vers(돌다)+-atile → 여러 방향으로 돌 수 있는. a versatile tool/mind. 명사 versatility"]}}},{"id":"q06","no":6,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Weight of Effort","pas":"Growth rarely comes in comfort. Muscles strengthen only after strain, and understanding deepens only after confusion. Each struggle is a quiet teacher, shaping endurance and revealing how far persistence can carry us.","sum":"While (A) brings rest, only (B) builds endurance and depth.","gloss":"편안함은 휴식을 주지만, 오직 노력(에너지의 발휘)만이 인내와 깊이를 만들어낸다.","bl":{"A":[{"first":"e","len":4,"sfx":""}],"B":[{"first":"e","len":8,"sfx":""}]},"key":{"A":{"w":"ease","acc":["ease"],"freq":false,"src":[],"note":""},"B":{"w":"exertion","acc":["exertion"],"freq":false,"src":[],"note":""}},"tr":"성장은 편안함 속에서는 거의 오지 않는다. 근육은 긴장과 통증을 겪은 뒤에야 강해지고, 이해는 혼란을 거친 뒤에야 깊어진다. 모든 고투는 조용한 스승이다 — 인내가 우리를 얼마나 멀리 이끌 수 있는지를 보여주며, 끈기를 단련시킨다.","ex":{"flow":"성장은 편안함 속에서 오지 않고, 긴장과 혼란·고군분투를 거쳐야 인내와 깊이가 생긴다는 내용. 편안함 ↔ 노력의 대비.","b":{"A":["ease 명) 편안함, 쉬움","comfort","with ease = 쉽게. 동사로 \"완화하다\"(ease the pain)도 있음. easy의 명사형"],"B":["exertion 명) (힘·노력의) 발휘, 노력","strain / struggle / persistence","exert(힘을 쓰다)+-ion. exert oneself = 애쓰다. 철자 exertion(-tion) 주의"]}}},{"id":"q07","no":7,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"How We See the World","pas":"Some people look at life and see what is missing. They count what they don’t have and feel unhappy. Others look at the same life and see what is already there. They notice small joys — a smile, a meal, a friend — and feel rich. The world may not change, but how we see it makes all the difference.","sum":"Because our view shapes emotion, seeing (A) brings sadness while seeing (B) brings peace.","gloss":"우리의 관점이 감정을 형성하기 때문에, 희소함을 보면 슬픔이 생기고, 풍요를 보면 평온함이 찾아온다.","bl":{"A":[{"first":"s","len":8,"sfx":""}],"B":[{"first":"a","len":9,"sfx":""}]},"key":{"A":{"w":"scarcity","acc":["scarcity"],"freq":true,"src":["[1학년] 2025년 1학기 기말 서답형 5번"],"note":""},"B":{"w":"abundance","acc":["abundance"],"freq":false,"src":[],"note":""}},"tr":"어떤 사람들은 삶을 바라볼 때 부족한 것들만 본다. 갖지 못한 것들을 세며 불행함을 느낀다. 하지만 다른 사람들은 같은 삶에서도 이미 있는 것들을 본다. 그들은 작은 기쁨들 — 미소, 식사, 친구 — 에서 풍요를 느낀다. 세상은 변하지 않아도, 그것을 보는 우리의 시선이 모든 것을 바꾼다.","ex":{"flow":"부족한 것을 세면 불행하고, 이미 있는 작은 기쁨을 보면 풍요롭게 느낀다는 내용. 관점에 따라 희소 ↔ 풍요로 감정이 달라진다.","b":{"A":["scarcity 명) 부족, 결핍, 희소성","see what is missing / count what they don’t have","형용사 scarce(부족한), 부사 scarcely(거의 ~않다). 반의어 abundance"],"B":["abundance 명) 풍부함, 풍요","see what is already there / feel rich","형용사 abundant. in abundance = 풍부하게. -ance 철자 주의(abundence ✗)"]}}},{"id":"q08","no":8,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Strong After the Storm","pas":"Life is not always easy. Sometimes we face problems that hurt or tire us. But people can grow through these hard times. Like trees that stand after heavy rain, we become stronger each time we rise again. Real strength is not never falling, but always getting back up.","sum":"Because hard times build (A), they make our strength more (B) and lasting.","gloss":"힘든 시기는 회복력을 길러주기 때문에, 우리의 강인함을 더 견고하고 오래 지속되게 만들어 준다.","bl":{"A":[{"first":"r","len":10,"sfx":""}],"B":[{"first":"d","len":7,"sfx":""}]},"key":{"A":{"w":"resilience","acc":["resilience"],"freq":false,"src":[],"note":""},"B":{"w":"durable","acc":["durable"],"freq":false,"src":[],"note":""}},"tr":"삶은 항상 쉽지 않다. 가끔은 상처를 주거나 우리를 지치게 하는 문제들을 겪는다. 하지만 사람은 그런 어려움 속에서 성장할 수 있다. 큰 비바람 후에도 서 있는 나무처럼, 우리는 다시 일어날 때마다 더 강해진다. 진짜 강함은 넘어지지 않는 것이 아니라, 다시 일어나는 것이다.","ex":{"flow":"어려움 속에서도 다시 일어설 때마다 강해진다는 내용. \"넘어지지 않는 것\"이 아니라 \"다시 일어나는 것\"이 진짜 강함.","b":{"A":["resilience 명) 회복력, 탄력성","we become stronger each time we rise again / always getting back up","형용사 resilient. 시련 뒤 다시 일어서는 힘이라는 뜻으로 요약문에 자주 나옴"],"B":["durable 형) 오래가는, 튼튼한, 내구성 있는","like trees that stand after heavy rain / lasting","dur(지속하다) 어원: duration, endure, during. 명사 durability. 뒤의 and lasting과 짝"]}}},{"id":"q09","no":9,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Price of Renewal","pas":"A city is always rewriting itself. Old buildings become cafés, small shops turn into galleries, and the streets that once echoed with routine now glow with trend. But behind the fresh paint, the people who gave the place its warmth often fade away. Progress can beautify, yet it can also quietly erase.","sum":"Gentrification often appears as (A) but results in quiet (B) of those who first built the community.","gloss":"젠트리피케이션은 종종 포용처럼 보이지만, 결국 그 공동체를 처음 세운 사람들을 조용히 배제하는 결과를 낳는다.","bl":{"A":[{"first":"i","len":9,"sfx":""}],"B":[{"first":"e","len":9,"sfx":""}]},"key":{"A":{"w":"inclusion","acc":["inclusion"],"freq":false,"src":[],"note":""},"B":{"w":"exclusion","acc":["exclusion"],"freq":false,"src":[],"note":""}},"tr":"도시는 늘 스스로를 다시 써 내려간다. 오래된 건물은 카페로, 작은 상점은 갤러리로 바뀌고, 한때 일상의 발자국으로 가득하던 거리는 이제 유행으로 반짝인다. 하지만 새 페인트 뒤에는, 그곳에 온기를 불어넣던 사람들이 사라져간다. 진보는 도시를 아름답게 만들지만, 그 아름다움이 동시에 무언가를 지워버리기도 한다.","ex":{"flow":"도시 재개발(젠트리피케이션)은 겉으로는 새롭고 아름다워 보이지만, 그곳에 온기를 주던 원래 사람들이 조용히 밀려난다는 내용.","b":{"A":["inclusion 명) 포함, 포용","Progress can beautify / glow with trend (겉으로 보이는 모습)","동사 include. 반의어 exclusion과 짝으로 출제. \"포용처럼 보이지만 실제로는 배제\"의 대비"],"B":["exclusion 명) 배제, 제외","the people who gave the place its warmth often fade away / quietly erase","동사 exclude, 형용사 exclusive(배타적인, 독점적인). ex(밖으로)+clud(닫다)"]}}},{"id":"q10","no":10,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"A Quiet Moment","pas":"Life can be busy and noisy. Our thoughts run fast, and we forget to slow down. When we take a short break, our mind starts to rest. After the noise fades, things become easier to understand, like the sky after rain.","sum":"Resting for a while helps (A) tension and brings (B) to the mind.","gloss":"잠시 쉬는 것은 긴장을 해소하는 것을 도와주고, 마음의 명료함을 되찾게 한다.","bl":{"A":[{"first":"r","len":7,"sfx":""}],"B":[{"first":"c","len":7,"sfx":""}]},"key":{"A":{"w":"relieve","acc":["relieve"],"freq":false,"src":[],"note":""},"B":{"w":"clarity","acc":["clarity"],"freq":false,"src":[],"note":""}},"tr":"삶은 바쁘고 시끄럽다. 생각이 너무 빠르게 달려서, 우리는 천천히 멈추는 법을 잊는다. 하지만 잠깐 쉬는 순간, 우리의 마음은 쉬기 시작한다. 소음이 사라진 뒤에는, 모든 것이 비 온 뒤의 하늘처럼 더 분명해진다.","ex":{"flow":"바쁘고 시끄러운 삶에서 잠깐 쉬면 마음이 쉬고, 소음이 가라앉은 뒤에 비 갠 하늘처럼 생각이 분명해진다는 내용.","b":{"A":["relieve 동) (고통·긴장을) 덜어 주다, 완화하다","our mind starts to rest","help (to) + 동사원형 → relieve. 명사 relief(안도, 완화). relieve stress/tension"],"B":["clarity 명) 명료함, 명확성","things become easier to understand, like the sky after rain","형용사 clear, 동사 clarify. bring clarity to ~ = ~을 분명하게 하다"]}}},{"id":"q11","no":11,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Social Media Can Hide a Person’s True Self","pas":"On social media, people often share only the best parts of their lives. They choose good angles, bright filters, and moments that make everything look perfect. Although this can be fun, it sometimes makes others forget that real life includes difficult days too. When people show more honest moments, they help create an online space that feels more human and easier to relate to.","sum":"Social media often shows an (A) image, while people feel closer when others share their (B) selves.","gloss":"소셜미디어는 종종 인위적인 모습만 보여주지만, 사람들은 진짜의 자기 모습을 공유할 때 더 가까움을 느낀다.","bl":{"A":[{"first":"a","len":10,"sfx":""}],"B":[{"first":"g","len":7,"sfx":""}]},"key":{"A":{"w":"artificial","acc":["artificial"],"freq":false,"src":[],"note":""},"B":{"w":"genuine","acc":["genuine"],"freq":true,"src":["[1학년] 2025년 1학기 기말 서답형 5번"],"note":""}},"tr":"소셜미디어에서 사람들은 자신의 삶에서 가장 좋은 순간들만 올리는 경우가 많다. 좋은 각도, 밝은 필터, 완벽해 보이는 순간들을 선택한다. 이런 방식은 재미있지만, 현실에는 힘든 날도 있다는 사실을 잊게 만들기도 한다. 사람들이 조금 더 솔직한 모습을 보여줄 때, 온라인 공간은 더 인간적이고 공감 가능한 장소가 된다.","ex":{"flow":"SNS에는 좋은 각도·필터로 완벽해 보이는 순간만 올라오지만, 솔직한 모습을 보일 때 더 인간적이고 공감하기 쉬워진다는 내용.","b":{"A":["artificial 형) 인위적인, 꾸며낸","good angles, bright filters, moments that make everything look perfect","art(기술)+fic(만들다) → 사람이 만든. an 뒤라 모음으로 시작하는 a-. 반의어 natural, genuine"],"B":["genuine 형) 진짜의, 진실한","show more honest moments / feels more human","genuine self = 진짜 자기 모습. 발음 [제뉴인]. 유의어 authentic, real"]}}},{"id":"q12","no":12,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Thinking Before Acting","pas":"When we are angry, we often say or do things we later regret. Strong feelings can make our minds cloudy. If we stop for a moment and take a deep breath, we can see the situation more clearly. Calm thinking helps us make better choices and keeps us from hurting others.","sum":"Because emotions (A) judgment, taking time to think keeps the mind (B).","gloss":"감정이 판단을 흐리게 하기 때문에, 잠시 생각할 시간을 가지면 마음을 이성적으로 유지할 수 있다.","bl":{"A":[{"first":"b","len":4,"sfx":""}],"B":[{"first":"r","len":8,"sfx":""}]},"key":{"A":{"w":"blur","acc":["blur"],"freq":false,"src":[],"note":""},"B":{"w":"rational","acc":["rational"],"freq":false,"src":[],"note":""}},"tr":"우리가 화가 날 때, 종종 나중에 후회할 말이나 행동을 한다. 강한 감정은 마음을 흐리게 만든다. 하지만 잠시 멈추고 깊게 숨을 쉬면, 상황이 더 분명하게 보인다. 차분한 생각은 더 나은 선택을 하게 하고, 다른 사람을 다치게 하지 않도록 돕는다.","ex":{"flow":"화가 나면 생각이 흐려져 후회할 말과 행동을 하게 되지만, 잠깐 멈추고 숨을 쉬면 상황을 더 분명히 보고 더 나은 선택을 한다는 내용.","b":{"A":["blur 동) 흐리게 하다","Strong feelings can make our minds cloudy","주어 emotions(복수) → 원형 blur. 명사로 \"흐릿한 형체\". 과거형 blurred(r 두 번)"],"B":["rational 형) 이성적인, 합리적인","Calm thinking / see the situation more clearly","keep + 목적어 + 형용사 → rational. 반의어 irrational, emotional. 명사 reason"]}}},{"id":"q13","no":13,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"When Truth Waits","pas":"Sometimes it’s hard to know what’s real. People may hide facts or twist stories to fit their own side. The truth can stay quiet for a while, covered by noise and confusion. But with time, what was hidden always finds a way to be seen again.","sum":"Because lies can make truth (A) and hidden, patience and (B) reveal it again.","gloss":"거짓이 진실을 모호하게 하고,(=흐리고) 숨길 수 있지만, 인내와 정직은 다시 그것을 드러낸다.","bl":{"A":[{"first":"o","len":7,"sfx":""}],"B":[{"first":"h","len":7,"sfx":""}]},"key":{"A":{"w":"obscure","acc":["obscure"],"freq":false,"src":[],"note":""},"B":{"w":"honesty","acc":["honesty"],"freq":false,"src":[],"note":""}},"tr":"무엇이 진실인지 알기 어려울 때가 있다. 사람들이 사실을 숨기거나, 자신의 편에 맞게 이야기를 바꾸기도 한다. 진실은 잠시 소음과 혼란 속에 가려져 있을 수 있다. 그러나 시간이 지나면, 숨겨졌던 것(hidden)은 결국 다시 드러난다.","ex":{"flow":"사람들이 사실을 숨기거나 왜곡해 진실이 한동안 가려지지만, 시간이 지나면 숨겨진 것은 다시 드러난다는 내용.","b":{"A":["obscure 형) 모호한, 잘 보이지 않는 (동: 가리다)","covered by noise and confusion / hide facts or twist stories","make + 목적어 + 형용사(obscure) and hidden. 동사로 \"흐리게 하다, 가리다\"도 가능"],"B":["honesty 명) 정직","with time, what was hidden … seen again (거짓 lies와 대비)","patience and honesty — 명사끼리 병렬. 형용사 honest. h는 묵음이라 an honest ~"]}}},{"id":"q14","no":14,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Beyond the Comfort Zone","pas":"Our comfort zone is like a warm, small garden. It feels safe, but the same flowers bloom there every day. Outside the wall, there are new paths, strange colors, and different winds. Only by stepping out can we see how big the world really is.","sum":"While the (A) can be scary, (B) turns fear into learning and growth.","gloss":"미지는 두려울 수 있지만, 탐험은 그 두려움을 배움과 성장으로 바꾼다.","bl":{"A":[{"first":"u","len":7,"sfx":""}],"B":[{"first":"e","len":11,"sfx":""}]},"key":{"A":{"w":"unknown","acc":["unknown"],"freq":false,"src":[],"note":""},"B":{"w":"exploration","acc":["exploration"],"freq":false,"src":[],"note":""}},"tr":"우리의 안전지대는 따뜻하고 작은 정원과 같다. 그 안은 안전하게 느껴지지만, 매일 같은 꽃만 핀다. 벽 밖에는 새로운 길, 낯선 색, 다른 바람이 있다. 그 벽을 넘어설 때에야, 세상이 얼마나 넓은지 알 수 있다.","ex":{"flow":"안전지대는 작고 따뜻한 정원과 같지만, 벽 밖으로 나가야 세상이 얼마나 넓은지 볼 수 있다는 내용.","b":{"A":["unknown 명) 미지의 것 (the unknown)","Outside the wall … new paths, strange colors, different winds","the + 형용사 = 명사(the unknown = 알려지지 않은 것). 반의어 the familiar"],"B":["exploration 명) 탐험, 탐구","Only by stepping out","동사 explore. 문장 주어 자리 → 명사. 철자 -ration"]}}},{"id":"q15","no":15,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Small Steps, Big Change","pas":"Great things don’t happen all at once. A tree doesn’t grow in a day, and skills aren’t learned overnight. Every small effort adds up, just like drops of water filling a cup. In time, what once looked small becomes something strong and lasting.","sum":"Success grows as small efforts (A) over time.","gloss":"","bl":{"A":[{"first":"a","len":10,"sfx":""}]},"key":{"A":{"w":"accumulate","acc":["accumulate"],"freq":false,"src":[],"note":""}},"tr":"위대한 일은 한순간에 이루어지지 않는다. 나무도 하루아침에 자라지 않고, 기술도 하룻밤에 익히지 못한다. 작은 노력 하나하나가 모여, 마치 물방울이 컵을 채우듯 큰 힘이 된다. 시간이 지나면, 작아 보이던 것들이 강하고 오래가는 결과로 변한다.","ex":{"flow":"위대한 일은 한 번에 이루어지지 않고, 작은 노력이 물방울이 컵을 채우듯 쌓여 강하고 오래가는 결과가 된다는 내용.","b":{"A":["accumulate 동) 축적되다, 쌓이다","Every small effort adds up, just like drops of water filling a cup","as + 주어(small efforts) + 동사 → 원형 accumulate. 명사 accumulation. ac-cu-mu-late 철자 c는 하나"]}}},{"id":"q16","no":16,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Invisible Paths","pas":"Diseases can spread quickly, even when we can’t see them. A single touch or careless moment can carry germs from one person to another. But the same hands that spread illness can also stop it — with care, masks, and kindness. When we protect each other, we break the chain that keeps sickness alive.","sum":"Care and cooperation help stop the (A) of disease.","gloss":"","bl":{"A":[{"first":"t","len":12,"sfx":""},{"first":"c","len":9,"sfx":""}]},"key":{"A":{"w":"transmission / contagion","acc":["transmission","contagion"],"freq":false,"src":[],"note":""}},"tr":"질병은 우리가 보지 못해도 빠르게 퍼질 수 있다. 한 번의 접촉이나 작은 부주의가 세균을 사람에서 사람으로 옮길 수 있다. 하지만 병을 퍼뜨리던 그 손이, 마스크와 배려로 병을 막을 수도 있다. 서로를 지킬 때, 우리는 질병의 고리를 끊는다.","ex":{"flow":"병은 눈에 보이지 않게 손길 하나로 퍼지지만, 같은 손이 배려와 마스크로 병을 막을 수도 있다는 내용.","b":{"A":["transmission / contagion 명) 전염, 전파","spread quickly / carry germs from one person to another / break the chain","두 단어 모두 정답(t 12칸 = transmission, c 9칸 = contagion). 동사 transmit, 형용사 contagious"]}}},{"id":"q17","no":17,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Learning to Stand Alone","pas":"As we grow up, people stop making choices for us. We begin to decide what to study, who to trust, and where to go. It can feel scary, but it also means freedom. When we learn from our own choices — even mistakes — we become stronger.","sum":"Because (A) allows us to decide and learn for ourselves, it helps us become (B).","gloss":"자율성이 우리 스스로 결정하고 배우게 해주기 때문에, 독립적인 사람이 될 수 있다.","bl":{"A":[{"first":"a","len":8,"sfx":""}],"B":[{"first":"i","len":11,"sfx":""}]},"key":{"A":{"w":"autonomy","acc":["autonomy"],"freq":false,"src":[],"note":""},"B":{"w":"independent","acc":["independent"],"freq":false,"src":[],"note":""}},"tr":"우리가 성장할수록, 다른 사람들이 대신 선택해주는 일은 줄어든다. 이제 우리는 무엇을 배울지, 누구를 믿을지, 어디로 갈지 스스로 결정해야 한다. 그건 두려울 수 있지만, 동시에 자유를 의미한다. 실수조차도 직접 선택을 통해 배우는 순간, 우리는 더 강한 사람이 된다.","ex":{"flow":"자라면서 스스로 무엇을 배우고 누구를 믿을지 결정하게 되고, 자기 선택(실수까지)으로 배우며 더 강해진다는 내용.","b":{"A":["autonomy 명) 자율성, 자주성","people stop making choices for us / We begin to decide","auto(스스로)+nomy(법칙). 형용사 autonomous. Because 다음 주어 자리 → 명사"],"B":["independent 형) 독립적인, 자립한","we become stronger / stand alone","become + 형용사. 반의어 dependent. 명사 independence (-ence)"]}}},{"id":"q18","no":18,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"From Thought to Action","pas":"Ideas begin in the mind like small sparks. They are invisible — we can’t touch them or see them. But when we act, they take shape: a song, a building, a smile. Dreams need hands to become real, and actions need dreams to have meaning.","sum":"While dreams are (A), their results are (B) and shape the world.","gloss":"꿈은 추상적이지만, 그 결과는 구체적(만질수 있는)이며 세상을 바꾼다.","bl":{"A":[{"first":"a","len":8,"sfx":""}],"B":[{"first":"t","len":8,"sfx":""}]},"key":{"A":{"w":"abstract","acc":["abstract"],"freq":false,"src":[],"note":""},"B":{"w":"tangible","acc":["tangible"],"freq":false,"src":[],"note":""}},"tr":"생각은 작은 불꽃처럼 마음속에서 시작된다. 그것들은 눈에 보이지 않고, 손으로 잡을 수도 없다. 하지만 행동으로 옮길 때, 그것들은 노래, 건물, 미소처럼 형태를 가진다. 꿈은 손이 있어야 현실이 되고, 행동은 꿈이 있어야 의미를 가진다.","ex":{"flow":"생각은 눈에 보이지 않는 작은 불꽃이지만, 행동하면 노래·건물·미소처럼 형태를 갖춘다는 내용. 추상 ↔ 구체의 대비.","b":{"A":["abstract 형) 추상적인","They are invisible — we can’t touch them or see them","명사로 \"요약(문)\"이라는 뜻도 있음. 반의어 concrete"],"B":["tangible 형) 만질 수 있는, 실재하는, 구체적인","they take shape: a song, a building, a smile / become real","tang(만지다) 어원. 반의어 intangible. tangible results = 가시적인 성과"]}}},{"id":"q19","no":19,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Trap of Comfort","pas":"People love what feels familiar. The same road, the same food, the same people — it feels safe and easy. But if we never try something new, we stop growing. Life becomes bigger only when we step beyond what we are used to.","sum":"People become (A) to comfort, but (B) begins beyond it.","gloss":"사람들은 편안함에 익숙해지지만, 성장은 그 너머에서 시작된다.","bl":{"A":[{"first":"a","len":10,"sfx":""}],"B":[{"first":"g","len":6,"sfx":""}]},"key":{"A":{"w":"accustomed","acc":["accustomed"],"freq":false,"src":[],"note":""},"B":{"w":"growth","acc":["growth"],"freq":false,"src":[],"note":""}},"tr":"사람들은 익숙한 것(familiar한 것) 을 좋아한다. 같은 길, 같은 음식, 같은 사람들 — 그것들은 편하고 안전하게 느껴진다. 하지만 새로운 것을 시도하지 않으면, 우리는 더 이상 성장하지 않는다. 삶은 우리가 익숙한(used to) 것 너머로 나아갈 때 비로소 커진다.","ex":{"flow":"익숙한 것은 안전하고 편하지만, 새로운 것을 시도하지 않으면 성장이 멈추고, 익숙한 것을 넘어설 때 삶이 커진다는 내용.","b":{"A":["accustomed 형) 익숙한","People love what feels familiar / what we are used to","be/become accustomed to + 명사(-ing) = ~에 익숙하다(be used to와 같음). c 두 개"],"B":["growth 명) 성장","we stop growing / Life becomes bigger","but 뒤 문장의 주어 → 명사. 동사 grow"]}}},{"id":"q20","no":20,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Different Voices","pas":"People don’t always agree. One person’s truth can be another person’s lie. When we share strong opinions, arguments often follow. But listening first can turn conflict into understanding — even when we still disagree.","sum":"While (A) issues create conflict, (B) can turn it into growth.","gloss":"논란이 있는 문제들은 갈등을 일으키지만, 대화는 그것을 성장으로 바꿀 수 있다.","bl":{"A":[{"first":"c","len":13,"sfx":""}],"B":[{"first":"d","len":8,"sfx":""}]},"key":{"A":{"w":"controversial","acc":["controversial"],"freq":false,"src":[],"note":""},"B":{"w":"dialogue","acc":["dialogue"],"freq":false,"src":[],"note":""}},"tr":"사람들은 항상 같은 생각을 하지 않는다. 한 사람의 진실이 다른 사람에게는 거짓처럼 보일 수도 있다. 강한 의견을 나누면, 종종 논쟁이 생긴다. 하지만 먼저 귀 기울이는 태도는 충돌을 이해로 바꿀 수 있다 — 비록 여전히 생각이 다르더라도.","ex":{"flow":"강한 의견을 나누면 논쟁이 생기지만, 먼저 들으면 의견이 달라도 갈등을 이해로 바꿀 수 있다는 내용.","b":{"A":["controversial 형) 논란이 많은","People don’t always agree / strong opinions, arguments often follow","issues를 꾸미는 형용사. 명사 controversy. contro(반대)+vers(돌다)"],"B":["dialogue 명) 대화","listening first","can turn 앞의 주어 → 명사. 미국식 철자 dialog도 쓰지만 칸 수(8칸)에 맞게 dialogue"]}}}]},{"r":2,"qs":[{"id":"q01","no":1,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Helping with a Gentle Hand","pas":"Sometimes people need help but are too proud to ask. When we step in, our way matters more than our words. A kind action or a quiet offer can change someone’s day. True help is not control — it is a gentle touch born from care.","sum":"The best (A) comes with (B), not control.","gloss":"가장 좋은 개입은 통제가 아닌 관대함에서 나온다.","bl":{"A":[{"first":"i","len":12,"sfx":""}],"B":[{"first":"g","len":10,"sfx":""}]},"key":{"A":{"w":"intervention","acc":["intervention"],"freq":false,"src":[],"note":""},"B":{"w":"generosity","acc":["generosity"],"freq":false,"src":[],"note":""}},"tr":"때로는 사람들이 도움이 필요하지만, 자존심 때문에 말하지 못할 때가 있다. 그럴 때 우리가 개입하는 방식은 말보다 더 중요하다. 따뜻한 행동 하나나 조용한 제안 하나가 누군가의 하루를 바꿀 수 있다. 진정한 도움은 통제가 아니라, 배려에서 나온 부드러운 손길이다.","ex":{"flow":"도움이 필요한 사람에게 다가갈 때는 말보다 방식이 중요하며, 진짜 도움은 통제가 아니라 배려에서 나온 부드러운 손길이라는 내용.","b":{"A":["intervention 명) 개입, 중재","When we step in / True help","step in = intervene(개입하다)의 명사형. inter(사이에)+ven(오다)"],"B":["generosity 명) 너그러움, 관대함","A kind action or a quiet offer / a gentle touch born from care","형용사 generous. come with ~ = ~이 따르다, ~에서 나오다. not control과 대비"]}}},{"id":"q02","no":2,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Language of Listening","pas":"Real communication is not only about speaking. It also means listening, even when we don’t agree. When we respect other voices, we learn new ways to see the world. Understanding grows when words meet kindness.","sum":"Because (A) allows us to listen and respect others, it creates stronger (B).","gloss":"관용이 타인을 존중하고 들어주게 하기 때문에, 더 깊은 연결이 생긴다.","bl":{"A":[{"first":"t","len":9,"sfx":""}],"B":[{"first":"c","len":10,"sfx":""}]},"key":{"A":{"w":"tolerance","acc":["tolerance"],"freq":false,"src":[],"note":""},"B":{"w":"connection","acc":["connection"],"freq":false,"src":[],"note":""}},"tr":"진짜 소통은 단지 말하는 것만이 아니다. 서로 동의하지 않아도 들어주는 것, 그것이 진짜 소통이다. 다른 사람의 목소리를 존중할 때, 우리는 세상을 새롭게 보는 법을 배운다. 말이 친절과 만날 때, 이해가 자라난다.","ex":{"flow":"의견이 달라도 듣고, 다른 목소리를 존중할 때 이해가 자란다는 내용. 관용 → 존중·경청 → 연결.","b":{"A":["tolerance 명) 관용, 너그러움","listening, even when we don’t agree / respect other voices","동사 tolerate, 형용사 tolerant. 의학·공학에선 \"내성, 허용치\""],"B":["connection 명) 연결, 유대","Understanding grows when words meet kindness","create stronger connection(s) = 더 깊은 유대를 만들다. 동사 connect"]}}},{"id":"q03","no":3,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Following or Thinking","pas":"In many groups, people try to fit in. They wear the same clothes, share the same opinions, and follow the same trends. It feels safe to be like everyone else, but something is lost — our own voice. Real growth begins when we stop copying and start thinking for ourselves.","sum":"Because (A) feels safe, many follow others instead of thinking freely.","gloss":"순응이 안전하게 느껴지기 때문에, 많은 사람들은 자유롭게 생각하기보다 남을 따른다.","bl":{"A":[{"first":"c","len":10,"sfx":""}]},"key":{"A":{"w":"conformity","acc":["conformity"],"freq":false,"src":[],"note":""}},"tr":"많은 집단 속에서 사람들은 어울리기 위해 비슷해지려 한다. 같은 옷을 입고, 같은 생각을 나누고, 같은 유행을 따른다. 남들과 같으면 안전하게 느껴지지만, 그 과정에서 잃는 것이 있다 — 바로 자신의 목소리다. 진짜 성장은 따라 하기보다 스스로 생각하기 시작할 때부터다.","ex":{"flow":"남들과 같은 옷·의견·유행을 따르면 안전하게 느껴지지만 자기 목소리를 잃는다는 내용.","b":{"A":["conformity 명) 순응, (집단에) 따름","try to fit in / same clothes, same opinions, same trends / be like everyone else","동사 conform (to) = ~에 따르다. con(함께)+form(형태) → 같은 모양이 됨. 반의어 nonconformity"]}}},{"id":"q04","no":4,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Power Beneath the Surface","pas":"In many fields, people focus on visible results — high scores, quick success, or public praise. However, what truly supports those outcomes often stays unseen. Like the roots of a tree that hold it firm during storms, quiet practice and patience form the real strength of achievement. Without such inner effort, even great talent cannot last for long.","sum":"True success stands on the (A) of patience and (B) effort.","gloss":"진정한 성공은 인내와 꾸준한 노력이란 기초 위에 존재한다.","bl":{"A":[{"first":"f","len":10,"sfx":""}],"B":[{"first":"s","len":6,"sfx":""}]},"key":{"A":{"w":"foundation","acc":["foundation"],"freq":false,"src":[],"note":""},"B":{"w":"steady","acc":["steady"],"freq":false,"src":[],"note":""}},"tr":"많은 분야에서 사람들은 눈에 보이는 결과 — 높은 점수, 빠른 성공, 대중의 칭찬에 집중한다. 그러나 그런 결과를 진짜로 지탱하는 것은 대개 눈에 보이지 않는다. 폭풍 속에서도 나무를 버티게 하는 뿌리처럼, 조용한 연습과 인내가 성취의 진짜 힘을 만든다. 이런 내적인 노력이 없다면, 아무리 큰 재능도 오래 지속될 수 없다.","ex":{"flow":"눈에 보이는 결과를 실제로 받쳐 주는 것은 나무 뿌리처럼 보이지 않는 연습과 인내라는 내용.","b":{"A":["foundation 명) 기초, 토대","the roots of a tree that hold it firm / form the real strength","stand on the foundation of ~ = ~의 토대 위에 서다. 동사 found(설립하다)"],"B":["steady 형) 꾸준한, 한결같은","quiet practice and patience / inner effort","effort를 꾸미는 형용사. 부사 steadily. 유의어 consistent"]}}},{"id":"q05","no":5,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Value of Struggle","pas":"Many people try to avoid mistakes, thinking that failure means weakness. However, new ideas rarely come from ease or perfection. When we face problems, our minds start to think in different ways.","sum":"Creativity grows from (A) and challenge, not from (B).","gloss":"창의성은 역경과 도전에서 자라며, 편안함 속에서는 자라지 않는다.","bl":{"A":[{"first":"a","len":9,"sfx":""}],"B":[{"first":"c","len":7,"sfx":""}]},"key":{"A":{"w":"adversity","acc":["adversity"],"freq":false,"src":[],"note":""},"B":{"w":"comfort","acc":["comfort"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 실수를 피하려 하고, 실패를 약함의 표시로 생각한다. 그러나 새로운 아이디어는 편안함이나 완벽함 속에서 잘 나오지 않는다. 문제에 부딪힐 때, 우리의 사고는 다른 방향으로 확장되기 시작한다.","ex":{"flow":"실패를 피하려 하지만, 새로운 생각은 편안함·완벽함이 아니라 문제를 마주할 때 나온다는 내용.","b":{"A":["adversity 명) 역경, 고난","When we face problems / failure","adverse(불리한)의 명사. advertise와 혼동 주의. in the face of adversity = 역경에 맞서"],"B":["comfort 명) 편안함, 위안","new ideas rarely come from ease or perfection","ease를 comfort로 바꿔 쓴 패러프레이즈. comfortable(형)과 구분"]}}},{"id":"q06","no":6,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"What We Leave Behind","pas":"Every generation receives more than just life itself. We inherit languages, stories, and ways of thinking from those who came before us. But inheritance is not one-way — what we create today becomes the ground our children will stand on.","sum":"Because culture and values are (A), they influence how our (B)(s) will live.","gloss":"문화와 가치가 물려받아지기 때문에, 그것이 우리의 후손들의 삶에 영향을 미친다.","bl":{"A":[{"first":"i","len":9,"sfx":""}],"B":[{"first":"d","len":10,"sfx":""}]},"key":{"A":{"w":"inherited","acc":["inherited"],"freq":false,"src":[],"note":""},"B":{"w":"descendant(s)","acc":["descendant(s)"],"freq":false,"src":[],"note":""}},"tr":"생각은 작은 불꽃처럼 마음속에서 시작된다. 그것들은 눈에 보이지 않고, 손으로 잡을 수도 없다. 하지만 행동으로 옮길 때, 그것들은 노래, 건물, 미소처럼 형태를 가진다. 꿈은 손이 있어야 현실이 되고, 행동은 꿈이 있어야 의미를 가진다.","ex":{"flow":"우리는 언어·이야기·사고방식을 앞 세대에게 물려받고, 오늘 만든 것이 다음 세대가 설 땅이 된다는 내용.","b":{"A":["inherited 형) 물려받은, 상속된","We inherit languages, stories, and ways of thinking","are + p.p.(수동) → inherited. 명사 inheritance, heritage(유산)"],"B":["descendant 명) 자손, 후손","our children / every generation","빈칸 뒤 (s)가 있으니 descendant(s). 반의어 ancestor. de(아래로)+scend(오르다) → 아래로 내려가는 사람"]}}},{"id":"q07","no":7,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Cracks of Light","pas":"People often try to hide their cracks — the parts of themselves that seem broken or less than perfect. Yet, those cracks let the light in. They remind us that strength is not about never falling, but about rising again each time we do. What makes us real is not flawlessness, but the courage to grow through our mistakes.","sum":"Even when we feel (A), accepting our (B) helps us grow stronger.","gloss":"부족함을 느낄 때조차, 불완전함을 받아들이면 더 강해질 수 있다.","bl":{"A":[{"first":"i","len":10,"sfx":""}],"B":[{"first":"i","len":12,"sfx":""}]},"key":{"A":{"w":"inadequate","acc":["inadequate"],"freq":false,"src":[],"note":""},"B":{"w":"imperfection","acc":["imperfection"],"freq":false,"src":[],"note":""}},"tr":"사람들은 종종 자신의 금이 간 부분, 즉 부서지거나 완벽하지 않은 부분을 감추려 한다. 그러나 그 틈으로 빛이 들어온다. 그것은 강함이란 절대 넘어지지 않는 것이 아니라, 넘어질 때마다 다시 일어나는 것임을 상기시킨다. 우리를 진짜로 만드는 것은 흠 없는 완벽함이 아니라, 실수를 통해 성장하려는 용기다.","ex":{"flow":"사람들은 자신의 흠을 숨기려 하지만 그 틈으로 빛이 들어오며, 완벽함이 아니라 실수를 통해 성장하는 용기가 우리를 진짜로 만든다는 내용.","b":{"A":["inadequate 형) 부족한, 불충분한","seem broken or less than perfect","feel + 형용사. in(부정)+adequate(충분한). 명사 inadequacy"],"B":["imperfection 명) 불완전함, 결점","cracks / not flawlessness","accepting our ~ (동명사의 목적어) → 명사. 형용사 imperfect"]}}},{"id":"q08","no":8,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Seeing Yourself in Others","pas":"When we see someone struggling, we often associate their situation with our own memories. This simple link helps us imagine what they might be feeling. Through such moments, we realize that emotions are shared more than we think. Understanding others begins when we see a part of ourselves in them.","sum":"By (A) our own experiences to others’, we build (B) and understanding.","gloss":"자신의 경험을 타인과 관련지음으로써, 우리는 공감(감정이입)과 이해를 쌓는다.","bl":{"A":[{"first":"r","len":8,"sfx":""}],"B":[{"first":"e","len":7,"sfx":""}]},"key":{"A":{"w":"relating","acc":["relating"],"freq":false,"src":[],"note":""},"B":{"w":"empathy","acc":["empathy"],"freq":false,"src":[],"note":""}},"tr":"우리가 어려움을 겪는 사람을 볼 때, 종종 그들의 상황을 우리의 기억과 연관시킨다(associate). 이 단순한 연결이 그들이 어떤 감정을 느끼는지 상상하게 해준다. 이런 순간들을 통해 감정은 우리가 생각하는 것보다 훨씬 더 많이 공유된다는 걸 깨닫게 된다. 타인을 이해하는 것은, 그 안에서 나의 일부분을 볼 때 시작된다.","ex":{"flow":"힘들어하는 사람을 보면 자신의 기억과 연결해 그 사람의 감정을 상상하게 되고, 그 속에서 이해가 시작된다는 내용.","b":{"A":["relating 동) 관련짓다 (relate A to B)","associate their situation with our own memories","By + 동명사 → relating. relate A to B = A를 B와 관련짓다(associate A with B의 패러프레이즈)"],"B":["empathy 명) 공감, 감정 이입","imagine what they might be feeling","em(안으로)+pathy(감정). sympathy(동정)와 구분. 형용사 empathetic"]}}},{"id":"q09","no":9,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Half-Filled Cup","pas":"Life often feels like a cup that’s only half full. We wait for the moment when everything will finally feel complete. But even with space left inside, the cup still holds something valuable. Maybe what’s missing gives us the reason to keep filling it.","sum":"While (A) feels heavy, an (B) life gives hope and direction.","gloss":"비어있음은 무겁게 느껴지지만, 끝나지 않은 삶은 오히려 희망과 방향을 준다.","bl":{"A":[{"first":"e","len":9,"sfx":""}],"B":[{"first":"u","len":10,"sfx":""}]},"key":{"A":{"w":"emptiness","acc":["emptiness"],"freq":false,"src":[],"note":""},"B":{"w":"unfinished","acc":["unfinished"],"freq":false,"src":[],"note":""}},"tr":"삶은 종종 절반만 찬 컵처럼 느껴진다. 우리는 모든 것이 완전히 채워지는 순간을 기다린다. 하지만 비어 있는 부분이 있더라도, 그 안에는 여전히 소중한 것이 담겨 있다. 어쩌면 그 부족한 부분이 바로 우리가 계속 채워가야 할 이유일지도 모른다.","ex":{"flow":"삶은 반쯤 찬 컵 같고, 비어 있는 부분이 오히려 계속 채워 갈 이유가 된다는 내용.","b":{"A":["emptiness 명) 공허함, 비어 있음","only half full / what’s missing","주어 자리 → 명사. empty(형)+-ness. y → i 철자 변화"],"B":["unfinished 형) 끝나지 않은, 미완성의","with space left inside / the reason to keep filling it","an 뒤 모음 u. 미완성이라 희망과 방향이 생긴다는 역설"]}}},{"id":"q10","no":10,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Power of Steady Effort","pas":"Many people start with strong motivation but lose energy after a few days. They expect quick results and stop when progress feels slow. However, real improvement is built step by step, not all at once. Without steady effort, even the best plan loses its power.","sum":"Because unsteady action leads to (A), only (B) effort brings real results.","gloss":"꾸준하지 않은 행동은 비효율성으로 이어지기 때문에, 일관된 노력이 진짜 결과를 낳는다.","bl":{"A":[{"first":"i","len":15,"sfx":""}],"B":[{"first":"c","len":10,"sfx":""}]},"key":{"A":{"w":"ineffectiveness","acc":["ineffectiveness"],"freq":false,"src":[],"note":""},"B":{"w":"consistent","acc":["consistent"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 강한 의지로 시작하지만, 며칠 후면 그 열정을 잃는다. 빠른 결과를 기대하다가, 진전이 느리면 그만두기 때문이다. 그러나 진짜 향상은 한 번에 이루어지는 것이 아니라, 한 걸음씩 쌓이는 것이다. 꾸준함이 없으면, 아무리 좋은 계획도 힘을 잃는다.","ex":{"flow":"처음엔 의욕적이어도 며칠 만에 지치고 멈추지만, 진짜 발전은 한 걸음씩 쌓이며 꾸준함 없이는 어떤 계획도 힘을 잃는다는 내용.","b":{"A":["ineffectiveness 명) 효과 없음, 비효율","even the best plan loses its power","in+effective+ness, 15칸 철자 길이 주의. lead to + 명사"],"B":["consistent 형) 일관된, 꾸준한","steady effort / step by step","명사 consistency. 유의어 steady, constant"]}}},{"id":"q11","no":11,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Beyond Short Gains","pas":"People often choose what brings quick comfort or reward. However, the easiest path is not always the best one. Real success grows from patience and steady effort, not from short-term wins. What feels hard today may become the most rewarding decision tomorrow.","sum":"Because patience builds (A) results, it becomes the truly (B) choice.","gloss":"인내가 지속적인 결과를 만들기 때문에, 그것이 진정으로 유리한 선택이 된다.","bl":{"A":[{"first":"l","len":7,"sfx":""}],"B":[{"first":"a","len":12,"sfx":""}]},"key":{"A":{"w":"lasting","acc":["lasting"],"freq":false,"src":[],"note":""},"B":{"w":"advantageous","acc":["advantageous"],"freq":false,"src":[],"note":""}},"tr":"사람들은 종종 빠른 편안함이나 보상을 주는 선택을 한다. 하지만 가장 쉬운 길이 언제나 가장 좋은 길은 아니다. 진정한 성공은 단기적인 승리가 아니라, 인내와 꾸준한 노력에서 자란다. 오늘은 힘들게 느껴지는 선택이 내일은 가장 큰 보상이 될 수도 있다.","ex":{"flow":"사람들은 빠른 보상을 고르지만, 진짜 성공은 인내와 꾸준함에서 자라고 오늘 힘든 선택이 내일 가장 보람 있는 결정이 된다는 내용.","b":{"A":["lasting 형) 오래가는, 지속적인","not from short-term wins","형용사로 쓰이는 -ing. short-term과 대비. 유의어 enduring, long-term"],"B":["advantageous 형) 유리한, 이로운","the most rewarding decision tomorrow","advantage+-ous. e를 빼지 않고 -geous 철자. 반의어 disadvantageous"]}}},{"id":"q12","no":12,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"From the Particular to the Whole","pas":"Great ideas often start from small experiences. A single story, a single problem, or a single act of kindness can reveal a truth that belongs to everyone. When we look closely at one life, we often see patterns that exist in many others. The local becomes global when we recognize ourselves in it.","sum":"(A) experiences can reveal (B) truths about human life.","gloss":"","bl":{"A":[{"first":"S","len":8,"sfx":""}],"B":[{"first":"u","len":9,"sfx":""}]},"key":{"A":{"w":"Specific","acc":["Specific"],"freq":false,"src":[],"note":""},"B":{"w":"universal","acc":["universal"],"freq":false,"src":[],"note":""}},"tr":"위대한 생각은 종종 작은 경험에서 시작된다. 하나의 이야기, 문제, 혹은 친절한 행동이 모두에게 적용되는 진리를 드러낼 수 있다. 한 사람의 삶을 자세히 들여다보면, 그 안에서 많은 이들이 공유하는 패턴을 발견할 수 있다. 우리가 그 안에서 자신을 볼 때, 개인적인 것이 보편적인 것으로 변한다.","ex":{"flow":"하나의 이야기·문제처럼 작은 경험이 모두에게 해당하는 진리를 드러낸다는 내용. 개별 ↔ 보편의 대비.","b":{"A":["Specific 형) 구체적인, 특정한","A single story, a single problem / one life / The local","문장 맨 앞이라 대문자 S. 명사 specification, 동사 specify"],"B":["universal 형) 보편적인","a truth that belongs to everyone / patterns that exist in many others / global","universe(우주)+-al. 명사 universality"]}}},{"id":"q13","no":13,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Different Ways to Say the Same Heart","pas":"People show love in many ways. Some say it with words, others through actions or quiet care. Culture and personality shape how we express warmth, but the feeling behind it stays the same. Affection needs no single form — sincerity makes every gesture meaningful.","sum":"Though people express love differently, their feelings are (A) in sincerity.","gloss":"비록 사람들이 사랑을 표현하는 방식은 다르지만, 그 감정의 진정성에 있어 동등한 가치를 가진다.","bl":{"A":[{"first":"e","len":10,"sfx":""}]},"key":{"A":{"w":"equivalent","acc":["equivalent"],"freq":false,"src":[],"note":""}},"tr":"사람들은 사랑을 표현하는 방식이 서로 다르다. 어떤 이는 말로, 또 다른 이는 행동이나 조용한 배려로 그것을 전한다. 문화와 성격이 따뜻함의 표현 방식을 결정하지만, 그 안의 진심은 같다. 사랑은 하나의 형태로만 존재하지 않으며, 진심이 모든 표현에 의미를 부여한다.","ex":{"flow":"사랑을 표현하는 방식은 문화와 성격에 따라 다르지만, 그 뒤의 마음과 진정성은 같다는 내용.","b":{"A":["equivalent 형) 동등한, 맞먹는","the feeling behind it stays the same","equi(같은)+val(가치). be equivalent to ~ = ~와 같다. 명사로 \"같은 것, 등가물\""]}}},{"id":"q14","no":14,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"The Limits of Words","pas":"Language helps us share our thoughts and feelings. Yet, words can never capture everything we mean. Some emotions are too deep or too complex to explain fully. That is why silence, art, or even a look can sometimes say more than speech.","sum":"Language is (A) in expressing the full depth of human emotion.","gloss":"언어는 인간의 감정을 완전히 표현하기에는 부족하다.","bl":{"A":[{"first":"d","len":9,"sfx":""}]},"key":{"A":{"w":"deficient","acc":["deficient"],"freq":false,"src":[],"note":""}},"tr":"언어는 우리가 생각과 감정을 나누도록 도와준다. 하지만 말로는 우리가 전하고 싶은 모든 것을 담을 수 없다. 어떤 감정은 너무 깊거나 복잡해서 완전히 설명할 수 없기 때문이다. 그래서 때로는 침묵이나 예술, 혹은 한 번의 눈길이 말보다 더 많은 것을 전달한다.","ex":{"flow":"말은 생각과 감정을 나누게 해 주지만, 너무 깊거나 복잡한 감정은 완전히 담지 못한다는 내용.","b":{"A":["deficient 형) 부족한, 결핍된","words can never capture everything we mean / too deep or too complex to explain fully","be deficient in ~ = ~이 부족하다. 명사 deficiency. ie 철자 주의"]}}},{"id":"q15","no":15,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Strength of Difference","pas":"In nature, no two living things are exactly the same. This difference helps species survive when the world changes. If every animal were alike, one single disease could destroy them all. Life continues because it always holds many forms and possibilities.","sum":"The (A) of life allows species to survive in (B) environments.","gloss":"","bl":{"A":[{"first":"v","len":7,"sfx":""}],"B":[{"first":"c","len":8,"sfx":""}]},"key":{"A":{"w":"variety","acc":["variety"],"freq":false,"src":[],"note":""},"B":{"w":"changing","acc":["changing"],"freq":false,"src":[],"note":""}},"tr":"자연 속에는 서로 완전히 같은 생명체는 없다. 이러한 차이(difference)가 세상이 변할 때 생물이 살아남게 돕는다. 만약 모든 동물이 똑같았다면, 하나의 질병이 모두를 멸종시킬 수도 있었을 것이다. 생명이 계속되는 이유는 언제나 다양한 형태와 가능성을 지니기 때문이다.","ex":{"flow":"자연에서 똑같은 생물은 없고, 이 다양성 덕분에 세상이 변해도 종이 살아남는다는 내용.","b":{"A":["variety 명) 다양성","no two living things are exactly the same / many forms and possibilities","형용사 various, 동사 vary. a variety of ~ = 다양한 ~"],"B":["changing 형) 변하는","when the world changes","환경을 꾸미는 현재분사 형용사. ever-changing = 끊임없이 변하는"]}}},{"id":"q16","no":16,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"The Meaning of Time","pas":"In some cultures, being a few minutes late is no big deal. In others, time is treated like a promise — something that must be kept. When people respect time, they also respect the people who wait for them.","sum":"(A) shows respect for others and builds trust.","gloss":"시간엄수는 타인에 대한 존중과 신뢰를 보여준다.","bl":{"A":[{"first":"P","len":11,"sfx":""}]},"key":{"A":{"w":"Punctuality","acc":["Punctuality"],"freq":false,"src":[],"note":""}},"tr":"어떤 문화에서는 몇 분 늦는 것이 큰일이 아니다. 그러나 다른 문화에서는 시간은 지켜야 하는 약속처럼 여겨진다. 시간을 존중하는 것은 기다리는 사람을 존중하는 것이기도 하다.","ex":{"flow":"어떤 문화에선 몇 분 늦어도 괜찮지만, 다른 문화에선 시간이 약속처럼 지켜져야 하며 시간을 존중하는 것은 기다리는 사람을 존중하는 것이라는 내용.","b":{"A":["Punctuality 명) 시간 엄수","time is treated like a promise / respect time","문장 맨 앞 대문자 P. 형용사 punctual(시간을 잘 지키는). punct(점) → 딱 그 시점에"]}}},{"id":"q17","no":17,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":null,"pas":"In nature, many species compete to survive, but not all success comes from fighting. Animals that help each other often live longer and raise more young. From tiny ants to great whales, cooperation builds strong groups. Nature shows that life’s greatest strength lies not in power, but in working together.","sum":"(A) leads to (B) and survival among living things.","gloss":"","bl":{"A":[{"first":"C","len":11,"sfx":""}],"B":[{"first":"p","len":10,"sfx":""}]},"key":{"A":{"w":"Cooperation","acc":["Cooperation"],"freq":false,"src":[],"note":""},"B":{"w":"prosperity","acc":["prosperity"],"freq":false,"src":[],"note":""}},"tr":"자연에서 많은 종들은 살기 위해 경쟁하지만, 모든 성공이 싸움에서 오지는 않는다. 서로 돕는 동물들이 더 오래 살고, 더 많은 새끼를 기른다. 작은 개미에서부터 거대한 고래까지, 협력은 강한 집단을 만든다. 자연은 인생의 가장 큰 힘이 힘 그 자체가 아니라, 함께하는 데 있음을 보여준다.","ex":{"flow":"자연에서 서로 돕는 동물들이 더 오래 살고 새끼를 더 많이 기르며, 가장 큰 힘은 함께 일하는 데 있다는 내용.","b":{"A":["Cooperation 명) 협력","help each other / working together / cooperation builds strong groups","문장 맨 앞 대문자. 동사 cooperate. co(함께)+oper(일하다)"],"B":["prosperity 명) 번영, 번성","live longer and raise more young / strong groups","형용사 prosperous, 동사 prosper. survival과 and로 병렬된 명사"]}}},{"id":"q18","no":18,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":null,"pas":"People often focus on one part of a problem and miss the rest. A scientist may see facts, while an artist feels emotion — both views matter. To understand something fully, we must look at it from different sides. Only then can we see how the pieces fit together.","sum":"A (A) view comes from seeing things from (B) perspectives.","gloss":"포괄적인(종합적인) 관점은 여러 가지 관점에서 보는 것으로부터 온다.","bl":{"A":[{"first":"c","len":13,"sfx":""}],"B":[{"first":"m","len":8,"sfx":""}]},"key":{"A":{"w":"comprehensive","acc":["comprehensive"],"freq":false,"src":[],"note":""},"B":{"w":"multiple","acc":["multiple"],"freq":false,"src":[],"note":""}},"tr":"사람들은 종종 문제의 한 부분에만 집중하고 나머지를 놓친다. 과학자는 사실을 보고, 예술가는 감정을 느낀다 — 두 시각 모두 중요하다. 무언가를 완전히 이해하려면, 여러 관점에서 바라봐야 한다. 그래야만 각각의 조각이 어떻게 하나로 맞춰지는지 볼 수 있다.","ex":{"flow":"과학자는 사실을, 예술가는 감정을 보듯 한 면만 보면 놓치는 것이 있고, 여러 면에서 봐야 전체가 맞춰진다는 내용.","b":{"A":["comprehensive 형) 포괄적인, 종합적인","understand something fully / see how the pieces fit together","comprehend(이해하다)의 형용사지만 뜻은 \"포괄적인\". comprehensible(이해할 수 있는)과 구분"],"B":["multiple 형) 다수의, 여러","different sides / both views matter","multiple perspectives = 여러 관점. multi(많은) 어원"]}}},{"id":"q19","no":19,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Different but Connected","pas":"People come from different places and speak in different ways. Our cultures, languages, and histories may seem far apart. Yet, behind these differences, the same human hopes and fears remain. We are not truly divided — only expressed in many forms.","sum":"Although cultures seem (A), (B) shares the same emotions and dreams.","gloss":"","bl":{"A":[{"first":"s","len":8,"sfx":""}],"B":[{"first":"h","len":8,"sfx":""}]},"key":{"A":{"w":"separate","acc":["separate"],"freq":false,"src":[],"note":""},"B":{"w":"humanity","acc":["humanity"],"freq":false,"src":[],"note":""}},"tr":"사람들은 서로 다른 지역에서 태어나고, 다른 방식으로 말한다. 우리의 문화와 언어, 그리고 역사는 멀리 떨어져 있는 것처럼 보인다. 그러나 이 차이들 뒤에는 같은 인간의 희망과 두려움이 있다. 우리는 완전히 분리된 존재가 아니라, 다양한 형태로 표현된 하나의 존재다.","ex":{"flow":"문화·언어·역사는 멀어 보여도 그 뒤에는 같은 인간의 희망과 두려움이 있다는 내용.","b":{"A":["separate 형) 분리된, 별개의","seem far apart / divided","seem + 형용사. 동사(분리하다)로도 쓰임. sep-a-rate 철자(seperate ✗)"],"B":["humanity 명) 인류, 인간성","the same human hopes and fears","shares(3인칭 단수 동사)의 주어 → 단수 명사 humanity. human+-ity"]}}},{"id":"q20","no":20,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"The Hidden Details","pas":"When people look at something familiar, they often think they already understand it. But seeing is not the same as noticing. Small details — a tone, a gesture, or a single word — can change the whole meaning. To truly understand, we must look again and look deeper.","sum":"Because we (A) what seems familiar, we miss deeper meaning.","gloss":"","bl":{"A":[{"first":"o","len":8,"sfx":""}]},"key":{"A":{"w":"overlook","acc":["overlook"],"freq":false,"src":[],"note":""}},"tr":"사람들은 익숙한 것을 볼 때, 이미 다 안다고 생각하곤 한다. 하지만 본다는 것은 곧 ‘주의 깊게 본다’는 뜻은 아니다. 작은 디테일 — 말투, 몸짓, 단어 하나 — 가 전체 의미를 바꿀 수 있다. 진정한 이해는 다시 보고, 더 깊이 보는 데서 시작된다.","ex":{"flow":"익숙한 것을 볼 때 이미 안다고 생각하지만, 보는 것과 알아차리는 것은 다르며 작은 디테일이 의미를 바꾼다는 내용.","b":{"A":["overlook 동) 간과하다, 못 보고 넘어가다","seeing is not the same as noticing / they already understand it","we + 동사 원형. \"내려다보다\"라는 뜻도 있음. look over(검토하다)와 구분"]}}}]},{"r":3,"qs":[{"id":"q01","no":1,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Beauty of Change","pas":"Nothing in life stays the same forever. Seasons pass, people grow, and moments fade away. Yet, that’s what makes life precious — because we know it won’t last forever. The value of a moment lies in its passing nature.","sum":"Because everything is (A), each moment becomes more (B).","gloss":"모든 것이 일시적이기 때문에, 매 순간은 더 의미있게 된다.","bl":{"A":[{"first":"t","len":9,"sfx":""}],"B":[{"first":"m","len":10,"sfx":""}]},"key":{"A":{"w":"temporary","acc":["temporary"],"freq":false,"src":[],"note":""},"B":{"w":"meaningful","acc":["meaningful"],"freq":false,"src":[],"note":""}},"tr":"인생에서 영원히 같은 것은 없다. 계절은 지나가고, 사람은 성장하며, 순간은 사라진다. 그러나 그것이 바로 삶을 소중하게 만드는 이유다 — 영원하지 않다는 것을 알기 때문이다. 한순간의 가치는, 그것이 지나가 버리는 성질 속에 있다.","ex":{"flow":"삶의 모든 것은 영원하지 않고 지나가기 때문에 오히려 소중하다는 내용. 순간의 가치는 \"지나간다는 성질\"에 있다.","b":{"A":["temporary 형) 일시적인","Nothing in life stays the same forever / it won’t last forever / passing nature","tempor(시간) 어원. 반의어 permanent. 철자 -rary"],"B":["meaningful 형) 의미 있는, 소중한","that’s what makes life precious / The value of a moment","become + 형용사. precious·value를 meaningful로 패러프레이즈"]}}},{"id":"q02","no":2,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Two Ways of Seeing","pas":"People often see the same event in different ways. One person focuses on feelings, while another looks only at facts. Both views matter, but neither shows the whole truth alone. To understand a situation well, we need both emotion and reason.","sum":"While (A) emotions influence our view, (B) facts complete the picture.","gloss":"주관적인 감정은 우리의 관점에 영향을 주는 반면에, 객관적인 사실은 그 그림을 완성한다.","bl":{"A":[{"first":"s","len":10,"sfx":""}],"B":[{"first":"o","len":9,"sfx":""}]},"key":{"A":{"w":"subjective","acc":["subjective"],"freq":false,"src":[],"note":""},"B":{"w":"objective","acc":["objective"],"freq":false,"src":[],"note":""}},"tr":"사람들은 같은 사건을 서로 다르게 본다. 어떤 사람은 감정을 중심으로 보고, 다른 사람은 사실만 본다. 두 관점 모두 중요하지만, 어느 하나만으로는 전체 진실을 보여줄 수 없다. 한 상황을 제대로 이해하려면 감정과 이성이 모두 필요하다.","ex":{"flow":"같은 일도 감정으로 보는 사람과 사실로 보는 사람이 있고, 둘 다 필요하다는 내용. 주관 ↔ 객관의 대비.","b":{"A":["subjective 형) 주관적인","One person focuses on feelings / emotion","sub(아래)+ject(던지다). 명사로 쓰는 subject(주어, 과목)와 구분"],"B":["objective 형) 객관적인","another looks only at facts / reason","명사로는 \"목표\". 반의어 subjective와 한 쌍으로 외우기"]}}},{"id":"q03","no":3,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Two Sources of Behavior","pas":"People around the world act in many different ways. Some reactions appear naturally, like smiling at kindness or stepping back from danger. Other behaviors come from the traditions we learn as we grow. Human behavior is shaped by both what we are born with and what our culture teaches us.","sum":"While some behaviors are (A), many others are (B), and both work together.","gloss":"일부 행동은 선천적이고, 다른 행동은 문화적(=후천적)이지만, 둘은 함께 작용한다.","bl":{"A":[{"first":"i","len":6,"sfx":""}],"B":[{"first":"c","len":8,"sfx":""}]},"key":{"A":{"w":"innate","acc":["innate"],"freq":false,"src":[],"note":""},"B":{"w":"cultural","acc":["cultural"],"freq":false,"src":[],"note":""}},"tr":"전 세계 사람들은 서로 다른 방식으로 행동한다. 친절에 미소를 짓거나 위험에서 물러서는 반응처럼, 어떤 행동은 자연스럽게 나타난다. 반면 다른 행동들은 우리가 자라면서 배우는 전통과 문화에서 온다. 즉, 인간의 행동은 타고난 부분과 문화가 가르치는 부분이 함께 만들어낸다.","ex":{"flow":"웃음처럼 저절로 나오는 행동도 있고, 자라며 배우는 전통에서 오는 행동도 있어, 인간 행동은 타고난 것과 문화가 함께 만든다는 내용.","b":{"A":["innate 형) 타고난, 선천적인","appear naturally / what we are born with","in(안에)+nat(태어나다). 유의어 inborn, inherent. n 두 개"],"B":["cultural 형) 문화적인","come from the traditions we learn / what our culture teaches us","culture의 형용사. 여기서는 \"후천적인(learned)\"의 의미"]}}},{"id":"q04","no":4,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Growing Through Challenge","pas":"People often avoid difficult tasks because they feel uncomfortable. However, facing small challenges helps us learn new skills. When we try something unfamiliar, our confidence slowly grows. Every bit of effort adds to our ability to handle bigger problems later.","sum":"Because trying new things can (A) growth, (B) becomes part of learning.","gloss":"새로운 시도는 성장을 향상시키기 때문에, 불편함도 학습의 일부가 된다.","bl":{"A":[{"first":"e","len":7,"sfx":""}],"B":[{"first":"d","len":10,"sfx":""}]},"key":{"A":{"w":"enhance","acc":["enhance"],"freq":false,"src":[],"note":""},"B":{"w":"discomfort","acc":["discomfort"],"freq":false,"src":[],"note":""}},"tr":"사람들은 불편하다는 이유로 어려운 일을 피하는 경우가 많다. 하지만 작은 도전에 맞서는 것은 새로운 기술을 배우는 데 도움이 된다. 익숙하지 않은 일을 시도할 때, 우리의 자신감은 천천히 자란다. 작은 노력 하나하나가 나중에 더 큰 문제를 다룰 수 있는 능력을 쌓아준다.","ex":{"flow":"어려운 일을 피하고 싶지만, 작은 도전이 새 기술을 익히게 하고 자신감을 키운다는 내용. (원본에 정답이 인쇄돼 있던 문항을 빈칸으로 고침)","b":{"A":["enhance 동) 향상시키다, 높이다","facing small challenges helps us learn new skills / our confidence slowly grows","can + 동사 원형. 명사 enhancement. 유의어 improve, boost"],"B":["discomfort 명) 불편함","they feel uncomfortable","주어 자리 → 명사. dis(부정)+comfort. uncomfortable(형)을 명사로 바꿔 쓴 것"]}}},{"id":"q05","no":5,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Beyond Simple Comparison","pas":"People often compare their abilities with others. Sometimes they feel proud, and other times they feel disappointed. But human value cannot be measured by one skill or one moment. When we see the bigger picture, we realize that everyone has something important to offer.","sum":"Because one skill can make someone look (A), others may seem (B), but this view ignores deeper value.","gloss":"어떤 능력 때문에 누군가는 우월해 보이고, 다른 이는 열등해 보일 수 있지만, 이런 시각은 더 깊은 가치를 놓친다.","bl":{"A":[{"first":"s","len":8,"sfx":""}],"B":[{"first":"i","len":8,"sfx":""}]},"key":{"A":{"w":"superior","acc":["superior"],"freq":false,"src":[],"note":""},"B":{"w":"inferior","acc":["inferior"],"freq":false,"src":[],"note":""}},"tr":"사람들은 자신의 능력을 다른 사람과 자주 비교한다. 그래서 어떤 때는 뿌듯함을 느끼고, 어떤 때는 실망하기도 한다. 하지만 인간의 가치는 하나의 능력이나 한 순간으로 판단할 수 없다. 더 넓게 보면, 모든 사람은 중요한 무언가를 가지고 있다는 것을 알게 된다.","ex":{"flow":"사람들은 능력을 비교하며 우쭐하거나 실망하지만, 인간의 가치는 한 가지 능력이나 한순간으로 잴 수 없다는 내용.","b":{"A":["superior 형) 우월한, 뛰어난","feel proud","look + 형용사. be superior to ~ (than ✗). 명사 superiority"],"B":["inferior 형) 열등한, 못한","feel disappointed","be inferior to ~. superior와 반의어 쌍"]}}},{"id":"q06","no":6,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Choosing What Matters","pas":"People often feel busy because they try to do everything at once. But not all tasks have the same importance. When we focus on what truly matters, we use our time and energy more wisely. A meaningful life begins with choosing what to give our attention to.","sum":"Life becomes clearer when we set the right (A).","gloss":"올바른 우선순위를 세울 때 삶은 더 선명해진다.","bl":{"A":[{"first":"p","len":8,"sfx":""}]},"key":{"A":{"w":"priority","acc":["priority"],"freq":false,"src":[],"note":""}},"tr":"사람들은 한 번에 모든 일을 하려고 해서 바쁘다고 느끼곤 한다. 하지만 모든 일이 같은 중요도를 가진 것은 아니다. 진짜 중요한 것에 집중할 때, 우리는 시간과 에너지를 더 현명하게 사용한다. 의미 있는 삶은 무엇에 우리의 주의를 쓸지 선택하는 데서 시작된다.","ex":{"flow":"모든 일을 한꺼번에 하려 해서 바쁘지만, 정말 중요한 일에 집중할 때 시간과 에너지를 더 현명하게 쓴다는 내용.","b":{"A":["priority 명) 우선순위","not all tasks have the same importance / focus on what truly matters","set priorities = 우선순위를 정하다. 형용사 prior(이전의, 우선하는), 동사 prioritize"]}}},{"id":"q07","no":7,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Finding the Middle Point","pas":"People often feel pressure to choose one side — work or rest, speed or patience. But life is rarely about extremes. When we give the right amount of time to different parts of life, things feel calmer and more meaningful. Growth happens when we learn not to go too far in any direction.","sum":"Life becomes better when we keep (A) and make our days more (B).","gloss":"균형을 유지하고, 하루를 더 조화롭게 만들 때 삶이 좋아진다.","bl":{"A":[{"first":"b","len":7,"sfx":""}],"B":[{"first":"h","len":10,"sfx":""}]},"key":{"A":{"w":"balance","acc":["balance"],"freq":false,"src":[],"note":""},"B":{"w":"harmonious","acc":["harmonious"],"freq":false,"src":[],"note":""}},"tr":"사람들은 일과 휴식, 빠름과 느림처럼 한쪽을 선택해야 한다는 압박을 자주 느낀다. 하지만 삶은 극단적인 선택으로 이루어지지 않는다. 삶의 여러 부분에 적절한 시간을 나눠 줄 때, 우리는 더 차분하고 의미 있는 하루를 보낸다. 어느 한쪽으로 지나치게 치우치지 않을 때 성장이 이루어진다.","ex":{"flow":"일과 휴식, 속도와 인내 중 하나만 고르기보다, 어느 쪽으로도 지나치지 않게 적절히 나눌 때 삶이 차분하고 의미 있어진다는 내용.","b":{"A":["balance 명) 균형","the right amount of time to different parts / not to go too far in any direction","keep balance = 균형을 유지하다. lose one’s balance = 균형을 잃다"],"B":["harmonious 형) 조화로운","things feel calmer and more meaningful","harmony+-ous, y → i. make + 목적어 + 형용사"]}}},{"id":"q08","no":8,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"New Ideas from Simple Beginnings","pas":"Great changes often start in quiet, ordinary moments. A single question, a small problem, or a new conversation can open a new path. As people share thoughts and learn together, fresh ideas slowly take shape. What begins as something small can grow into something much larger.","sum":"The (A) of new ideas often begins with small actions or questions.","gloss":"새로운 아이디어의 출현은 종종 작은 행동이나 질문에서 시작된다.","bl":{"A":[{"first":"e","len":9,"sfx":""}]},"key":{"A":{"w":"emergence","acc":["emergence"],"freq":false,"src":[],"note":""}},"tr":"큰 변화는 종종 조용하고 평범한 순간에서 시작된다. 하나의 질문, 작은 문제, 새로운 대화가 새로운 길을 열어줄 수 있다. 사람들이 생각을 나누고 함께 배울 때, 새로운 아이디어는 천천히 형태를 갖춘다. 작게 시작된 것이 나중에는 훨씬 더 큰 것으로 자라날 수 있다.","ex":{"flow":"큰 변화는 평범한 순간의 질문 하나, 대화 하나에서 시작되어 생각이 모이며 서서히 모습을 갖춘다는 내용.","b":{"A":["emergence 명) 출현, 등장","fresh ideas slowly take shape / start in quiet, ordinary moments","동사 emerge. emergency(비상사태)와 철자·뜻 혼동 주의"]}}},{"id":"q09","no":9,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Learning in a Fast World","pas":"Today, new information appears every day. People must keep learning to understand the world around them. When we stay curious and ask questions, our understanding grows more quickly. Even small efforts, repeated often, help us learn faster than we expect.","sum":"Curiosity and steady effort can (A) learning.","gloss":"호기심과 꾸준한 노력은 학습을 가속화한다.","bl":{"A":[{"first":"a","len":10,"sfx":""}]},"key":{"A":{"w":"accelerate","acc":["accelerate"],"freq":false,"src":[],"note":""}},"tr":"오늘날에는 새로운 정보가 매일 나타난다. 사람들은 주변 세상을 이해하기 위해 계속해서 배워야 한다. 호기심을 유지하고 질문할 때, 우리의 이해는 더 빨리 성장한다. 작은 노력도 자주 반복하면, 우리가 생각한 것보다 훨씬 빠르게 배울 수 있다.","ex":{"flow":"새 정보가 매일 나오는 세상에서 호기심을 갖고 질문하면 이해가 더 빨리 자라고, 반복된 작은 노력이 예상보다 빨리 배우게 한다는 내용.","b":{"A":["accelerate 동) 가속하다, 촉진하다","our understanding grows more quickly / learn faster than we expect","can + 동사 원형. ac+celer(빠른). 반의어 decelerate. c 두 개, l 하나"]}}},{"id":"q10","no":10,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Value of Not Going Too Far","pas":"Many people believe that doing more always brings better results. But pushing ourselves too hard can lead to stress and mistakes. When we slow down and take things at a steady pace, we make clearer decisions. Life improves when effort is steady, not extreme.","sum":"Because (A)(s) cause problems, keeping a (B) pace leads to clearer thinking.","gloss":"극단은 문제를 만들기 때문에, 적당한 속도가 더 맑은 사고를 이끈다.","bl":{"A":[{"first":"e","len":7,"sfx":"(s)"}],"B":[{"first":"m","len":8,"sfx":""}]},"key":{"A":{"w":"extreme(s)","acc":["extreme(s)"],"freq":false,"src":[],"note":""},"B":{"w":"moderate","acc":["moderate"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 더 많이 하는 것이 항상 더 좋은 결과를 가져온다고 생각한다. 하지만 너무 무리하면 스트레스와 실수가 생길 수 있다. 속도를 조금 늦추고 꾸준한 페이스를 유지할 때, 우리는 더 명확한 결정을 내린다. 삶은 극단이 아니라, 꾸준한 노력 속에서 나아진다.","ex":{"flow":"더 많이 할수록 좋다고 믿지만 지나치면 스트레스와 실수가 생기고, 꾸준한 속도가 더 분명한 판단을 하게 한다는 내용.","b":{"A":["extreme 명) 극단","pushing ourselves too hard / not extreme","빈칸 뒤 (s) → extremes. 형용사로도 쓰임(extreme heat)"],"B":["moderate 형) 적당한, 중간의","a steady pace / slow down","명사 moderation. 반의어 extreme. 동사(완화하다)로도 쓰임"]}}},{"id":"q11","no":11,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"More Alike Than We Think","pas":"People from different places may look, speak, or act in very different ways. But when we pay attention, we notice many shared habits and feelings. Everyone laughs, worries, hopes, and cares for others. These small similarities remind us that humans are much closer than we first imagine.","sum":"Despite differences, people share a strong (A) in emotions and daily life.","gloss":"차이가 있음에도 불구하고, 사람들은 감정과 일상에서 강한 유사성을 공유한다.","bl":{"A":[{"first":"r","len":11,"sfx":""},{"first":"l","len":8,"sfx":""}]},"key":{"A":{"w":"resemblance / likeness","acc":["resemblance","likeness"],"freq":false,"src":[],"note":""}},"tr":"서로 다른 곳에서 온 사람들은 외모, 말투, 행동이 매우 다를 수 있다. 하지만 주의 깊게 보면, 많은 공통된 습관과 감정을 발견하게 된다. 모든 사람은 웃고, 걱정하고, 희망하고, 누군가를 돌본다. 이 작은 닮은 점들은 우리가 생각하는 것보다 사람들이 훨씬 더 가깝다는 사실을 일깨워 준다.","ex":{"flow":"사람마다 외모와 말, 행동이 달라도 모두 웃고 걱정하고 희망하며, 생각보다 훨씬 비슷하다는 내용.","b":{"A":["resemblance / likeness 명) 닮음, 유사성","many shared habits and feelings / small similarities","두 단어 모두 정답(r 10칸 = resemblance, l 8칸 = likeness). 동사 resemble(타동사, ~와 닮다: resemble with ✗)"]}}},{"id":"q12","no":12,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Growing Through What We Lack","pas":"People often feel discouraged when they are not good at something. However, having a weak spot can motivate us to learn and improve. A small struggle can push us to practice more and discover new abilities. Sometimes, the things we lack become the starting points of our greatest progress.","sum":"Because a (A) pushes us to practice, it often leads to (B).","gloss":"부족함이 우리를 연습하도록 만들기 때문에, 종종 발전으로 이어진다.","bl":{"A":[{"first":"d","len":10,"sfx":""}],"B":[{"first":"i","len":11,"sfx":""}]},"key":{"A":{"w":"deficiency","acc":["deficiency"],"freq":false,"src":[],"note":""},"B":{"w":"improvement","acc":["improvement"],"freq":false,"src":[],"note":""}},"tr":"사람들은 어떤 것을 잘하지 못할 때 종종 실망을 느낀다. 하지만 약점이 있다는 사실이 오히려 배우고 성장하려는 동기가 되기도 한다. 작은 어려움 하나가 더 많이 연습하고 새로운 능력을 발견하게 만든다. 때로는 우리가 부족한 부분이 더 큰 발전의 시작점이 된다.","ex":{"flow":"무언가를 잘 못하면 낙담하지만, 약점이 연습하고 새 능력을 발견하게 하는 동기가 되어 큰 발전의 출발점이 된다는 내용.","b":{"A":["deficiency 명) 결핍, 부족함","having a weak spot / the things we lack","a + 명사. 형용사 deficient. 2회 14번 deficient와 같이 외우기"],"B":["improvement 명) 향상, 발전","learn and improve / our greatest progress","lead to + 명사. 동사 improve"]}}},{"id":"q13","no":13,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"The Quiet Power of Routine","pas":"Many people believe that exciting moments make life meaningful. But daily routines—like waking up on time, eating well, and finishing small tasks—also play an important role. They give us a steady rhythm that keeps stress low and helps us stay focused. A calm and predictable day often supports long-term growth better than sudden changes.","sum":"While excitement is (A), (B) from routine builds lasting progress.","gloss":"자극은 일시적이지만, 루틴에서 오는 안정성은 지속적인 발전을 만든다.","bl":{"A":[{"first":"t","len":9,"sfx":""}],"B":[{"first":"s","len":9,"sfx":""}]},"key":{"A":{"w":"temporary","acc":["temporary"],"freq":false,"src":[],"note":""},"B":{"w":"stability","acc":["stability"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 자극적인 순간들이 삶을 의미 있게 만든다고 생각한다. 하지만 정해진 시간에 일어나기, 잘 먹기, 작은 일들을 마무리하는 것 같은 일상적인 습관도 중요하다. 이 습관들은 우리에게 흔들림 없는 리듬을 주어 스트레스를 줄이고 집중을 돕는다. 갑작스러운 변화보다, 차분하고 예측 가능한 하루가 오히려 장기적인 성장을 더 잘 만들어 준다.","ex":{"flow":"신나는 순간만이 아니라 매일의 루틴이 안정된 리듬을 만들어 스트레스를 낮추고 장기적인 성장을 돕는다는 내용.","b":{"A":["temporary 형) 일시적인","sudden changes / exciting moments (vs long-term growth)","1번과 같은 단어. 반의어 lasting, permanent"],"B":["stability 명) 안정(성)","a steady rhythm / A calm and predictable day","형용사 stable, 동사 stabilize. builds(단수 동사)의 주어"]}}},{"id":"q14","no":14,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Learning from Imperfect Starts","pas":"People often hesitate to begin something new because they feel unprepared. They worry that their skills are not strong enough or that they will make mistakes. But progress rarely begins from perfect conditions. Even a small, uncertain start can lead to steady improvement over time.","sum":"While early efforts may seem (A), they often become the (B) of later success.","gloss":"초기의 노력은 불충분해 보일 수 있지만, 그것들은 나중에 성공의 기반이 된다.","bl":{"A":[{"first":"i","len":10,"sfx":""}],"B":[{"first":"f","len":10,"sfx":""}]},"key":{"A":{"w":"inadequate","acc":["inadequate"],"freq":false,"src":[],"note":""},"B":{"w":"foundation","acc":["foundation"],"freq":false,"src":[],"note":""}},"tr":"사람들은 준비가 충분하지 않다고 느껴서 새로운 것을 시작하기를 망설인다. 자신의 능력이 약하거나 실수할까봐 걱정하기 때문이다. 하지만 완벽한 조건에서 시작되는 발전은 거의 없다. 작고 불확실한 시작도 시간이 지나면 꾸준한 성장으로 이어질 수 있다.","ex":{"flow":"준비가 덜 됐다고 느껴 시작을 망설이지만, 발전은 완벽한 조건에서 시작되지 않고 작고 불확실한 시작이 꾸준한 향상으로 이어진다는 내용.","b":{"A":["inadequate 형) 불충분한, 부족한","feel unprepared / skills are not strong enough / a small, uncertain start","seem + 형용사. 2회 7번과 같은 단어"],"B":["foundation 명) 기초, 토대","can lead to steady improvement over time","the foundation of ~ = ~의 기반. 2회 4번과 같은 단어"]}}},{"id":"q15","no":15,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Caution in the Wild","pas":"In nature, animals rarely move without checking their surroundings. A small pause before eating, walking, or exploring helps them avoid danger. This careful behavior is not a sign of weakness but a strategy shaped by survival. Those that take time to observe often live longer than those that rush forward.","sum":"Because (A) allows animals to observe their environment, it increases their (B)(s) of survival.","gloss":"망설임은 환경을 관찰할 시간을 주기 때문에 생존 가능성을 높인다.","bl":{"A":[{"first":"h","len":10,"sfx":""}],"B":[{"first":"c","len":6,"sfx":"(s)"}]},"key":{"A":{"w":"hesitation","acc":["hesitation"],"freq":false,"src":[],"note":""},"B":{"w":"chance(s)","acc":["chance(s)"],"freq":false,"src":[],"note":""}},"tr":"자연에서 동물들은 주변을 살피지 않고 행동하는 일이 거의 없다. 먹거나 걷거나 탐색하기 전에 잠깐 멈추는 행동은 위험을 피하는 데 도움이 된다. 이런 조심스러움은 약함이 아니라, 생존을 위해 형성된 전략이다. 서두르기보다 관찰하는 시간을 가진 동물들이 더 오래 살아남는 경우가 많다.","ex":{"flow":"동물은 먹거나 움직이기 전에 잠깐 멈춰 주변을 살피고, 이 신중함이 위험을 피하게 해 더 오래 살게 한다는 내용.","b":{"A":["hesitation 명) 망설임, 주저","A small pause / take time to observe","동사 hesitate. without hesitation = 주저 없이"],"B":["chance 명) 가능성, 기회","live longer / avoid danger","빈칸 뒤 (s) → chances of survival = 생존 가능성"]}}},{"id":"q16","no":16,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Change Shaped by Nature","pas":"In every generation, small differences appear in living things. These changes happen without any plan—they simply occur as life continues. Most of them do nothing, but a few help an animal survive better than others. When such helpful traits remain, the species slowly becomes stronger over time.","sum":"Because variations are (A), nature keeps the (B) traits that help survival.","gloss":"변이가 무작위이기 때문에, 자연은 유익한 특징만 선택해 남긴다.","bl":{"A":[{"first":"r","len":6,"sfx":""}],"B":[{"first":"b","len":10,"sfx":""}]},"key":{"A":{"w":"random","acc":["random"],"freq":false,"src":[],"note":""},"B":{"w":"beneficial","acc":["beneficial"],"freq":false,"src":[],"note":""}},"tr":"매 세대마다 생명체에는 작은 차이들이 나타난다. 이 변화들은 어떤 계획 때문이 아니라, 삶이 이어지면서 그냥 생겨나는 것들이다. 대부분은 큰 영향을 주지 않지만, 일부는 동물이 더 잘 살아남도록 돕는다. 이렇게 도움이 되는 특징들이 남게 되면서, 그 종은 시간이 지나며 천천히 더 강해진다.","ex":{"flow":"세대마다 계획 없이 작은 차이가 생기고, 그중 생존에 도움이 되는 특징이 남아 종이 강해진다는 내용 (자연 선택).","b":{"A":["random 형) 무작위의, 임의의","happen without any plan — they simply occur","at random = 무작위로. 반의어 planned, intentional"],"B":["beneficial 형) 이로운, 유익한","help an animal survive better / helpful traits","bene(좋은) 어원. 명사 benefit. be beneficial to ~"]}}},{"id":"q17","no":17,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Adjusting Our View of the World","pas":"People often see the world only from their own point of view. They judge ideas based on personal habits or past experiences. But deeper understanding comes when we slow down and listen to others. By accepting different perspectives, we learn to think in a more open and flexible way.","sum":"While people prefer (A) thoughts, true insight comes when they (B) new perspectives.","gloss":"사람들은 익숙한 생각을 좋아하더라도, 새로운 관점을 수용할 때 진짜 통찰이 생긴다.","bl":{"A":[{"first":"f","len":8,"sfx":""}],"B":[{"first":"a","len":11,"sfx":""}]},"key":{"A":{"w":"familiar","acc":["familiar"],"freq":false,"src":[],"note":""},"B":{"w":"accommodate","acc":["accommodate"],"freq":false,"src":[],"note":""}},"tr":"사람들은 세상을 자신의 관점으로만 보는 경우가 많다. 아이디어를 자신의 습관이나 과거 경험에 따라 판단하기 때문이다. 하지만 다른 사람의 의견을 천천히 듣고 받아들일 때, 더 깊은 이해가 생긴다. 여러 관점을 수용하면, 우리는 더 열린 마음과 유연한 사고를 갖게 된다.","ex":{"flow":"사람들은 자기 관점과 습관으로 생각을 판단하지만, 다른 관점을 받아들일 때 더 열린 사고를 하게 된다는 내용.","b":{"A":["familiar 형) 익숙한, 친숙한","their own point of view / personal habits or past experiences","be familiar with ~ (사람이 주어), be familiar to ~ (대상이 주어)"],"B":["accommodate 동) 수용하다, 받아들이다","By accepting different perspectives","they + 동사 원형. c 두 개, m 두 개(accomodate ✗). \"숙박을 제공하다\"라는 뜻도"]}}},{"id":"q18","no":18,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Thinking Beyond Usual Patterns","pas":"People often follow familiar ways of thinking because they feel safe and easy. These common patterns help us make quick decisions, but they can also limit new ideas. When we slow down and question what we usually accept, we open the door to deeper understanding. Many meaningful discoveries begin when someone dares to think differently.","sum":"True insight appears when people (A) from (B) ways of thinking.","gloss":"사람들이 관습적인 사고에서 벗어날 때 진짜 통찰이 생긴다.","bl":{"A":[{"first":"d","len":7,"sfx":""}],"B":[{"first":"c","len":12,"sfx":""}]},"key":{"A":{"w":"deviate","acc":["deviate"],"freq":false,"src":[],"note":""},"B":{"w":"conventional","acc":["conventional"],"freq":false,"src":[],"note":""}},"tr":"사람들은 익숙한 사고방식을 따르는 경우가 많다. 이런 평범하고 익숙한 방식은 빠른 결정을 돕지만, 새로운 생각을 제한할 수도 있다. 우리가 당연하게 받아들이는 것들을 질문할 때, 더 깊은 이해가 열린다. 많은 중요한 발견은 누군가가 다르게 생각하려고 용기낼 때 시작된다.","ex":{"flow":"익숙한 사고 패턴은 빠른 결정을 돕지만 새 생각을 막고, 당연한 것을 의심하고 다르게 생각할 때 발견이 시작된다는 내용.","b":{"A":["deviate 동) 벗어나다, 일탈하다","dares to think differently / question what we usually accept","deviate from ~ = ~에서 벗어나다. de(떨어져)+via(길). 명사 deviation"],"B":["conventional 형) 관습적인, 전통적인","familiar ways of thinking / These common patterns","convention(관습)+-al. 반의어 unconventional, innovative"]}}},{"id":"q19","no":19,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why We Delay Important Tasks","pas":"Many people plan to finish their work early, but they often push it aside. They choose small, easy activities instead because these feel more comfortable. However, avoiding important tasks only increases stress later. When we begin even a little earlier, we feel more control and less pressure.","sum":"People feel more stress when they (A) instead of starting early.","gloss":"사람들은 일찍 시작하지 않고 미루면 더 큰 스트레스를 느낀다.","bl":{"A":[{"first":"p","len":13,"sfx":""}]},"key":{"A":{"w":"procrastinate","acc":["procrastinate"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 일을 일찍 끝내려고 계획하지만, 종종 그것을 미뤄 둔다. 대신 더 쉽고 작은 활동을 선택하는데, 그게 더 편하게 느껴지기 때문이다. 하지만 중요한 일을 피하면, 나중에 스트레스만 더 커진다. 아주 조금이라도 먼저 시작하면, 우리는 더 통제감이 생기고 압박감이 줄어든다.","ex":{"flow":"일찍 끝내려 계획하지만 쉬운 일로 미루게 되고, 중요한 일을 피할수록 나중에 스트레스가 커진다는 내용.","b":{"A":["procrastinate 동) 미루다, 꾸물거리다","push it aside / avoiding important tasks","they + 동사 원형. pro(앞으로)+cras(내일) → 내일로 미루다. 명사 procrastination"]}}},{"id":"q20","no":20,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Different Ways of Expressing Ourselves","pas":"People around the world express their thoughts in many ways. Some use strong gestures, while others prefer calm and quiet communication. These habits come from each group’s history and daily life. By noticing these differences, we learn to understand others more openly.","sum":"Because groups have (A) histories, their communication styles become (B).","gloss":"문화마다 독특한(고유의) 역사가 있기 때문에, 그들의 소통 방식은 뚜렷하게 달라진다.","bl":{"A":[{"first":"u","len":6,"sfx":""}],"B":[{"first":"d","len":11,"sfx":""}]},"key":{"A":{"w":"unique","acc":["unique"],"freq":false,"src":[],"note":""},"B":{"w":"distinctive","acc":["distinctive"],"freq":false,"src":[],"note":""}},"tr":"전 세계 사람들은 자신의 생각을 다양한 방식으로 표현한다. 어떤 사람들은 강한 몸짓을 사용하고, 어떤 사람들은 차분하고 조용한 표현을 선호한다. 이런 습관은 각각의 역사와 일상에서 만들어진 것이다. 이 차이들을 살펴보면, 우리는 다른 사람들을 더 열린 마음으로 이해하게 된다.","ex":{"flow":"사람들은 강한 몸짓이나 조용한 말투처럼 다양한 방식으로 표현하며, 이 습관은 각 집단의 역사와 일상에서 온다는 내용.","b":{"A":["unique 형) 고유한, 독특한","each group’s history and daily life","u는 자음 발음이라 a unique ~. \"매우 독특한\"을 very unique로 쓰지 않음"],"B":["distinctive 형) 독특한, 특유의, 구별되는","Some use strong gestures, while others prefer calm and quiet communication","distinct(뚜렷한)+-ive. distinguish(구별하다)와 같은 어원"]}}}]},{"r":4,"qs":[{"id":"q01","no":1,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why We Are Not All the Same","pas":"People share many basic features, but each person still develops in a different way. Some differences come from the environment—such as food, climate, and daily habits. Other differences come from what we receive from our parents at birth. Together, these influences shape how we grow, think, and respond to the world.","sum":"Human differences come from both (A) and (B) factors.","gloss":"사람들의 차이는 환경적 요인과 유전적 요인에서 온다.","bl":{"A":[{"first":"e","len":13,"sfx":""}],"B":[{"first":"g","len":7,"sfx":""}]},"key":{"A":{"w":"environmental","acc":["environmental"],"freq":false,"src":[],"note":""},"B":{"w":"genetic","acc":["genetic"],"freq":false,"src":[],"note":""}},"tr":"사람들은 많은 기본적인 특징을 공유하지만, 각자가 다르게 발달한다. 어떤 차이는 음식, 기후, 생활습관 같은 환경에서 생긴다. 또 다른 차이는 태어날 때 부모로부터 물려받은 요소에서 비롯된다. 이 두 영향이 함께 작용해 우리가 어떻게 자라고, 생각하고, 세상에 반응하는지가 결정된다.","ex":{"flow":"사람마다 다르게 자라는 이유로 환경(음식·기후·습관)과 부모에게서 받은 것(유전) 두 가지를 든 내용.","b":{"A":["environmental 형) 환경의, 환경적인","the environment — such as food, climate, and daily habits","environment+-al. factors를 꾸미는 형용사"],"B":["genetic 형) 유전의, 유전적인","what we receive from our parents at birth","gene(유전자)의 형용사. 명사 genetics(유전학)"]}}},{"id":"q02","no":2,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why We Notice Some Feelings and Ignore Others","pas":"In psychology, researchers say that people pay attention only to a few signals around them. When we feel stressed or busy, our brains choose the easiest information to process. Because of this, we sometimes miss signs that someone is sad, worried, or lonely. But when we slow down and focus on others, our minds become more open to their emotions.","sum":"Because stress can create (A), slowing down helps us show more (B).","gloss":"스트레스가 무관심을 만들기 때문에, 속도를 늦추면 더 큰 공감을 보일 수 있다.","bl":{"A":[{"first":"i","len":12,"sfx":""}],"B":[{"first":"e","len":7,"sfx":""}]},"key":{"A":{"w":"indifference","acc":["indifference"],"freq":false,"src":[],"note":""},"B":{"w":"empathy","acc":["empathy"],"freq":false,"src":[],"note":""}},"tr":"심리학에서 연구자들은 사람이 주변의 많은 신호 중 일부만 주로 주의를 기울인다고 말한다. 우리가 스트레스를 받거나 바쁠 때, 뇌는 처리하기 가장 쉬운 정보만 선택한다. 그 때문에 누군가가 슬프거나 걱정하거나 외로워하는 신호를 놓칠 때가 있다. 하지만 속도를 줄이고 다른 사람에게 집중하면, 우리는 그들의 감정을 더 잘 받아들일 수 있다.","ex":{"flow":"스트레스를 받거나 바쁘면 뇌가 쉬운 정보만 골라 남의 슬픔을 놓치지만, 속도를 늦추면 다른 사람의 감정에 더 열린다는 내용.","b":{"A":["indifference 명) 무관심","we sometimes miss signs that someone is sad, worried, or lonely","in(부정)+different(차이 있는 → 관심 있는). 형용사 indifferent to ~ = ~에 무관심한"],"B":["empathy 명) 공감","focus on others / more open to their emotions","2회 8번과 같은 단어. show empathy = 공감을 보이다"]}}},{"id":"q03","no":3,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Prices as Signals in a Free Market","pas":"Hayek believed that prices do more than show how much something costs. They act as signals that tell people when a resource is rare or easy to find. When a price rises, buyers use less of that resource, and sellers try to supply more. Through these simple reactions, the market organizes itself without a central plan.","sum":"Price signals help markets avoid a resource (A) and move toward a (B).","gloss":"가격 신호는 시장이 자원 부족을 피하고 잉여로 가도록 돕는다.","bl":{"A":[{"first":"d","len":7,"sfx":""}],"B":[{"first":"s","len":7,"sfx":""}]},"key":{"A":{"w":"deficit","acc":["deficit"],"freq":false,"src":[],"note":""},"B":{"w":"surplus","acc":["surplus"],"freq":false,"src":[],"note":""}},"tr":"하이에크는 가격이 단순히 비용을 보여주는 것이 아니다라고 보았다. 가격은 어떤 자원이 희귀한지, 여유가 있는지 사람들에게 알려주는 신호로 작용한다. 가격이 오르면 소비자는 덜 사용하고, 판매자는 더 공급하려고 한다. 이런 단순한 반응만으로도 시장은 중앙 계획 없이 스스로 조정된다.","ex":{"flow":"하이에크는 가격이 자원이 부족한지 흔한지 알려 주는 신호이며, 가격이 오르면 덜 쓰고 더 공급해 시장이 스스로 조직된다고 보았다는 내용.","b":{"A":["deficit 명) 부족(액), 적자","a resource is rare / When a price rises, buyers use less","a resource deficit = 자원 부족. 반의어 surplus. 형용사 deficient와 같은 어원"],"B":["surplus 명) 잉여, 과잉","sellers try to supply more","sur(넘어서)+plus(더). trade surplus = 무역 흑자"]}}},{"id":"q04","no":4,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Understanding Through Simple Examples","pas":"When people learn new ideas, they often struggle to understand them right away. Because the idea feels unfamiliar, it can be hard to know how it works. But when teachers give a simple example that connects to everyday life, the idea becomes much easier to accept. These small explanations guide our thinking and help us build clearer understanding.","sum":"Because (A) ideas confuse learners, an (B) helps connect them to daily life.","gloss":"익숙하지 않은 개념은 학습자를 혼란스럽게 하지만, 비유는 그것을 일상과 연결해 준다.","bl":{"A":[{"first":"u","len":10,"sfx":""}],"B":[{"first":"a","len":7,"sfx":""}]},"key":{"A":{"w":"unfamiliar","acc":["unfamiliar"],"freq":false,"src":[],"note":""},"B":{"w":"analogy","acc":["analogy"],"freq":false,"src":[],"note":""}},"tr":"사람들은 새로운 개념을 배울 때, 처음에는 쉽게 이해하지 못한다. 그 개념이 낯설게 느껴지기 때문에, 어떻게 작동하는지 떠올리기 어렵다. 하지만 일상과 연결된 쉬운 예시를 들으면, 그 개념은 훨씬 더 쉽게 받아들여진다. 이런 작은 설명들이 우리의 생각을 이끌어 주며 더 명확한 이해를 만들어 준다.","ex":{"flow":"새 개념은 낯설어 이해하기 어렵지만, 일상과 연결된 간단한 예를 들면 훨씬 받아들이기 쉬워진다는 내용.","b":{"A":["unfamiliar 형) 익숙하지 않은, 낯선","the idea feels unfamiliar","지문 단어 그대로. un+familiar"],"B":["analogy 명) 비유, 유추","a simple example that connects to everyday life","an 뒤 모음 a. 형용사 analogous. 비슷한 것에 빗대어 설명하는 것"]}}},{"id":"q05","no":5,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Helping Others to Survive Together","pas":"In the wild, many animals help one another even when they are not family. A bird may warn others about a predator, or one animal may share food during hard times. At first, this seems risky because the animal gives something away. But later, the same partner may return the favor, and both survive more easily. This repeated exchange helps groups stay strong over many generations.","sum":"Animals survive better through (A) helping behavior.","gloss":"동물들은 상호호혜적 도움 행동을 통해 더 잘 살아남는다.","bl":{"A":[{"first":"r","len":10,"sfx":""}]},"key":{"A":{"w":"reciprocal","acc":["reciprocal"],"freq":false,"src":[],"note":""}},"tr":"자연에서는 가족이 아니어도 서로 돕는 동물들이 많다. 한 새가 포식자 경고를 해주거나, 어떤 동물이 어려운 시기에 먹이를 나누어 주기도 한다. 처음에는 손해처럼 보이지만, 나중에 그 상대가 보답을 해주면서, 둘 다 더 쉽게 살아남는다. 이런 반복적인 도움의 교환은 여러 세대 동안 그룹을 더 강하게 만든다.","ex":{"flow":"야생에서 동물들이 경고하거나 먹이를 나누면, 나중에 상대가 은혜를 갚아 둘 다 더 쉽게 살아남는다는 내용.","b":{"A":["reciprocal 형) 상호의, 호혜적인","the same partner may return the favor / This repeated exchange","서로 주고받는 관계. 동사 reciprocate. 유의어 mutual"]}}},{"id":"q06","no":6,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"A World Changing Faster Than Before","pas":"In recent years, technology has grown more quickly than many people expected. New tools appear every day, and they change how we work, study, and communicate. Many people try to keep up, but the speed of change can feel overwhelming. Still, these developments open new opportunities for learning and problem-solving.","sum":"Because of its (A) pace, many people feel pressure to (B).","gloss":"전례 없는 변화 속도 때문에 많은 사람들이 적응하는데 압박을 느낀다.","bl":{"A":[{"first":"u","len":13,"sfx":""}],"B":[{"first":"a","len":5,"sfx":""}]},"key":{"A":{"w":"unprecedented","acc":["unprecedented"],"freq":false,"src":[],"note":""},"B":{"w":"adapt","acc":["adapt"],"freq":false,"src":[],"note":""}},"tr":"최근 몇 년 동안 기술은 많은 사람이 예상한 것보다 훨씬 빠르게 성장했다. 새로운 도구들이 매일 등장하며, 우리가 일하고, 공부하고, 소통하는 방식을 바꾸고 있다. 많은 사람들이 이런 변화를 따라가려고 하지만, 너무 빠른 속도 때문에 부담스럽게 느껴질 때도 있다. 그럼에도 이런 발전은 학습과 문제 해결에 새로운 기회를 열어 준다.","ex":{"flow":"기술이 예상보다 빠르게 발전해 일하고 공부하는 방식을 바꾸고, 많은 사람이 따라가려 애쓰지만 변화 속도에 압도된다는 내용.","b":{"A":["unprecedented 형) 전례 없는","grown more quickly than many people expected","un+precedent(선례)+-ed. 14칸 철자: un-pre-ce-dent-ed"],"B":["adapt 동) 적응하다","Many people try to keep up","feel pressure to + 동사 원형. adopt(채택하다), adept(능숙한)와 철자 혼동 주의"]}}},{"id":"q07","no":7,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Being Alone and Understanding Ourselves","pas":"People sometimes spend time alone, away from noise and busy routines. In these quiet moments, they can think more clearly about their feelings and goals. Although being alone may seem uncomfortable at first, it often helps people notice what truly matters to them. Short periods of quiet time can make daily life feel more balanced and calm.","sum":"A short (A) moment helps people understand themselves better.","gloss":"짧은 고독한 시간은 사람들에게 자신을 더 잘 이해하게 한다.","bl":{"A":[{"first":"s","len":8,"sfx":""}]},"key":{"A":{"w":"solitary","acc":["solitary"],"freq":false,"src":[],"note":""}},"tr":"사람들은 가끔 소음과 바쁜 일상에서 벗어나 혼자 시간을 보낸다. 이런 조용한 순간에는, 자신의 감정과 목표를 더 명확하게 생각할 수 있다. 처음에는 혼자 있는 것이 불편해 보일 수 있지만, 그 시간은 오히려 자신에게 정말 중요한 것이 무엇인지 깨닫게 해 준다. 잠깐의 고요한 시간만으로도 일상이 더 균형 있고 차분하게 느껴질 수 있다.","ex":{"flow":"혼자 조용히 있는 시간에 감정과 목표를 더 분명히 생각하고, 무엇이 중요한지 알아차린다는 내용.","b":{"A":["solitary 형) 혼자의, 고독한","spend time alone / being alone","moment를 꾸미는 형용사. 명사 solitude. sol(혼자) 어원: solo"]}}},{"id":"q08","no":8,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Opening Up and Feeling Connected","pas":"Many people hide their worries because they want to look confident. But when they gently share their true feelings with someone they trust, something important happens. The other person often responds with kindness, showing that they have similar fears or doubts. These honest moments help people feel closer, turning simple conversations into meaningful connections.","sum":"Sharing (A) helps people build a stronger sense of (B).","gloss":"취약함을 나누면 더 강한 소속감이 생긴다.","bl":{"A":[{"first":"v","len":13,"sfx":""}],"B":[{"first":"b","len":9,"sfx":""}]},"key":{"A":{"w":"vulnerability","acc":["vulnerability"],"freq":false,"src":[],"note":""},"B":{"w":"belonging","acc":["belonging"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 자신을 자신감 있어 보이게 하려고 걱정을 숨긴다. 하지만 믿을 수 있는 사람에게 진짜 감정을 조금씩 나누면, 중요한 변화가 일어난다. 상대도 비슷한 두려움과 고민을 가지고 있다는 것을 친절하게 보여주기 때문이다. 이런 솔직한 순간들은 사람들을 더 가깝게 만들고, 평범한 대화를 의미 있는 연결로 바꾼다.","ex":{"flow":"걱정을 숨기다가 믿는 사람에게 진짜 감정을 나누면, 상대도 비슷한 두려움을 보여 주며 서로 더 가까워진다는 내용.","b":{"A":["vulnerability 명) 취약함, 약한 모습","share their true feelings / worries … fears or doubts","형용사 vulnerable. Sharing의 목적어 → 명사"],"B":["belonging 명) 소속(감)","feel closer / meaningful connections","a sense of belonging = 소속감. 복수형 belongings는 \"소지품\""]}}},{"id":"q09","no":9,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"When Actions Don’t Match Words","pas":"People often say that honesty and kindness are important. But in real life, they sometimes act differently when the situation becomes difficult. Someone may promise to help but disappear when help is actually needed. These moments remind us that true character is shown through actions, not just good words.","sum":"While good words sound nice, (A) actions reveal a lack of true (B).","gloss":"좋은 말을 듣기는 좋아도, 위선적인 행동은 진정한 정직함의 부족을 드러낸다.","bl":{"A":[{"first":"h","len":12,"sfx":""}],"B":[{"first":"h","len":7,"sfx":""}]},"key":{"A":{"w":"hypocritical","acc":["hypocritical"],"freq":false,"src":[],"note":""},"B":{"w":"honesty","acc":["honesty"],"freq":false,"src":[],"note":""}},"tr":"사람들은 정직과 친절이 중요하다고 말한다. 하지만 실제 상황이 어려워지면, 말과 다르게 행동할 때가 있다. 누군가는 도와주겠다고 약속해 놓고, 정작 필요할 때 사라지기도 한다. 이런 순간들은 좋은 말보다 행동이 진짜 성품을 보여 준다는 사실을 일깨워 준다.","ex":{"flow":"사람들은 정직과 친절이 중요하다고 말하지만 어려울 때는 다르게 행동하기도 하며, 진짜 인격은 말이 아니라 행동으로 드러난다는 내용.","b":{"A":["hypocritical 형) 위선적인","promise to help but disappear / act differently","명사 hypocrisy(위선), hypocrite(위선자). y 철자 주의"],"B":["honesty 명) 정직","honesty and kindness are important / true character","1회 13번과 같은 단어. a lack of ~ = ~의 부족"]}}},{"id":"q10","no":10,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Choosing to Stay by Someone’s Side","pas":"In daily life, people face moments when a friend or partner is going through a hard time. Some choose to step back because the situation feels uncomfortable. But others stay close, offering support even when things are difficult. These steady actions build trust and show how much a relationship truly matters.","sum":"Because support in hard times builds (A), it becomes a strong sign of (B).","gloss":"힘든 시기에 보내는 지원이 신뢰를 만들기 때문에, 그것이 강한 충성의 증거가 된다.","bl":{"A":[{"first":"t","len":5,"sfx":""}],"B":[{"first":"l","len":7,"sfx":""}]},"key":{"A":{"w":"trust","acc":["trust"],"freq":false,"src":[],"note":""},"B":{"w":"loyalty","acc":["loyalty"],"freq":false,"src":[],"note":""}},"tr":"일상에서 우리는 친구나 가까운 사람이 힘든 시간을 보내는 순간을 마주한다. 어떤 사람들은 상황이 불편하다는 이유로 멀어지기도 한다. 하지만 다른 사람들은 상황이 어렵더라도 곁에 머물며 지원을 보낸다. 이런 꾸준한 행동들이 신뢰를 만들고, 관계가 얼마나 소중한지 보여준다.","ex":{"flow":"친구가 힘들 때 물러서는 사람도 있지만 곁에 남아 돕는 사람도 있고, 그런 꾸준한 행동이 신뢰를 쌓고 관계의 깊이를 보여 준다는 내용.","b":{"A":["trust 명) 신뢰","These steady actions build trust","지문 단어 그대로. 동사로도 쓰임"],"B":["loyalty 명) 충성, 의리","stay close, offering support even when things are difficult","형용사 loyal. a sign of ~ = ~의 표시"]}}},{"id":"q11","no":11,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why We Repeat the Same Choices","pas":"In daily life, people often make similar decisions without thinking much. They choose the same foods, follow the same routes, or react in familiar ways. This happens because the brain prefers routines that feel safe and easy. But trying something new from time to time can help people learn more and grow.","sum":"People have a (A) to repeat familiar choices because they feel (B).","gloss":"사람들은 익숙한 선택을 반복하는 경향이 있다 왜냐하면 그러한 선택들이 안전하게 느껴지기 때문이다.","bl":{"A":[{"first":"t","len":8,"sfx":""}],"B":[{"first":"s","len":4,"sfx":""}]},"key":{"A":{"w":"tendency","acc":["tendency"],"freq":false,"src":[],"note":""},"B":{"w":"safe","acc":["safe"],"freq":false,"src":[],"note":""}},"tr":"일상에서 사람들은 크게 생각하지 않고 비슷한 선택을 반복한다. 똑같은 음식을 고르고, 늘 가던 길을 가며, 익숙한 방식으로 반응한다. 이런 행동은 뇌가 안전하고 편안하게 느껴지는 루틴을 선호하기 때문이다. 하지만 가끔 새로운 것을 시도하면, 더 많이 배우고 성장할 수 있다.","ex":{"flow":"사람들은 같은 음식·같은 길처럼 익숙한 선택을 반복하는데, 뇌가 안전하고 쉬운 루틴을 좋아하기 때문이라는 내용.","b":{"A":["tendency 명) 경향, 성향","often make similar decisions","have a tendency to + 동사원형 = ~하는 경향이 있다. 동사 tend to"],"B":["safe 형) 안전한","routines that feel safe and easy","feel + 형용사. 4칸"]}}},{"id":"q12","no":12,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How Things Spread in a Group","pas":"In many situations, something does not appear in the same amount everywhere. For example, some neighborhoods have more trees, while others have only a few. In a classroom, some students may talk often, and others stay quiet. By observing these differences, we can understand patterns that shape how a group behaves.","sum":"Studying the (A) of things helps us see patterns in a group.","gloss":"분포를 연구하는 것은 한 집단의 패턴을 이해하는 데 도움이 된다.","bl":{"A":[{"first":"d","len":12,"sfx":""}]},"key":{"A":{"w":"distribution","acc":["distribution"],"freq":false,"src":[],"note":""}},"tr":"많은 상황에서 어떤 것이 모든 곳에 똑같이 나타나는 것은 아니다. 예를 들어 어떤 지역은 나무가 많고, 다른 지역은 적을 수도 있다. 교실에서도 어떤 학생은 자주 말하고, 어떤 학생은 조용하다. 이런 차이를 살펴보면, 그 집단이 어떻게 움직이는지 보여주는 패턴을 이해할 수 있다.","ex":{"flow":"어떤 동네엔 나무가 많고 어떤 동네엔 적듯, 어떤 것이 곳곳에 같은 양으로 있지 않으며 그 차이를 보면 집단의 패턴을 이해할 수 있다는 내용.","b":{"A":["distribution 명) 분포, 분배","does not appear in the same amount everywhere","동사 distribute. the distribution of wealth = 부의 분배"]}}},{"id":"q13","no":13,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Simple Choices Feel Better","pas":"People often want freedom to choose whatever they like. But when too many options appear, they feel more confused instead of satisfied. They spend more time comparing, worrying, and doubting their final choice. Although choices are meant to make life easier, they can sometimes create unnecessary stress.","sum":"Having more choices creates a (A): too many options bring confusion instead of (B).","gloss":"더 많은 선택은 역설을 만들어낸다. 너무 많은 선택지는 만족보다는 혼란을 준다는 점이다.","bl":{"A":[{"first":"p","len":7,"sfx":""}],"B":[{"first":"s","len":12,"sfx":""}]},"key":{"A":{"w":"paradox","acc":["paradox"],"freq":false,"src":[],"note":""},"B":{"w":"satisfaction","acc":["satisfaction"],"freq":false,"src":[],"note":""}},"tr":"사람들은 원하는 것을 선택할 자유를 좋아한다. 하지만 선택지가 너무 많아지면, 만족하기보다는 오히려 혼란스러워진다. 사람들은 더 오래 비교하고, 걱정하며, 마지막 선택을 의심하게 된다. 선택은 원래 삶을 더 편하게 만들려고 존재하지만, 때때로 불필요한 스트레스를 만들어내기도 한다.","ex":{"flow":"자유롭게 고르고 싶지만 선택지가 너무 많으면 만족하기보다 비교하고 걱정하며 더 혼란스러워진다는 내용 (선택의 역설).","b":{"A":["paradox 명) 역설","Although choices are meant to make life easier, they can … create unnecessary stress","쉽게 하려던 것이 오히려 어렵게 만드는 모순. 형용사 paradoxical"],"B":["satisfaction 명) 만족","feel more confused instead of satisfied","instead of + 명사. 형용사 satisfied를 명사로"]}}},{"id":"q14","no":14,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How Groups Shape Our Decisions","pas":"People often believe they make choices completely on their own. But in daily life, the opinions and habits of the people around us influence what we do. We may follow certain fashions, copy ways of speaking, or join activities because others do the same. By noticing how strongly groups affect us, we can understand our behavior more clearly.","sum":"While we think we act alone, our decisions often follow (A) pressure and habits.","gloss":"우리는 혼자 행동한다고 생각하지만, 우리의 많은 선택은 집단적 압력과 관습을 따른다.","bl":{"A":[{"first":"c","len":10,"sfx":""}]},"key":{"A":{"w":"collective","acc":["collective"],"freq":false,"src":[],"note":""}},"tr":"사람들은 자신이 모든 선택을 스스로 한다고 생각하는 경우가 많다. 하지만 일상에서는 주변 사람들의 의견과 습관이 우리의 행동에 큰 영향을 준다. 우리는 다른 사람이 하니까 유행을 따르거나, 말투를 비슷하게 하고, 같은 활동에 참여하기도 한다. 이처럼 집단이 우리에게 얼마나 강하게 영향을 주는지 이해하면, 자신의 행동을 더 명확하게 볼 수 있다.","ex":{"flow":"스스로 선택한다고 믿지만, 주변 사람들의 의견과 습관이 우리가 하는 일에 영향을 준다는 내용.","b":{"A":["collective 형) 집단의, 집단적인","the opinions and habits of the people around us / groups affect us","collect(모으다)+-ive. 반의어 individual"]}}},{"id":"q15","no":15,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Seeing Others With Kindness","pas":"People often notice the actions of others but overlook the feelings behind them. Someone who seems angry may actually be tired or worried. When we pause and try to understand the emotions beneath a person’s behavior, we respond more gently. This simple effort can turn small conflicts into moments of understanding.","sum":"Understanding others’ feelings helps us respond in a more (A) way.","gloss":"타인의 감정을 이해하면 더 따뜻하고 동정심 있는 방식으로 반응할 수 있다.","bl":{"A":[{"first":"c","len":13,"sfx":""}]},"key":{"A":{"w":"compassionate","acc":["compassionate"],"freq":false,"src":[],"note":""}},"tr":"사람들은 다른 사람의 행동은 쉽게 보지만, 그 뒤에 있는 감정은 놓치는 경우가 많다. 화나 보이는 사람도 사실 지치거나 걱정하고 있을 수 있다. 상대의 행동 아래 숨겨진 감정을 이해하려고 잠시 멈춰 보면, 우리는 더 부드럽게 반응할 수 있다. 이런 작은 노력은 작은 갈등을 이해의 순간으로 바꿀 수 있다.","ex":{"flow":"화나 보이는 사람이 실은 피곤하거나 걱정하는 것일 수 있으니, 행동 밑의 감정을 이해하려 하면 더 부드럽게 반응하게 된다는 내용.","b":{"A":["compassionate 형) 동정심 있는, 연민 어린","respond more gently","com(함께)+passion(고통) → 함께 아파하는. 명사 compassion"]}}},{"id":"q16","no":16,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"How We Judge What Is True","pas":"People often think they see the world exactly as it is. But our experiences, memories, and emotions shape how we understand events. One person may view a situation as unfair, while another sees it as normal. By noticing these different viewpoints, we learn that understanding is not fixed but influenced by many factors.","sum":"While truth may seem (A), people often understand it in a (B) way.","gloss":"진리가 절대적으로 보일 수 있지만, 사람들은 그것을 종종 상대적으로 이해한다.","bl":{"A":[{"first":"a","len":8,"sfx":""}],"B":[{"first":"r","len":8,"sfx":""}]},"key":{"A":{"w":"absolute","acc":["absolute"],"freq":false,"src":[],"note":""},"B":{"w":"relative","acc":["relative"],"freq":false,"src":[],"note":""}},"tr":"사람들은 세상을 있는 그대로 본다고 생각하곤 한다. 하지만 우리의 경험, 기억, 감정이 사건을 이해하는 방식을 결정한다. 어떤 사람은 한 상황을 불공평하다고 느끼고, 다른 사람은 당연하다고 느낀다. 이런 관점 차이를 살펴보면, 이해는 고정된 것이 아니라 여러 요소에 의해 달라진다는 것을 알게 된다.","ex":{"flow":"사람들은 세상을 있는 그대로 본다고 생각하지만, 경험·기억·감정이 이해를 바꾸므로 이해는 고정된 것이 아니라는 내용.","b":{"A":["absolute 형) 절대적인","see the world exactly as it is / fixed","부사 absolutely. 반의어 relative"],"B":["relative 형) 상대적인","influenced by many factors / different viewpoints","명사로는 \"친척\". 부사 relatively"]}}},{"id":"q17","no":17,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"When Limits Shape New Ideas","pas":"Many people think creativity only appears when there are no rules. But small limits can actually help people focus and discover new solutions. For example, using only a few colors can inspire unique artwork, and writing with a short time limit can lead to quick, original ideas. Sometimes, having less freedom pushes people to think in more interesting ways.","sum":"While full freedom seems (A), (B) rules can sometimes increase creativity.","gloss":"완전한 자유가 이상적으로 보이지만, 때로는 제한적 규칙이 창의성을 높인다.","bl":{"A":[{"first":"i","len":5,"sfx":""}],"B":[{"first":"r","len":11,"sfx":""}]},"key":{"A":{"w":"ideal","acc":["ideal"],"freq":false,"src":[],"note":""},"B":{"w":"restrictive","acc":["restrictive"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 규칙이 없을 때만 창의성이 나온다고 생각한다. 하지만 작은 제한은 사람들에게 집중할 기회를 주고 새로운 해결책을 찾게 해 줄 수 있다. 예를 들어 적은 색만 사용해야 하는 상황이 특별한 작품을 만들기도 하고, 짧은 시간 안에 글을 써야 할 때 독창적인 아이디어가 떠오르기도 한다. 때로는 자유가 적을수록 사람들이 더 흥미로운 방식으로 생각하게 만든다.","ex":{"flow":"창의성은 규칙이 없어야 나온다고 생각하지만, 적은 색만 쓰거나 시간 제한을 두는 등의 작은 제약이 오히려 집중과 새로운 해법을 이끈다는 내용.","b":{"A":["ideal 형) 이상적인","Many people think creativity only appears when there are no rules","seem + 형용사. 명사로 \"이상\""],"B":["restrictive 형) 제한하는, 제약하는","small limits / having less freedom","restrict(제한하다)+-ive. 명사 restriction"]}}},{"id":"q18","no":18,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Free Services That Make Experiences Better","pas":"Many places offer small free services to make visitors feel welcome. Hotels may give free water or snacks, and museums sometimes provide free guides for first-time guests. These simple gifts do not cost much, but they make people feel more relaxed and cared for. Small acts like these often improve the overall experience.","sum":"(A) items help visitors feel more welcome.","gloss":"무료(의) 제공품은 손님을 더 환영받는 느낌으로 만든다.","bl":{"A":[{"first":"C","len":13,"sfx":""}]},"key":{"A":{"w":"Complimentary","acc":["Complimentary"],"freq":false,"src":[],"note":""}},"tr":"많은 장소에서는 손님이 더 환영받는 느낌을 느끼도록 작은 무료 서비스를 제공한다. 호텔은 무료 물이나 간식을 주기도 하고, 박물관은 처음 온 방문객에게 무료 가이드를 제공하기도 한다. 이런 작은 서비스는 큰 비용이 들지 않지만, 사람들에게 편안함과 배려받는 느낌을 준다. 이와 같은 작은 행동들이 전체적인 경험을 더 좋게 만든다.","ex":{"flow":"호텔의 무료 물, 박물관의 무료 가이드처럼 작은 무료 서비스가 방문객을 환영받는 느낌이 들게 한다는 내용.","b":{"A":["Complimentary 형) 무료의, 칭찬하는","free water or snacks / free guides / These simple gifts","문장 맨 앞 대문자. -i- 철자 주의: complementary(보완적인)와 혼동 금지"]}}},{"id":"q19","no":19,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why We Feel Two Things at the Same Time","pas":"People sometimes experience mixed feelings about the same situation. For example, someone may feel excited about a new job but also nervous about the change. These emotions appear together because life often gives us both positive and difficult moments. Understanding this helps people accept their feelings instead of trying to hide them.","sum":"People often feel (A) emotions in one situation.","gloss":"사람들은 하나의 상황에서 모순된 감정을 느끼곤 한다.","bl":{"A":[{"first":"c","len":13,"sfx":""},{"first":"a","len":10,"sfx":""}]},"key":{"A":{"w":"contradictory / ambivalent","acc":["contradictory","ambivalent"],"freq":false,"src":[],"note":""}},"tr":"사람들은 같은 상황에 대해 서로 다른 감정을 동시에 느끼기도 한다. 예를 들어 새로운 직장을 두고 설레면서도 변화가 두려울 수 있다. 이런 감정이 함께 나타나는 이유는, 삶이 좋은 순간과 어려운 순간을 함께 주기 때문이다. 이 사실을 이해하면 감정을 숨기기보다 그대로 받아들이는 데 도움이 된다.","ex":{"flow":"새 직장이 설레면서도 긴장되듯, 같은 상황에 엇갈린 감정이 함께 나타난다는 내용.","b":{"A":["contradictory / ambivalent 형) 모순된, 상반된 / (감정이) 양면적인","mixed feelings / excited … but also nervous","두 단어 모두 정답(c 13칸, a 10칸). ambi(양쪽)+val(가치) → 양쪽 마음이 다 있는"]}}},{"id":"q20","no":20,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Misunderstandings Happen Easily","pas":"People often judge others based on quick impressions. When they see something confusing, they may assume the worst instead of asking questions. For example, a person who seems quiet might simply be tired, not unfriendly. By taking time to listen and ask, we can avoid unnecessary conflict and understand situations more clearly.","sum":"Because quick (A)(s) create misunderstanding, they often lead to wrong (B).","gloss":"성급한 판단은 오해를 만들고, 잘못된 비난으로 이어지기도 한다.","bl":{"A":[{"first":"j","len":8,"sfx":"(s)"}],"B":[{"first":"a","len":10,"sfx":""}]},"key":{"A":{"w":"judgment(s)","acc":["judgment(s)"],"freq":false,"src":[],"note":""},"B":{"w":"accusation","acc":["accusation"],"freq":false,"src":[],"note":""}},"tr":"사람들은 짧은 인상만으로 다른 사람을 판단하는 경우가 많다. 헷갈리는 상황을 보면 질문하기보다 나쁘게 추측하기도 한다. 예를 들어 조용한 사람은 불친절해서가 아니라 단지 피곤한 것일 수도 있다. 잠시 시간을 내어 듣고 질문해 보면, 불필요한 갈등을 피하고 더 정확하게 이해할 수 있다.","ex":{"flow":"사람들은 첫인상으로 판단하고 헷갈리면 최악을 가정하지만, 듣고 물어보면 불필요한 갈등을 피할 수 있다는 내용.","b":{"A":["judgment 명) 판단","judge others based on quick impressions","빈칸 뒤 (s) → judgments. 영국식 judgement도 쓰지만 이 칸은 8칸 judgment"],"B":["accusation 명) 비난, 고발","assume the worst / unnecessary conflict","동사 accuse A of B = A를 B로 비난하다. wrong accusations = 억울한 비난"]}}}]},{"r":5,"qs":[{"id":"q01","no":1,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":null,"pas":"Many students think talent alone leads to success, but this is rarely true. Researchers explain that steady practice builds skills much more effectively than natural ability. Even small daily efforts can create big improvements over time. Because of this, teachers encourage students to keep working, even when progress feels slow.","sum":"Success in learning comes from 99% (A) and 1% (B), showing that steady effort matters more than talent.","gloss":"학습의 성공은 재능보다 99%의 땀과 1%의 영감에서 오며, 꾸준한 노력이 훨씬 중요하다는 것을 보여준다.","bl":{"A":[{"first":"p","len":12,"sfx":""}],"B":[{"first":"i","len":11,"sfx":""}]},"key":{"A":{"w":"perspiration","acc":["perspiration"],"freq":false,"src":[],"note":""},"B":{"w":"inspiration","acc":["inspiration"],"freq":false,"src":[],"note":""}},"tr":"많은 학생들은 재능만으로 성공한다고 생각하지만, 실제로는 거의 그렇지 않다. 연구자들은 꾸준한 연습이 타고난 능력보다 훨씬 효과적으로 실력을 만든다고 설명한다. 작은 노력이라도 매일 쌓이면 시간이 지나 큰 발전을 만든다. 그래서 교사들은 진전이 느리게 보여도 계속 노력하라고 학생들을 격려한다.","ex":{"flow":"재능만으로 성공한다는 생각과 달리 꾸준한 연습이 타고난 능력보다 훨씬 효과적이라는 내용. 에디슨의 \"천재는 99%의 땀과 1%의 영감\"을 빌린 요약문.","b":{"A":["perspiration 명) 땀, 노력","steady practice / small daily efforts / keep working","per(통해)+spir(숨 쉬다). 동사 perspire. inspiration과 철자가 비슷하니 첫 글자로 구분"],"B":["inspiration 명) 영감","talent alone / natural ability","in(안으로)+spir(숨) → 숨을 불어넣다. 동사 inspire"]}}},{"id":"q02","no":2,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":null,"pas":"Some illnesses start with mild symptoms that seem easy to ignore. However, inside the body, the problem can grow quickly if it is not found early. Doctors encourage regular check-ups because they help catch changes before they become serious. When people understand their health signs, they can take action sooner and protect themselves better.","sum":"Early (A) prevents small health issues from becoming (B).","gloss":"조기 발견은 작은 건강 문제가 치명적으로 되는 것을 막아준다.","bl":{"A":[{"first":"d","len":9,"sfx":""}],"B":[{"first":"f","len":5,"sfx":""}]},"key":{"A":{"w":"detection","acc":["detection"],"freq":false,"src":[],"note":""},"B":{"w":"fatal","acc":["fatal"],"freq":false,"src":[],"note":""}},"tr":"어떤 질병은 가볍고 무시하기 쉬운 증상으로 시작된다. 하지만 몸 안에서는 문제가 빨리 커질 수 있기 때문에, 초기에 발견되지 않으면 위험해질 수 있다. 그래서 의사들은 정기 검진을 권하며, 이는 큰 문제가 되기 전에 변화를 발견하도록 도와준다. 자신의 건강 신호를 이해하면 더 빨리 대응하고 스스로를 보호할 수 있다.","ex":{"flow":"가벼운 증상도 일찍 발견하지 않으면 몸속에서 빠르게 커질 수 있어, 정기 검진으로 변화를 미리 잡아야 한다는 내용.","b":{"A":["detection 명) 발견, 탐지","if it is not found early / help catch changes","early detection = 조기 발견. 동사 detect. 문장 주어 자리 → 명사"],"B":["fatal 형) 치명적인","before they become serious / grow quickly","become + 형용사. 명사 fatality(사망자). 유의어 deadly, lethal"]}}},{"id":"q03","no":3,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How Nature Breaks Down Old Materials","pas":"In forests and fields, fallen leaves, old plants, and animal remains do not stay the same forever. Tiny organisms in the soil slowly change these materials into simpler substances. This process returns important nutrients to the ground, helping new plants grow. Without this natural cycle, the environment would quickly run out of the resources it needs.","sum":"Small organisms help dead materials (A) in nature.","gloss":"자연에서는 작은 생물들이 죽은 물질을 분해하는 것을 도와준다.","bl":{"A":[{"first":"d","len":9,"sfx":""}]},"key":{"A":{"w":"decompose","acc":["decompose"],"freq":false,"src":[],"note":""}},"tr":"숲이나 들판에서는 떨어진 잎, 오래된 식물, 동물의 흔적이 영원히 그대로 남아 있지 않는다. 흙 속의 작은 생물들이 이런 물질을 천천히 더 단순한 형태로 바꾼다. 이 과정은 중요한 영양분을 땅으로 돌려보내, 새 식물이 자라는 데 도움을 준다. 이런 자연 순환이 없다면, 환경은 필요한 자원을 금방 잃게 될 것이다.","ex":{"flow":"낙엽과 동물 사체를 흙 속 작은 생물이 더 단순한 물질로 바꿔 땅에 영양분을 돌려준다는 내용.","b":{"A":["decompose 동) 분해되다, 부패하다","change these materials into simpler substances / Breaks Down","help + 목적어 + 동사원형. de(반대)+compose(구성하다). 명사 decomposition"]}}},{"id":"q04","no":4,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"How People Preserve Culture in Difficult Places","pas":"Human groups have settled in many challenging locations around the world. Some communities live in areas with very little water or extreme temperatures. Despite these difficulties, they pass down stories, skills, and customs through each generation. Researchers study these groups to understand how people protect their way of life even when conditions are tough.","sum":"Culture can remain (A) even when people live in a (B) environment.","gloss":"문화는 온전히(손상되지 않고) 유지될 수 있다 심지어 사람들이 가혹한 환경에서 살고 있을 때에도.","bl":{"A":[{"first":"i","len":6,"sfx":""}],"B":[{"first":"h","len":5,"sfx":""}]},"key":{"A":{"w":"intact","acc":["intact"],"freq":false,"src":[],"note":""},"B":{"w":"harsh","acc":["harsh"],"freq":false,"src":[],"note":""}},"tr":"인간 집단은 전 세계의 어려운 환경에서도 삶의 터전을 만들어 왔다. 어떤 공동체는 물 부족이나 극심한 기온 같은 조건 속에서 생활한다. 이런 어려움 속에서도 그들은 이야기, 기술, 관습을 세대마다 전해 유지한다. 연구자들은 이런 집단을 통해 힘든 조건에서도 사람들이 어떻게 문화를 지켜 나가는지 이해한다.","ex":{"flow":"물이 거의 없거나 기온이 극단적인 곳에서도 사람들은 이야기·기술·관습을 대대로 전하며 삶의 방식을 지킨다는 내용.","b":{"A":["intact 형) 손상되지 않은, 온전한","pass down stories, skills, and customs / protect their way of life","remain + 형용사. in(부정)+tact(만지다) → 손대지 않은"],"B":["harsh 형) 가혹한, 혹독한","very little water or extreme temperatures / conditions are tough","a harsh environment/climate. 유의어 severe"]}}},{"id":"q05","no":5,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Small Problems in Relationships","pas":"In friendships, tiny misunderstandings can happen without anyone noticing at first. People may assume things or stay quiet instead of asking what is wrong. When this continues, feelings get heavier and communication becomes harder. Taking a moment to talk openly can help rebuild trust and keep the relationship healthy.","sum":"While problems start small, they can (A) quickly without open communication.","gloss":"문제는 작게 시작되지만, 열린 소통이 없으면 빠르게 악화될 수 있다.","bl":{"A":[{"first":"w","len":6,"sfx":""}]},"key":{"A":{"w":"worsen","acc":["worsen"],"freq":false,"src":[],"note":""}},"tr":"우정이나 인간관계에서는 작은 오해가 처음엔 티 나지 않게 생길 수 있다. 사람들은 질문하기보다 혼자 추측하거나 조용히 넘어가기도 한다. 이런 상황이 계속되면 감정이 무거워지고 소통이 점점 더 어려워진다. 솔직하게 대화하는 시간은 신뢰를 다시 쌓고 관계를 건강하게 유지하는 데 도움이 된다.","ex":{"flow":"친구 사이 작은 오해가 묻어 두면 감정이 무거워지고 대화가 어려워지지만, 솔직하게 이야기하면 신뢰를 되찾는다는 내용.","b":{"A":["worsen 동) 악화되다","feelings get heavier and communication becomes harder","can + 동사 원형. worse+-en(~하게 되다). 반의어 improve"]}}},{"id":"q06","no":6,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Some Technologies Do Not Work Well Together","pas":"As technology develops, new devices and programs appear every year. Some tools are designed by different companies and use their own systems. When people try to connect these tools, they sometimes face problems because the systems follow different rules. Understanding how each system works helps users choose tools that can function smoothly together.","sum":"Different systems can be (A) when they follow (B) rules.","gloss":"시스템들이 분리된 규칙을 따를 때 다른 시스템은 양립하지 못할 수 있다.","bl":{"A":[{"first":"i","len":12,"sfx":""}],"B":[{"first":"s","len":8,"sfx":""}]},"key":{"A":{"w":"incompatible","acc":["incompatible"],"freq":false,"src":[],"note":""},"B":{"w":"separate","acc":["separate"],"freq":false,"src":[],"note":""}},"tr":"기술이 발전하면서 새로운 기기와 프로그램이 매년 만들어진다. 일부 도구들은 서로 다른 회사에서 만들어져 각자의 시스템을 사용한다. 사람들이 이런 도구들을 연결하려고 하면, 규칙이 달라서 잘 작동하지 않는 문제가 생기기도 한다. 각 시스템이 어떻게 작동하는지 이해하면, 서로 잘 호환되는 도구를 선택하는 데 도움이 된다.","ex":{"flow":"회사마다 자기 시스템을 써서, 서로 다른 규칙을 따르는 도구를 연결하면 문제가 생긴다는 내용.","b":{"A":["incompatible 형) 호환되지 않는, 양립할 수 없는","face problems when they try to connect these tools","in+compatible(호환되는). 반의어 compatible. function smoothly together와 반대"],"B":["separate 형) 별개의, 각자의","use their own systems / follow different rules","2회 19번과 같은 단어. sep-a-rate 철자"]}}},{"id":"q07","no":7,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"How People Recover After Difficult Experiences","pas":"Everyone faces moments that feel heavy or stressful. Some people take longer to feel better, while others slowly rebuild their energy by following daily routines. Talking to supportive friends or taking small steps forward can help the mind regain strength. Over time, these efforts make future challenges feel less heavy.","sum":"While stress can feel (A), steady effort brings back (B) over time.","gloss":"스트레스가 압도적이라고 느껴지더라도 꾸준한 노력은 시간이 지나며 회복력을 되찾게 한다.","bl":{"A":[{"first":"o","len":12,"sfx":""}],"B":[{"first":"r","len":10,"sfx":""}]},"key":{"A":{"w":"overwhelming","acc":["overwhelming"],"freq":false,"src":[],"note":""},"B":{"w":"resilience","acc":["resilience"],"freq":false,"src":[],"note":""}},"tr":"모든 사람은 무겁고 스트레스가 큰 순간을 겪는다. 어떤 사람은 회복하는 데 시간이 더 걸리고, 어떤 사람은 일상 루틴을 유지하며 천천히 힘을 되찾는다. 응원해주는 친구와 이야기하거나 작은 행동부터 다시 시작하는 것이 마음의 힘을 회복하는 데 도움이 된다. 시간이 지나면 이런 노력은 다음 어려움이 덜 부담스럽게 느껴지도록 만들어 준다.","ex":{"flow":"누구나 힘든 순간을 겪지만 일상 루틴과 친구와의 대화, 작은 걸음으로 마음이 다시 힘을 되찾는다는 내용.","b":{"A":["overwhelming 형) 압도적인, 감당하기 힘든","moments that feel heavy or stressful","can feel + 형용사. 동사 overwhelm. 원본의 쉼표 위치를 바로잡은 문항"],"B":["resilience 명) 회복력","regain strength / rebuild their energy","1회 8번과 같은 단어. bring back = 되찾게 하다"]}}},{"id":"q08","no":8,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why We Sometimes Do More Than We Need","pas":"People often add extra steps when trying to solve a simple problem. They may overthink a choice or repeat actions even when one attempt is enough. This happens because the mind seeks control, especially when people feel uncertain.","sum":"Because (A) makes people seek control, they perform (B) actions.","gloss":"불확실성이 사람들로 하여금 통제를 원하게 만들어, 불필요한 행동을 하게 된다.","bl":{"A":[{"first":"u","len":11,"sfx":""}],"B":[{"first":"u","len":11,"sfx":""}]},"key":{"A":{"w":"uncertainty","acc":["uncertainty"],"freq":false,"src":[],"note":""},"B":{"w":"unnecessary","acc":["unnecessary"],"freq":false,"src":[],"note":""}},"tr":"사람들은 간단한 문제를 해결할 때도 불필요한 단계를 더하는 경우가 있다. 선택을 지나치게 고민하거나, 한 번이면 충분한 행동을 여러 번 반복하기도 한다. 이런 일은 사람들이 불확실할 때 통제감을 느끼려 하기 때문이다.","ex":{"flow":"간단한 문제에도 단계를 더하거나 한 번이면 될 행동을 반복하는 것은 불확실할 때 마음이 통제를 원하기 때문이라는 내용.","b":{"A":["uncertainty 명) 불확실성","especially when people feel uncertain","makes(단수 동사)의 주어 → 명사. 형용사 uncertain"],"B":["unnecessary 형) 불필요한","add extra steps / repeat actions even when one attempt is enough","un+necessary. c 하나, s 두 개"]}}},{"id":"q09","no":9,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Some People Stay Quiet in Conversations","pas":"In group discussions, not everyone speaks with the same confidence. Some people listen carefully but hesitate to share their thoughts right away. They may worry about being misunderstood or cutting into someone’s turn to speak. When conversations feel safe and welcoming, more people begin to share their ideas more comfortably.","sum":"Some people become (A) in conversations because they fear (B) others.","gloss":"몇몇 사람들은 대화에서 소극적이 된다. 그들이 다른 사람에게 끼어드는 것을 두려워하기 때문이다.","bl":{"A":[{"first":"p","len":7,"sfx":""}],"B":[{"first":"i","len":12,"sfx":""}]},"key":{"A":{"w":"passive","acc":["passive"],"freq":false,"src":[],"note":""},"B":{"w":"interrupting","acc":["interrupting"],"freq":false,"src":[],"note":""}},"tr":"그룹 토론에서 모든 사람이 같은 자신감으로 말하는 것은 아니다. 어떤 사람들은 주의 깊게 듣지만 바로 자신의 생각을 공유하는 것을 주저한다. 오해를 받거나 다른 사람을 말을 자르게 될까봐 걱정할 수도 있다. 대화가 안전하고 반갑게 느껴질 때 더 많은 사람들이 자신의 생각을 더 편안하게 공유하기 시작한다.","ex":{"flow":"토론에서 어떤 사람들은 오해받거나 다른 사람 말할 차례를 끊을까 봐 생각을 바로 말하지 못한다는 내용.","b":{"A":["passive 형) 소극적인, 수동적인","listen carefully but hesitate to share their thoughts","become + 형용사. 반의어 active"],"B":["interrupting 동) 방해하는 것, 끼어드는 것 (동명사)","cutting into someone’s turn to speak","fear + 동명사 → interrupting. inter(사이)+rupt(깨다). r 두 개"]}}},{"id":"q10","no":10,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Some Areas Hold More Life Than Others","pas":"In nature, living things do not spread evenly across every place. Some regions have plenty of sunlight, water, and food, making it easier for many organisms to survive. Other places have fewer resources, so only a small number of species can live there. By studying how conditions vary, scientists learn why certain places support more life than others.","sum":"Areas with more resources often have a more (A) population of living organisms.","gloss":"자원이 많은 지역들은 종종 더 밀집된 인구의 생명체를 가진다.","bl":{"A":[{"first":"d","len":5,"sfx":""}]},"key":{"A":{"w":"dense","acc":["dense"],"freq":false,"src":[],"note":""}},"tr":"자연에서는 생명체가 모든 곳에 똑같이 분포하지 않는다. 어떤 지역은 햇빛, 물, 먹이가 풍부해서 많은 생물들이 살아가기 쉽다. 반대로 자원이 적은 지역은 소수의 생물만 살 수 있다. 이런 환경 조건의 차이를 연구하면, 왜 어떤 곳은 더 많은 생명체가 모여 사는지 이해할 수 있다.","ex":{"flow":"햇빛·물·먹이가 풍부한 지역엔 많은 생물이 살고, 자원이 적은 곳엔 적은 종만 산다는 내용.","b":{"A":["dense 형) 밀집한, 빽빽한","many organisms to survive","a dense population = 밀집 인구. 명사 density. 반의어 sparse"]}}},{"id":"q11","no":11,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Different Survival Strategies in Nature","pas":"Animals do not survive in the same way. Some species avoid danger by hiding quietly, while others stay active and move quickly to escape threats. Both strategies help them stay alive, but each works better in different environments. By studying these patterns, scientists learn how living things adjust to the challenges around them.","sum":"Because habitats (A), species develop (B) reactions to danger.","gloss":"서식지가 다양하기 때문에 종들은 위험에 대해 반대 방식으로 반응한다.","bl":{"A":[{"first":"v","len":4,"sfx":""}],"B":[{"first":"o","len":8,"sfx":""}]},"key":{"A":{"w":"vary","acc":["vary"],"freq":false,"src":[],"note":""},"B":{"w":"opposite","acc":["opposite"],"freq":false,"src":[],"note":""}},"tr":"동물들은 똑같은 방식으로 생존하지 않는다. 어떤 종은 조용히 숨으며 위험을 피하고, 다른 종은 빠르게 움직여 위협에서 벗어난다. 두 전략 모두 생존에 도움이 되지만, 각각 특정 환경에서 더 효과적이다. 과학자들은 이런 생존 패턴을 통해 생물들이 주변의 다양한 도전에 어떻게 적응하는지 연구한다.","ex":{"flow":"조용히 숨는 종도 있고 빠르게 움직여 도망치는 종도 있으며, 각 전략은 다른 환경에서 더 잘 통한다는 내용.","b":{"A":["vary 동) 다양하다, 서로 다르다","each works better in different environments","habitats(복수) + 동사 원형. 형용사 various, 명사 variety"],"B":["opposite 형) 반대의","hiding quietly ↔ stay active and move quickly","reactions를 꾸미는 형용사. be opposite to ~. 명사 opposition"]}}},{"id":"q12","no":12,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":null,"pas":"Many viruses spread easily because they attach quickly to cells in the human body. Scientists study how these tiny organisms enter cells so they can create better treatments. Some studies show that small changes in a virus can make it harder to control. Understanding these changes helps doctors respond faster during outbreaks.","sum":"Scientists study how viruses change and spread so people can become more (A) to future outbreaks.","gloss":"과학자들은 사람들이 미래의 유행병에 더 면역이 될 수 있도록 바이러스의 변화와 확산을 연구한다.","bl":{"A":[{"first":"i","len":6,"sfx":""}]},"key":{"A":{"w":"immune","acc":["immune"],"freq":false,"src":[],"note":""}},"tr":"많은 바이러스는 인간 몸의 세포에 빠르게 달라붙기 때문에 쉽게 퍼진다. 과학자들은 더 나은 치료법을 만들기 위해 이 작은 존재들이 세포에 어떻게 들어가는지 연구한다. 일부 연구는 바이러스의 작은 변화가 통제하기 더 어렵게 만들 수 있다고 보여준다. 이런 변화를 이해하는 것은 의료진이 유행 상황에서 더 빨리 대응하는 데 도움이 된다.","ex":{"flow":"바이러스는 세포에 빨리 달라붙어 쉽게 퍼지고, 과학자들은 더 나은 치료와 빠른 대응을 위해 그 변화를 연구한다는 내용.","b":{"A":["immune 형) 면역이 있는","create better treatments / respond faster during outbreaks","be immune to ~ = ~에 면역이 있다. 명사 immunity, 동사 immunize"]}}},{"id":"q13","no":13,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":null,"pas":"When the body experiences strain or injury, it sends signals to the brain to show that something is wrong. Doctors often recommend rest, light movement, or warm compresses to support the body’s natural recovery. These actions help reduce tension and allow the injured area to heal more effectively. By understanding how the body reacts, people can make better choices during recovery.","sum":"While discomfort is natural after injury, proper care can (A) the pain and speed recovery.","gloss":"부상 후 불편함은 자연스럽지만, 적절한 관리는 고통을 덜어주고 회복을 빠르게 한다.","bl":{"A":[{"first":"a","len":9,"sfx":""}]},"key":{"A":{"w":"alleviate","acc":["alleviate"],"freq":false,"src":[],"note":""}},"tr":"몸이 무리하거나 다치면, 뭔가 잘못되었다는 신호를 뇌로 보낸다. 의사들은 보통 휴식, 가벼운 움직임, 따뜻한 찜질 등을 권해 자연스러운 회복을 돕는다. 이런 방법들은 긴장을 줄이고, 손상된 부위가 더 잘 회복되도록 해 준다. 몸이 어떻게 반응하는지 알면, 회복 과정에서 더 좋은 선택을 할 수 있다.","ex":{"flow":"몸에 부상이 생기면 휴식·가벼운 움직임·온찜질로 회복을 돕고, 이런 조치가 긴장을 줄인다는 내용.","b":{"A":["alleviate 동) 완화하다, 덜어 주다","help reduce tension / heal more effectively","can + 동사 원형. al+lev(가볍게 하다). 유의어 relieve, ease. l 두 개"]}}},{"id":"q14","no":14,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Careful Preparation Makes Life Easier","pas":"Many people think problems appear suddenly, but most difficulties grow slowly over time. When someone ignores small tasks—like cleaning a workspace or planning their day—stress begins to build. However, taking a little time to organize things helps people feel clearer and more in control. This simple habit makes it easier to face bigger challenges when they arrive.","sum":"While (A) small duties creates confusion, a (B) approach brings clarity and control.","gloss":"작은 일들을 무시하는 것은 혼란을 만들지만, 철저한 접근은 명확함과 통제력을 준다.","bl":{"A":[{"first":"i","len":8,"sfx":""}],"B":[{"first":"t","len":8,"sfx":""}]},"key":{"A":{"w":"ignoring","acc":["ignoring"],"freq":false,"src":[],"note":""},"B":{"w":"thorough","acc":["thorough"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 문제가 갑자기 생긴다고 생각하지만, 대부분의 어려움은 천천히 쌓여 나타난다. 작은 일들—작업 공간 정리나 하루 계획 세우기—을 무시하면 스트레스가 차곡차곡 쌓인다. 그러나 조금만 시간을 들여 정리하고 준비하면, 마음이 더 명확해지고 통제력이 생긴다. 이런 작은 습관은 더 큰 문제를 마주할 때 훨씬 쉽게 대처하도록 도와준다.","ex":{"flow":"대부분의 어려움은 천천히 커지고, 작은 일을 무시하면 스트레스가 쌓이지만, 조금씩 정리하면 더 분명하고 통제감 있게 느낀다는 내용.","b":{"A":["ignoring 동) 무시하기 (동명사)","When someone ignores small tasks","빈칸이 주어 + 목적어(small duties)를 가짐 → 동명사 ignoring"],"B":["thorough 형) 철저한, 빈틈없는","taking a little time to organize things","a thorough approach. through(~을 통해), though(비록)와 철자 혼동 주의"]}}},{"id":"q15","no":15,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Strength and Skill Must Grow Together","pas":"Many people believe that being a good person means avoiding conflict and staying quiet. However, life often brings situations where calm behavior is not enough. When individuals develop real skills, they also gain the strength to protect themselves and others. This combination—ability and controlled power—helps people act wisely and face challenges without fear.","sum":"Real strength comes from becoming (A) and knowing how to use power wisely.","gloss":"진짜 힘은 유능한 상태가 되고, 그 힘을 현명하게 쓰는 데서부터 온다.","bl":{"A":[{"first":"c","len":9,"sfx":""}]},"key":{"A":{"w":"competent","acc":["competent"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 착한 사람은 갈등을 피하고 조용해야 한다고 생각한다. 하지만 현실에서는 침착함만으로 해결되지 않는 순간도 찾아온다. 사람이 진짜 능력을 키우면, 자신과 주변을 지킬 수 있는 힘도 갖게 된다. 이처럼 능력과 통제된 힘이 함께할 때, 사람은 두려움 없이 현명하게 문제를 마주할 수 있다.","ex":{"flow":"좋은 사람이 되는 것이 갈등을 피하는 것만은 아니며, 실력을 기를 때 자신과 남을 지킬 힘도 생긴다는 내용.","b":{"A":["competent 형) 유능한, 능숙한","develop real skills / ability","become + 형용사. 명사 competence. compete(경쟁하다)와 구분"]}}},{"id":"q16","no":16,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Different Speeds of Health Problems","pas":"Some health conditions develop slowly over a long period, making the signs easy to miss. Others appear suddenly and cause strong discomfort in a short time. Doctors study these patterns to understand how fast a problem is growing and what treatment will work best. By watching changes in the body, people can respond at the right time and avoid bigger risks.","sum":"While (A) issues are slow and long-lasting, (B) problems create quick and intense symptoms.","gloss":"만성적 문제는 느리고 오래가지만, 급성적 문제는 빠르고 강한 증상을 만든다.","bl":{"A":[{"first":"c","len":7,"sfx":""}],"B":[{"first":"a","len":5,"sfx":""}]},"key":{"A":{"w":"chronic","acc":["chronic"],"freq":false,"src":[],"note":""},"B":{"w":"acute","acc":["acute"],"freq":false,"src":[],"note":""}},"tr":"일부 건강 문제는 오랜 시간에 걸쳐 천천히 진행되어, 증상이 눈에 잘 띄지 않을 수 있다. 반면 어떤 문제는 갑자기 나타나고 짧은 시간 안에 큰 불편을 일으킨다. 의사들은 이런 패턴을 연구해 문제가 얼마나 빨리 자라는지, 그리고 어떤 치료가 가장 효과적인지 판단한다. 몸의 변화를 관찰하면, 적절한 시기에 대응해 더 큰 위험을 피할 수 있다.","ex":{"flow":"어떤 병은 오래 천천히 진행되어 징후를 놓치기 쉽고, 어떤 병은 갑자기 나타나 짧은 시간에 심한 증상을 낸다는 내용.","b":{"A":["chronic 형) 만성의","develop slowly over a long period","chron(시간) 어원: chronicle, synchronize. 반의어 acute"],"B":["acute 형) 급성의, 극심한","appear suddenly and cause strong discomfort in a short time","\"예리한\"이라는 뜻도 있음(acute sense of smell)"]}}},{"id":"q17","no":17,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Avoiding Challenges Holds People Back","pas":"Many people try to stay comfortable because they fear making mistakes. They choose easier tasks and avoid situations that push them to grow. However, comfort alone does not help a person develop new skills or become stronger. When individuals accept small difficulties, they learn more about themselves and discover abilities they did not notice before.","sum":"While comfort feels safe, it can be a (A), and the (B) is that real growth never starts.","gloss":"편안함은 안전해 보이지만, 그것이 한계가 되고, 단점(결점)은 진짜 성장이 시작되지 않는다는 점이다.","bl":{"A":[{"first":"l","len":10,"sfx":""}],"B":[{"first":"d","len":8,"sfx":""}]},"key":{"A":{"w":"limitation","acc":["limitation"],"freq":false,"src":[],"note":""},"B":{"w":"drawback","acc":["drawback"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 실수를 두려워해서 편안함만 유지하려고 한다. 그래서 더 쉬운 일만 선택하고, 자신을 성장시키는 상황은 피한다. 하지만 편안함만으로는 새로운 능력을 키우거나 강해질 수 없다. 작은 어려움을 받아들이면, 사람은 자신을 더 깊이 이해하고 몰랐던 능력을 발견하게 된다.","ex":{"flow":"실수가 두려워 편한 것만 고르면 새 기술이나 힘을 기를 수 없고, 작은 어려움을 받아들일 때 몰랐던 능력을 발견한다는 내용.","b":{"A":["limitation 명) 한계, 제약","comfort alone does not help a person develop / Holds People Back","a + 명사. 동사 limit"],"B":["drawback 명) 단점, 결점","avoid situations that push them to grow","the drawback is that ~ = 단점은 ~라는 것이다. 유의어 disadvantage"]}}},{"id":"q18","no":18,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Some Innovations Spread Faster Than Others","pas":"When a new idea or tool appears, not every society accepts it at the same speed. Some communities quickly try new methods because they want to improve daily life. Others wait longer, observing how the change affects people in different places. Researchers study these patterns to understand why certain groups embrace new practices while others remain cautious.","sum":"Different societies show the (A) of new ideas at different speeds.","gloss":"사회마다 새로운 아이디어의 채택 속도가 다르다.","bl":{"A":[{"first":"a","len":8,"sfx":""}]},"key":{"A":{"w":"adoption","acc":["adoption"],"freq":false,"src":[],"note":""}},"tr":"새로운 아이디어나 도구가 등장해도, 모든 사회가 같은 속도로 받아들이는 것은 아니다. 어떤 공동체는 일상생활을 더 나아지게 하고 싶어 새로운 방식을 빠르게 시도한다. 반면 다른 공동체는 변화가 다른 지역 사람들에게 어떤 영향을 주는지 지켜보며 천천히 결정한다. 연구자들은 이런 양상을 통해 어떤 집단은 변화를 쉽게 받아들이고, 어떤 집단은 더 신중한지 이해하려 한다.","ex":{"flow":"새 아이디어나 도구를 모든 사회가 같은 속도로 받아들이지 않고, 빨리 시도하는 곳과 신중하게 기다리는 곳이 있다는 내용.","b":{"A":["adoption 명) 채택, 도입 (입양)","accept it / embrace new practices","동사 adopt(채택하다). adapt(적응하다)·adaption과 혼동 주의"]}}},{"id":"q19","no":19,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Listening Matters When Someone Feels Upset","pas":"When a friend feels stressed or confused, people often try to give advice right away. However, not everyone wants quick answers. Sometimes, the person simply needs someone who will listen without giving any advice or offering a solution. By giving space and paying attention, we help others feel understood and supported.","sum":"Listening without (A) can help (B) someone who feels upset.","gloss":"판단 없이 들어주는 것은 힘든 사람을 위로해주는 것에 도움이 된다.","bl":{"A":[{"first":"j","len":9,"sfx":""}],"B":[{"first":"c","len":7,"sfx":""}]},"key":{"A":{"w":"judgement","acc":["judgement","judgment"],"freq":false,"src":[],"note":""},"B":{"w":"console","acc":["console"],"freq":false,"src":[],"note":""}},"tr":"친구가 스트레스를 받거나 혼란스러울 때, 사람들은 보통 바로 조언을 하려고 한다. 하지만 모든 사람이 즉각적인 해결책을 원하는 것은 아니다. 때로는 그 사람이 조언을 제공하거나 해결책을 제시하지 않고 그냥 들어주는 사람을 필요로 할 때도 있다. 공간을 주고 진심으로 귀 기울이는 행동은 상대가 이해받고 지지받는 느낌을 갖게 도와준다.","ex":{"flow":"힘든 친구에게 바로 조언하려 하지만, 때로는 조언 없이 들어 주는 사람이 필요하다는 내용.","b":{"A":["judgement 명) 판단, 평가","listen without giving any advice or offering a solution","without + 명사. 칸이 9칸이므로 judgement. 미국식 judgment(8자)도 정답 인정"],"B":["console 동) 위로하다","help others feel understood and supported","help + 동사원형. 명사 consolation. 명사 console(게임기, 계기판)과 구분"]}}},{"id":"q20","no":20,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How One Small Change Can Spread Through a Community","pas":"When people in a community begin using a new habit or idea, others often notice it. Some individuals copy the behavior because it looks useful, while others follow simply because many people are doing it. As more people join in, the new practice becomes part of daily life. This shows how even small actions can slowly shape the way a group thinks and behaves.","sum":"A small change can have a strong (A) on community behavior.","gloss":"작은 변화도 공동체 행동에 강력한 영향을 줄 수 있다.","bl":{"A":[{"first":"i","len":6,"sfx":""}]},"key":{"A":{"w":"impact","acc":["impact"],"freq":false,"src":[],"note":""}},"tr":"어떤 공동체에서 새로운 습관이나 아이디어가 사용되기 시작하면, 다른 사람들도 그것을 알아차린다. 일부 사람들은 실제로 도움이 돼 보여서 따라 하고, 또 다른 사람들은 많은 사람이 하니까 따라 한다. 점점 더 많은 사람이 참여하면 그 새로운 방식은 일상의 일부가 된다. 이런 과정은 작은 행동 하나도 공동체의 사고방식과 행동을 천천히 바꿀 수 있음을 보여준다.","ex":{"flow":"공동체에서 누군가 새 습관을 쓰면 다른 사람들이 따라 하고, 참여자가 늘수록 그 습관이 일상이 된다는 내용.","b":{"A":["impact 명) 영향, 충격","shape the way a group thinks and behaves","have an impact on ~ = ~에 영향을 미치다(have an effect on과 같음)"]}}}]},{"r":6,"qs":[{"id":"q01","no":1,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Understanding What People Don’t Say","pas":"People often focus on spoken words, but many feelings are shown without talking. A person’s face, posture, or small gestures can reveal if they are stressed, excited, or uncomfortable. Sometimes these signs appear before someone chooses the right words. By paying attention to these quiet signals, we can understand people more deeply.","sum":"Because people show feelings through (A) cues, we must look beyond (B) words.","gloss":"사람들은 감정을 비언어적 단서로 드러내기 때문에, 우리는 말해지는 표현 이면의 것을 볼 수 있어야 한다.","bl":{"A":[{"first":"n","len":9,"sfx":""}],"B":[{"first":"s","len":6,"sfx":""}]},"key":{"A":{"w":"nonverbal","acc":["nonverbal"],"freq":false,"src":[],"note":""},"B":{"w":"spoken","acc":["spoken"],"freq":false,"src":[],"note":""}},"tr":"사람들은 흔히 말로 표현된 것만 신경 쓰지만, 많은 감정은 말 없이도 드러난다. 표정, 자세, 작은 몸짓은 그 사람이 스트레스받았는지, 설렜는지, 불편한지 알려줄 수 있다. 때로는 이런 신호가 말보다 먼저 나타나기도 한다. 이 조용한 신호들을 살피면 사람을 더 깊이 이해할 수 있다.","ex":{"flow":"사람들은 말에 집중하지만 얼굴·자세·작은 몸짓처럼 말 없이도 감정이 드러나며, 이런 조용한 신호에 주의하면 사람을 더 깊이 이해한다는 내용.","b":{"A":["nonverbal 형) 비언어적인","face, posture, or small gestures / shown without talking","non(아닌)+verbal(말의). nonverbal cues = 비언어적 단서"],"B":["spoken 형) 말로 한, 구두의","spoken words","지문 표현 그대로. speak의 과거분사. 반의어 written"]}}},{"id":"q02","no":2,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Planning Helps People Avoid Stress","pas":"Many problems feel bigger when people wait until the last moment to deal with them. Tasks become rushed, and small mistakes are easier to make. But when individuals prepare early—by organizing materials or setting simple goals—they feel calmer and more focused. This early effort makes difficult situations easier to handle later.","sum":"Because (A) (B) reduces mistakes, completing tasks ahead of time makes challenges easier.","gloss":"사전 준비를 하면 실수가 줄어들기 때문에, 일을 미리 끝내두면 어려움이 훨씬 쉬워진다.","bl":{"A":[{"first":"p","len":5,"sfx":""}],"B":[{"first":"p","len":11,"sfx":""}]},"key":{"A":{"w":"prior","acc":["prior"],"freq":false,"src":[],"note":""},"B":{"w":"preparation","acc":["preparation"],"freq":false,"src":[],"note":""}},"tr":"사람들이 마지막 순간까지 일을 미루면, 문제가 더 크게 느껴진다. 일이 급해지고, 작은 실수도 더 쉽게 일어난다. 하지만 재료를 미리 준비하거나 작은 목표를 세우는 등 일찍 대비하면 더 차분하고 집중된 상태를 유지할 수 있다. 이런 초기 노력은 나중에 어려운 상황을 더 쉽게 다루도록 도와준다.","ex":{"flow":"마지막 순간까지 미루면 일이 급해지고 실수가 늘지만, 미리 준비하면 더 차분하고 집중할 수 있다는 내용.","b":{"A":["prior 형) 사전의, 이전의","prepare early / ahead of time","prior preparation = 사전 준비. prior to ~ = ~ 이전에. 명사 priority"],"B":["preparation 명) 준비","prepare early — by organizing materials or setting simple goals","reduces(단수 동사)의 주어 → 명사. 동사 prepare"]}}},{"id":"q03","no":3,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Protecting the Environment From Harmful Waste","pas":"Factories and farms sometimes release waste that can harm the land and water if it is not handled properly. When this waste spreads, it can make soil and rivers unsafe for people, animals, and plants. Communities must work together to reduce pollution and keep their surroundings clean.","sum":"Communities must prevent waste from becoming (A) and work to ensure it does not (B) the environment.","gloss":"지역 사회는 폐기물이 (물리·화학적으로) 위험해지는 것을 막고, 환경을 오염시키지 않도록 노력해야 한다.","bl":{"A":[{"first":"h","len":9,"sfx":""}],"B":[{"first":"c","len":11,"sfx":""}]},"key":{"A":{"w":"hazardous","acc":["hazardous"],"freq":false,"src":[],"note":""},"B":{"w":"contaminate","acc":["contaminate"],"freq":false,"src":[],"note":""}},"tr":"공장과 농장은 폐기물을 제대로 처리하지 않으면 땅과 물에 해를 줄 수 있다. 이 폐기물이 퍼지면 사람, 동물, 식물이 사용하는 토양과 강을 위험하게 만들 수 있다. 지역 사회는 오염을 줄이고 주변 환경을 깨끗하게 유지하기 위해 함께 노력해야 한다.","ex":{"flow":"공장과 농장의 폐기물이 제대로 처리되지 않으면 땅과 물을 해치고, 퍼지면 흙과 강을 위험하게 만든다는 내용. (원본 요약문의 문법 오류를 바로잡은 문항)","b":{"A":["hazardous 형) 위험한, 유해한","waste that can harm the land and water / unsafe","hazard(위험)+-ous. hazardous waste = 유해 폐기물"],"B":["contaminate 동) 오염시키다","make soil and rivers unsafe / pollution","does not + 동사 원형. 명사 contamination. 유의어 pollute"]}}},{"id":"q04","no":4,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Surviving Hard Times","pas":"In some regions, long periods without enough food force communities to change how they live. People may search for new ways to grow crops or share limited supplies to survive hard times. Through these efforts, they learn to identify important differences between safe and unsafe choices.","sum":"Hard conditions during a (A) help people (B) which strategies work best.","gloss":"기근 속의 어려운 환경은 사람들이 어떤 전략이 효과적인지 구별하는 데 도움을 준다.","bl":{"A":[{"first":"f","len":6,"sfx":""}],"B":[{"first":"d","len":11,"sfx":""}]},"key":{"A":{"w":"famine","acc":["famine"],"freq":false,"src":[],"note":""},"B":{"w":"distinguish","acc":["distinguish"],"freq":false,"src":[],"note":""}},"tr":"일부 지역에서는 오랫동안 음식이 부족한 상황이 계속되면, 사람들은 삶의 방식을 바꿀 수밖에 없다. 사람들은 힘든 시기를 견디기 위해 새로운 농사 방법을 찾거나 제한된 자원을 나누려 한다. 이러한 노력 속에서 사람들은 안전한 선택과 위험한 선택의 중요한 차이를 구별하게 된다.","ex":{"flow":"먹을 것이 부족한 시기가 길어지면 사람들은 새로운 재배법을 찾거나 물자를 나누며, 안전한 선택과 위험한 선택을 가려내는 법을 배운다는 내용.","b":{"A":["famine 명) 기근","long periods without enough food","during a + 명사. famine relief = 기근 구호. feminine(여성의)과 혼동 주의"],"B":["distinguish 동) 구별하다","identify important differences between safe and unsafe choices","help + 목적어 + 동사원형. distinguish A from B. 형용사 distinguished(저명한)"]}}},{"id":"q05","no":5,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"How the Body Protects Itself","pas":"The human body has many ways to defend itself when harmful germs enter. White blood cells act quickly, removing dangerous invaders before they spread. If the body reacts too strongly, however, this response can also damage healthy tissue.","sum":"When an (A) occurs, the body reacts quickly, yet the reaction can become (B) to healthy cells.","gloss":"감염이 생기면 몸이 빠르게 반응하지만, 그 반응이 건강한 세포에 파괴적일 수 있다.","bl":{"A":[{"first":"i","len":9,"sfx":""}],"B":[{"first":"d","len":11,"sfx":""}]},"key":{"A":{"w":"infection","acc":["infection"],"freq":false,"src":[],"note":""},"B":{"w":"destructive","acc":["destructive"],"freq":false,"src":[],"note":""}},"tr":"인체는 해로운 세균이 들어오면 스스로를 보호하는 다양한 방법을 가지고 있다. 백혈구는 빠르게 움직여 위험한 침입자를 퍼지기 전에 제거한다. 그러나 몸이 너무 강하게 반응하면, 이 과정이 건강한 조직까지 손상시킬 수 있다.","ex":{"flow":"몸에 해로운 균이 들어오면 백혈구가 빠르게 제거하지만, 반응이 너무 강하면 건강한 조직까지 손상될 수 있다는 내용.","b":{"A":["infection 명) 감염","when harmful germs enter","an + 모음 i. 동사 infect, 형용사 infectious"],"B":["destructive 형) 파괴적인","this response can also damage healthy tissue","become + 형용사. be destructive to ~. 동사 destroy, 명사 destruction"]}}},{"id":"q06","no":6,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why People Move to New Places","pas":"Many families choose to leave their hometowns when they hope for better jobs or safer living conditions. Moving to another region often requires careful planning because travel and daily life can cost more money. Despite the challenges, people believe that starting fresh somewhere else may give them a brighter future.","sum":"Families choose (A) even though the (B) of moving and living elsewhere can be high.","gloss":"많은 가정은 이동과 생활 비용이라는 높은 지출에도 불구하고 이주를 선택한다.","bl":{"A":[{"first":"m","len":9,"sfx":""}],"B":[{"first":"e","len":11,"sfx":""}]},"key":{"A":{"w":"migration","acc":["migration"],"freq":false,"src":[],"note":""},"B":{"w":"expenditure","acc":["expenditure"],"freq":false,"src":[],"note":""}},"tr":"많은 가정은 더 나은 일자리나 안전한 생활을 원할 때 고향을 떠나기로 결정한다. 다른 지역으로 이동하는 것은 여행과 일상 생활에 더 많은 비용이 들기 때문에 신중한 계획이 필요하다. 그럼에도 불구하고 사람들은 새로운 곳에서 다시 시작하는 것이 더 나은 미래를 줄 수 있다고 믿는다.","ex":{"flow":"더 나은 일자리나 안전한 삶을 위해 고향을 떠나는 가정이 많고, 이동과 생활에는 돈이 더 들지만 더 밝은 미래를 기대한다는 내용.","b":{"A":["migration 명) 이주, 이동","leave their hometowns / Moving to another region","choose + 명사. 동사 migrate. immigration(이민 옴)·emigration(이민 감)과 구분"],"B":["expenditure 명) 지출, 비용","travel and daily life can cost more money","동사 expend(쓰다). 유의어 expense, cost. -iture 철자"]}}},{"id":"q07","no":7,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Understanding Illness in Different Ways","pas":"When people feel unwell, they often try to understand their symptoms based on personal beliefs or past experiences. These ideas can influence what kind of help they look for, from home remedies to professional medical care. Sometimes, choosing the right response can greatly improve a person’s chances of recovering quickly.","sum":"Finding the right (A) often depends on an accurate (B) of what the body is experiencing.","gloss":"올바른 치료를 찾기 위해서는 몸의 상태에 대한 정확한 해석이 중요하다.","bl":{"A":[{"first":"t","len":9,"sfx":""}],"B":[{"first":"i","len":14,"sfx":""}]},"key":{"A":{"w":"treatment","acc":["treatment"],"freq":false,"src":[],"note":""},"B":{"w":"interpretation","acc":["interpretation"],"freq":false,"src":[],"note":""}},"tr":"사람들은 몸이 좋지 않을 때, 개인적 신념이나 과거 경험을 바탕으로 증상을 이해하려 한다. 이러한 생각은 가정요법부터 전문적인 의료 서비스까지 어떤 도움을 찾을지에 영향을 준다. 올바른 대응을 선택하면 빠르게 회복할 가능성을 크게 높일 수 있다.","ex":{"flow":"몸이 아프면 개인의 믿음이나 경험으로 증상을 이해하고, 그 이해에 따라 어떤 도움을 찾을지가 달라진다는 내용.","b":{"A":["treatment 명) 치료, 처치","home remedies to professional medical care / the right response","동사 treat. the right treatment = 알맞은 치료"],"B":["interpretation 명) 해석, 이해","understand their symptoms based on personal beliefs or past experiences","an accurate + 명사. 동사 interpret, 명사 interpreter(통역사)"]}}},{"id":"q08","no":8,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"How New Habits Become Stronger","pas":"People often try to improve their daily routines by making small changes they can follow easily. With time and practice, these new behaviors become more stable and feel natural. Even simple adjustments can help someone build a more effective and balanced lifestyle.","sum":"Repeated practice after a (A) allows new behaviors to (B) over time.","gloss":"수정 후 반복 연습을 통해 새로운 행동은 시간이 지나며 굳어진다(강화시키다).","bl":{"A":[{"first":"m","len":12,"sfx":""}],"B":[{"first":"c","len":11,"sfx":""}]},"key":{"A":{"w":"modification","acc":["modification"],"freq":false,"src":[],"note":""},"B":{"w":"consolidate","acc":["consolidate"],"freq":false,"src":[],"note":""}},"tr":"사람들은 쉽게 따라 할 수 있는 작은 변화를 통해 일상 습관을 개선하려 노력한다. 시간과 반복이 지나면 이러한 새로운 행동들은 더 안정적이 되고 자연스럽게 느껴진다. 아주 작은 조정이라도 더 효과적이고 균형 잡힌 생활 방식을 만드는 데 도움이 된다.","ex":{"flow":"쉽게 따를 수 있는 작은 변화로 일상을 개선하면, 시간과 연습이 쌓이며 새 행동이 안정되고 자연스러워진다는 내용.","b":{"A":["modification 명) 수정, 변경","making small changes / simple adjustments","동사 modify. after a + 명사"],"B":["consolidate 동) 굳히다, 강화하다","these new behaviors become more stable and feel natural","allow + 목적어 + to 동사원형. con(함께)+solid(단단한). 명사 consolidation"]}}},{"id":"q09","no":9,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Nervous Feelings Before a Yearly Event","pas":"Before a big event that happens every year, many students worry about whether they will perform well. They practice for weeks, trying to avoid mistakes and make their teachers proud. Even though the day brings pressure, it also gives students a chance to show how much they have improved.","sum":"The (A) performance can make students (B), but it also motivates them to practice.","gloss":"연례 공연은 학생들을 불안하게 하지만 연습하도록 자극하기도 한다.","bl":{"A":[{"first":"a","len":6,"sfx":""}],"B":[{"first":"a","len":7,"sfx":""}]},"key":{"A":{"w":"annual","acc":["annual"],"freq":false,"src":[],"note":""},"B":{"w":"anxious","acc":["anxious"],"freq":false,"src":[],"note":""}},"tr":"매년 열리는 큰 행사를 앞두고 많은 학생들은 잘할 수 있을지 걱정한다. 그들은 실수를 피하고 선생님을 기쁘게 하려고 몇 주 동안 연습한다. 그날은 부담을 주지만, 동시에 학생들이 얼마나 성장했는지 보여줄 기회도 된다.","ex":{"flow":"해마다 열리는 큰 행사를 앞두고 학생들은 잘할 수 있을지 걱정하며 몇 주씩 연습하고, 부담이 크지만 실력을 보여 줄 기회가 된다는 내용.","b":{"A":["annual 형) 해마다의, 연례의","a big event that happens every year","ann(해) 어원: anniversary. 부사 annually"],"B":["anxious 형) 불안한, 걱정하는","worry about whether they will perform well / pressure","make + 목적어 + 형용사. 명사 anxiety. be anxious to ~ 는 \"몹시 ~하고 싶은\""]}}},{"id":"q10","no":10,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"When One Company Controls a Market","pas":"In some regions, a single company becomes the only provider of an important product or service. Because no other businesses compete with it, the company can decide prices and rules on its own. This situation often affects consumers, who have fewer choices and must accept what is offered.","sum":"When a firm dominates a (A), it often forms a (B) with no competition.","gloss":"한 기업이 한 영역을 지배하면 경쟁이 없어 독점이 되기 쉽다.","bl":{"A":[{"first":"t","len":9,"sfx":""}],"B":[{"first":"m","len":8,"sfx":""}]},"key":{"A":{"w":"territory","acc":["territory"],"freq":false,"src":[],"note":""},"B":{"w":"monopoly","acc":["monopoly"],"freq":false,"src":[],"note":""}},"tr":"어떤 지역에서는 한 회사가 중요한 상품이나 서비스를 제공하는 유일한 공급자가 되기도 한다. 다른 기업과 경쟁이 없기 때문에, 그 회사는 스스로 가격과 규칙을 결정할 수 있다. 이러한 상황은 소비자에게 영향을 주어, 선택지가 줄어들고 제공되는 것을 받아들일 수밖에 없게 만든다.","ex":{"flow":"어떤 지역에서 한 회사만 중요한 상품을 공급하면, 경쟁자가 없어 가격과 규칙을 마음대로 정하고 소비자의 선택은 줄어든다는 내용.","b":{"A":["territory 명) 영역, 지역, 영토","In some regions","dominate a territory = 한 영역을 장악하다. 형용사 territorial"],"B":["monopoly 명) 독점","the only provider / no other businesses compete with it","mono(하나)+poly(팔다). 동사 monopolize"]}}},{"id":"q11","no":11,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How Animals Change to Survive","pas":"Some animals survive by slowly changing their behavior when their surroundings become difficult. If food is limited, they may give up familiar places and explore new areas to stay safe. Over many generations, these choices help them pass useful traits to their young.","sum":"Some animals must (A) familiar areas when conditions become difficult.","gloss":"몇몇 동물들은 환경이 어려워지면 익숙한 장소를 버려야 한다.","bl":{"A":[{"first":"a","len":7,"sfx":""}]},"key":{"A":{"w":"abandon","acc":["abandon"],"freq":false,"src":[],"note":""}},"tr":"일부 동물들은 환경이 어려워지면 행동을 천천히 바꾸며 생존한다. 먹이가 부족하면 익숙한 장소를 포기하고, 더 안전한 새로운 지역을 탐색하기도 한다. 많은 세대에 걸쳐 이러한 선택은 유용한 특성을 자손에게 전달하는 데 도움을 준다.","ex":{"flow":"환경이 어려워지면 먹이를 찾아 익숙한 곳을 떠나 새 지역을 탐색하는 동물들이 있다는 내용.","b":{"A":["abandon 동) 버리다, 떠나다","give up familiar places","must + 동사 원형. 명사 abandonment. 유의어 desert, leave"]}}},{"id":"q12","no":12,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Bringing Damaged Ecosystems Back to Health","pas":"Forests that have been harmed by fires or pollution often need long-term care to become healthy again. Experts plant new trees, clean the soil, and protect wildlife so nature can recover over time. These efforts help the area return to a safer and more balanced state.","sum":"Planting new trees and cleaning the soil are key steps that help (A) natural areas.","gloss":"새로운 나무를 심고 토양을 정화하는 과정은 자연 지역을 복구하는 데 중요한 단계이다.","bl":{"A":[{"first":"r","len":7,"sfx":""}]},"key":{"A":{"w":"restore","acc":["restore"],"freq":false,"src":[],"note":""}},"tr":"불이나 오염으로 피해를 입은 숲은 다시 건강해지기 위해 오랜 시간이 필요하다. 전문가들은 나무를 심고, 토양을 정화하고, 야생 동물을 보호하여 자연이 시간이 지나며 회복될 수 있도록 돕는다. 이러한 노력은 그 지역이 더 안전하고 균형 잡힌 상태로 돌아가는 데 기여한다.","ex":{"flow":"불이나 오염으로 망가진 숲은 나무 심기·흙 정화·야생동물 보호 같은 장기적인 돌봄으로 다시 건강해진다는 내용.","b":{"A":["restore 동) 회복시키다, 복원하다","become healthy again / recover / return to a safer and more balanced state","help + 동사원형. 명사 restoration. 유의어 recover, revive"]}}},{"id":"q13","no":13,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Moving More Easily in Modern Cities","pas":"As cities grow larger, people look for ways to travel quickly without long delays. Public transportation systems, such as buses and trains, help residents reach work and school more efficiently. Improving these systems gives everyone better access to different parts of the city.","sum":"Better bus and train services support greater (A) by helping people reach places faster.","gloss":"더 나은 버스와 기차 서비스는 사람들의 이동성을 지원해 더 빠르게 이동할 수 있게 한다.","bl":{"A":[{"first":"m","len":8,"sfx":""}]},"key":{"A":{"w":"mobility","acc":["mobility"],"freq":false,"src":[],"note":""}},"tr":"도시가 커질수록 사람들은 긴 지연 없이 빠르게 이동할 방법을 찾는다. 버스와 지하철 같은 대중교통은 주민들이 더 효율적으로 직장이나 학교에 갈 수 있게 돕는다. 이러한 시스템을 개선하면 누구나 도시의 다양한 지역에 더 쉽게 접근할 수 있다.","ex":{"flow":"도시가 커지면서 버스·기차 같은 대중교통이 사람들이 직장과 학교에 더 효율적으로 가게 돕는다는 내용.","b":{"A":["mobility 명) 이동성, 기동성","travel quickly without long delays / better access to different parts of the city","형용사 mobile. support greater mobility = 이동성을 높이다"]}}},{"id":"q14","no":14,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Finding Your Way in the Digital World","pas":"Many people now use online maps and apps to find the best route when traveling to a new place. These tools show directions, traffic conditions, and nearby facilities to help users move with confidence. Thanks to technology, even unfamiliar cities feel easier to explore than before.","sum":"Technology makes it simpler for travelers to (A) different areas with confidence.","gloss":"기술은 여행자들이 다양한 지역을 자신 있게 이동하고 길을 찾는 것을 쉽게 만든다.","bl":{"A":[{"first":"n","len":8,"sfx":""}]},"key":{"A":{"w":"navigate","acc":["navigate"],"freq":false,"src":[],"note":""}},"tr":"많은 사람들은 새로운 곳으로 이동할 때 최적의 경로를 찾기 위해 온라인 지도와 앱을 사용한다. 이 도구들은 길 안내, 교통 상황, 주변 시설 정보를 제공해 이용자가 더 안심하고 이동하도록 돕는다. 기술 덕분에 낯선 도시도 예전보다 훨씬 탐색하기 쉬워졌다.","ex":{"flow":"온라인 지도와 앱이 길·교통·주변 시설을 알려 줘 낯선 도시도 자신 있게 다닐 수 있게 해 준다는 내용.","b":{"A":["navigate 동) 길을 찾다, 돌아다니다","find the best route / move with confidence / explore","for travelers to + 동사 원형. 명사 navigation"]}}},{"id":"q15","no":15,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Understanding a Patient’s Condition","pas":"When people feel sick, doctors ask questions and run tests to find out what is causing the problem. They might check blood samples, scan the body, or observe symptoms carefully. These steps help them choose the right care so the patient can begin to recover.","sum":"Tests and careful observation help medical staff (A) health problems accurately.","gloss":"검사와 세심한 관찰은 의료진이 문제를 정확히 진단하는 데 도움을 준다.","bl":{"A":[{"first":"d","len":8,"sfx":""}]},"key":{"A":{"w":"diagnose","acc":["diagnose"],"freq":false,"src":[],"note":""}},"tr":"사람들이 아플 때, 의사들은 문제의 원인을 알아내기 위해 질문을 하고 검사를 진행한다. 그들은 혈액을 확인하거나 몸을 촬영하거나 증상을 주의 깊게 살펴볼 수 있다. 이러한 과정은 환자가 회복을 시작할 수 있도록 올바른 치료를 선택하는 데 도움이 된다.","ex":{"flow":"의사들은 질문과 검사(혈액·스캔·증상 관찰)로 원인을 찾아 알맞은 치료를 고른다는 내용.","b":{"A":["diagnose 동) 진단하다","find out what is causing the problem","help + 동사원형. 명사 diagnosis(복수 diagnoses). dia(통해)+gnos(알다)"]}}},{"id":"q16","no":16,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Some Land Supports More Life","pas":"Some areas of land are rich in nutrients, allowing plants to grow quickly and stay healthy. Farmers value these places because crops develop well and provide strong harvests. When the soil loses its nutrients, however, plants struggle and produce much less food.","sum":"When the soil is not (A), plants struggle and yields decrease.","gloss":"토양이 비옥하지 않으면 식물이 자라기 어렵고 수확량이 감소한다.","bl":{"A":[{"first":"f","len":7,"sfx":""}]},"key":{"A":{"w":"fertile","acc":["fertile"],"freq":false,"src":[],"note":""}},"tr":"일부 땅은 영양분이 풍부하여 식물이 빠르게 자라고 건강하게 유지될 수 있다. 농부들은 이런 지역을 중요하게 여기는데, 작물이 잘 자라고 많은 수확을 제공하기 때문이다. 하지만 토양이 영양분을 잃으면 식물은 자라기 어려워지고 생산량도 크게 줄어든다.","ex":{"flow":"영양분이 풍부한 땅은 작물이 잘 자라 수확이 좋고, 영양분을 잃으면 식물이 자라기 힘들고 수확이 줄어든다는 내용.","b":{"A":["fertile 형) 비옥한, 기름진","rich in nutrients","is not + 형용사. 명사 fertility, 동사 fertilize(비료 fertilizer). 반의어 barren"]}}},{"id":"q17","no":17,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How Everyday Products Are Made","pas":"Many goods we use daily come from factories where machines and workers turn raw materials into useful items. These places follow careful steps to create products that meet safety and quality standards. Without this process, stores would not be able to offer the wide variety of items people rely on.","sum":"Clear steps help companies (A) goods that meet safety and quality standards.","gloss":"명확한 절차는 기업이 안전 및 품질 기준을 충족하는 제품을 제조하는 데 도움이 된다.","bl":{"A":[{"first":"m","len":11,"sfx":""}]},"key":{"A":{"w":"manufacture","acc":["manufacture"],"freq":false,"src":[],"note":""}},"tr":"우리가 매일 사용하는 많은 물건들은 공장에서 기계와 노동자들이 원재료를 유용한 물품으로 바꾸어 만들어진다. 이러한 장소들은 안전과 품질 기준을 만족시키는 제품을 만들기 위해 세심한 절차를 따른다. 이 과정이 없다면, 가게는 사람들이 의존하는 다양한 물건을 제공할 수 없을 것이다.","ex":{"flow":"공장에서 기계와 노동자가 원료를 유용한 물건으로 바꾸고, 안전·품질 기준에 맞게 신중한 단계를 거친다는 내용.","b":{"A":["manufacture 동) 제조하다","turn raw materials into useful items / create products","help + 동사원형. manu(손)+fact(만들다). 명사로도 쓰임"]}}},{"id":"q18","no":18,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How the Body Fights Against Harmful Germs","pas":"As seasons change, people often face new challenges that can affect their health, such as cold weather or spreading viruses. To stay well, the body strengthens its natural defenses by building habits like proper sleep, good nutrition, and regular exercise. These healthy routines make it easier for the body to deal with harmful germs it meets in daily life.","sum":"Good sleep and nutrition increase the body’s (A) to harmful germs.","gloss":"충분한 수면과 영양은 해로운 세균에 대한 저항력을 높인다.","bl":{"A":[{"first":"r","len":10,"sfx":""}]},"key":{"A":{"w":"resistance","acc":["resistance"],"freq":false,"src":[],"note":""}},"tr":"계절이 바뀌면 추운 날씨나 퍼지는 바이러스처럼 건강에 영향을 주는 새로운 어려움이 생긴다. 몸은 충분한 수면, 좋은 식습관, 규칙적인 운동 같은 습관을 통해 자연적인 방어력을 강화한다. 이러한 건강한 생활 습관은 일상에서 마주치는 해로운 세균을 더 잘 이겨내도록 돕는다.","ex":{"flow":"계절이 바뀌며 추위나 바이러스 같은 위협이 오면, 충분한 잠·영양·운동이 몸의 자연 방어력을 키운다는 내용.","b":{"A":["resistance 명) 저항(력)","strengthens its natural defenses / deal with harmful germs","the body’s resistance to ~ = ~에 대한 저항력. 동사 resist, 형용사 resistant"]}}},{"id":"q19","no":19,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Weather Conditions That Affect Daily Life","pas":"In some regions, the air carries a lot of moisture, making the weather feel heavy and uncomfortable. During this time, clothes take longer to dry, and people may feel tired more easily. Because of these conditions, many communities use fans or dehumidifiers to stay comfortable indoors.","sum":"People often feel tired in (A) conditions because the air is full of moisture.","gloss":"사람들은 공기에 수분이 많은 습한 환경에서 쉽게 피로함을 느낀다.","bl":{"A":[{"first":"h","len":5,"sfx":""}]},"key":{"A":{"w":"humid","acc":["humid"],"freq":false,"src":[],"note":""}},"tr":"일부 지역에서는 공기 속에 수분이 많아 날씨가 무겁고 불편하게 느껴진다. 이런 시기에는 옷이 마르는 데 더 오래 걸리고, 사람들은 쉽게 피로감을 느낄 수 있다. 이러한 환경 때문에 많은 지역 사회는 실내에서 쾌적하게 지내기 위해 선풍기나 제습기를 사용한다.","ex":{"flow":"공기에 습기가 많으면 날씨가 무겁고 불편하게 느껴지고, 옷이 잘 안 마르며 쉽게 피곤해진다는 내용.","b":{"A":["humid 형) 습한","the air carries a lot of moisture","명사 humidity. 제습기 dehumidifier가 같은 어원"]}}},{"id":"q20","no":20,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How People Understand the World Around Them","pas":"People often understand situations differently depending on their past experiences and personal feelings. Two individuals might see the same event but focus on completely different details. These differences can influence how they make decisions and how they react to others.","sum":"A person’s (A) affects how they make decisions and respond to others.","gloss":"개인의 인식은 의사결정과 타인에 대한 반응에 영향을 준다.","bl":{"A":[{"first":"p","len":10,"sfx":""}]},"key":{"A":{"w":"perception","acc":["perception"],"freq":false,"src":[],"note":""}},"tr":"사람들은 과거 경험과 개인적 감정에 따라 상황을 다르게 이해하곤 한다. 두 사람이 같은 사건을 보더라도 전혀 다른 부분에 주목할 수 있다. 이러한 차이는 그들의 의사결정과 다른 사람에게 보이는 반응에도 영향을 줄 수 있다.","ex":{"flow":"사람들은 과거 경험과 감정에 따라 같은 일을 다르게 이해하고, 그 차이가 결정과 반응에 영향을 준다는 내용.","b":{"A":["perception 명) 인식, 지각","understand situations differently / focus on completely different details","affects(단수 동사)의 주어 → 명사. 동사 perceive"]}}}]},{"r":7,"qs":[{"id":"q01","no":1,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why a Sense of Safety Supports Personal Growth","pas":"People learn and develop better when they feel calm in their surroundings. In stressful places, individuals focus more on avoiding problems than trying new things. But in environments where people feel respected and protected, they are more willing to explore, make mistakes, and try again. Such conditions allow them to discover new abilities and build confidence step by step.","sum":"People (A) when they feel (B) in their environment.","gloss":"사람들은 환경이 안전하다고 느낄 때 더 번성한다.","bl":{"A":[{"first":"t","len":6,"sfx":""}],"B":[{"first":"s","len":6,"sfx":""}]},"key":{"A":{"w":"thrive","acc":["thrive"],"freq":false,"src":[],"note":""},"B":{"w":"secure","acc":["secure"],"freq":false,"src":[],"note":""}},"tr":"사람들은 주변 환경이 안정적일 때 더 잘 배우고 성장한다. 스트레스가 많은 곳에서는 새로운 것을 시도하기보다 문제를 피하는 데 에너지를 쓰게 된다. 하지만 존중받고 안전하다고 느껴지는 환경에서는 사람들은 더 기꺼이 탐색하고, 실수하고, 다시 시도한다. 이런 조건은 새로운 능력을 발견하고 자신감을 쌓는 과정을 가능하게 해 준다.","ex":{"flow":"스트레스가 많은 곳에선 문제를 피하는 데 집중하지만, 존중받고 보호받는다고 느끼는 환경에선 새로운 시도와 실수를 하며 성장한다는 내용.","b":{"A":["thrive 동) 번성하다, 잘 자라다","learn and develop better / discover new abilities and build confidence","People(복수) + 동사 원형. 유의어 flourish, prosper"],"B":["secure 형) 안전한, 안정된","feel calm / respected and protected","feel + 형용사. 명사 security. 동사(확보하다)로도 쓰임"]}}},{"id":"q02","no":2,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How New Technology Changes Everyday Life","pas":"When a new tool becomes available, people often need time to understand how it works. At first, many individuals feel unsure and continue using older methods. However, as they see others benefit from the new tool, they slowly begin to try it themselves. Once more people use it, daily routines start to shift, showing how one invention can influence many parts of life.","sum":"The (A) of new technology slowly changes people’s daily routines.","gloss":"새로운 기술의 등장은 사람들의 일상을 천천히 변화시킨다.","bl":{"A":[{"first":"a","len":6,"sfx":""}]},"key":{"A":{"w":"advent","acc":["advent"],"freq":false,"src":[],"note":""}},"tr":"새로운 도구가 등장하면, 사람들은 그 사용법을 이해하기까지 시간이 필요하다. 처음에는 많은 사람들이 불확실함 때문에 기존의 방식을 계속 사용한다. 그러나 주변 사람들이 그 도구를 통해 이득을 얻는 모습을 보게 되면, 조금씩 스스로도 사용해 보기 시작한다. 더 많은 사람들이 사용하기 시작하면 일상의 흐름이 달라지며, 하나의 발명이 삶의 여러 부분에 영향을 줄 수 있음을 보여준다.","ex":{"flow":"새 도구가 나오면 처음엔 망설이다가 다른 사람들이 덕 보는 것을 보고 하나둘 쓰기 시작해 일상이 바뀐다는 내용.","b":{"A":["advent 명) 출현, 도래","When a new tool becomes available / one invention","the advent of ~ = ~의 등장. ad(~로)+vent(오다) → 다가옴"]}}},{"id":"q03","no":3,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Long-Term Goals Require Steady Effort","pas":"When people try to achieve something important, success usually does not come quickly. They may face slow progress, repeated mistakes, or moments when they feel discouraged. However, continuing to work a little each day helps them move forward even when results are not visible. This slow but consistent effort often becomes the key to reaching long-term goals.","sum":"Because (A) takes time, people must develop (B) to keep working through challenges.","gloss":"진보(발전)는 시간이 걸리기 때문에, 사람들은 도전을 버텨낼 인내력을 길러야 한다.","bl":{"A":[{"first":"p","len":8,"sfx":""}],"B":[{"first":"e","len":9,"sfx":""},{"first":"p","len":12,"sfx":""}]},"key":{"A":{"w":"progress","acc":["progress"],"freq":false,"src":[],"note":""},"B":{"w":"endurance / perseverance","acc":["endurance","perseverance"],"freq":false,"src":[],"note":""}},"tr":"사람들이 중요한 목표를 이루려 할 때, 성공은 보통 빠르게 찾아오지 않는다. 진전이 더딜 수 있고, 실수가 반복되거나 의욕이 떨어지는 순간도 있다. 하지만 하루에 조금씩이라도 계속 노력하면, 눈에 띄는 성과가 없어도 앞으로 나아갈 수 있다. 이런 느리지만 꾸준한 노력이 장기적인 목표를 이루는 핵심이 되는 경우가 많다.","ex":{"flow":"중요한 목표는 빨리 이루어지지 않고 더딘 진전과 실수가 반복되지만, 매일 조금씩 계속하는 것이 장기 목표의 열쇠라는 내용.","b":{"A":["progress 명) 진전, 발전","slow progress / move forward","takes(단수 동사)의 주어 → 불가산 명사 progress"],"B":["endurance / perseverance 명) 인내(력) / 끈기","continuing to work a little each day / slow but consistent effort","두 단어 모두 정답(e 9칸, p 12칸). endure(견디다), persevere(인내하다)"]}}},{"id":"q04","no":4,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How the Mind Links New Information to What It Already Knows","pas":"When people learn something new, they rarely understand it as an isolated fact. Instead, the brain tries to connect the new idea to something familiar—such as an earlier experience or a concept already stored in memory. This connection helps the information stay longer and become easier to recall later. Because of this process, learning becomes faster when new ideas relate to things we already understand.","sum":"While isolated facts are harder to keep, an (A) with prior knowledge makes learning easier.","gloss":"고립된 단독 정보는 기억하기 어렵지만, 기존 지식과의 연상(연결)은 학습을 더 쉽게 만든다.","bl":{"A":[{"first":"a","len":11,"sfx":""}]},"key":{"A":{"w":"association","acc":["association"],"freq":false,"src":[],"note":""}},"tr":"사람들이 새로운 정보를 배울 때, 그것을 단독적인 사실로만 이해하는 경우는 거의 없다. 대신 뇌는 그 새로운 정보를 이전에 경험했거나 이미 기억 속에 있는 개념과 연결하려고 한다. 이러한 연결은 정보를 더 오래 기억하게 하고 나중에 더 쉽게 떠올릴 수 있도록 돕는다. 이 과정 덕분에, 새로운 내용이 우리가 이미 아는 것과 관련될수록 학습은 더 빨라진다.","ex":{"flow":"새 정보를 따로 떨어진 사실로 이해하기보다, 뇌는 익숙한 경험이나 기억 속 개념과 연결해 더 오래, 쉽게 기억한다는 내용.","b":{"A":["association 명) 연상, 연관(성)","connect the new idea to something familiar / This connection","an + 모음 a. 동사 associate A with B(2회 8번 지문)"]}}},{"id":"q05","no":5,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"How Machines Change the Way People Work","pas":"As technology becomes more advanced, many machines can now perform tasks that people once had to do themselves. These tools help workers finish jobs faster and with fewer mistakes. However, people still need to understand how the machines operate, especially when something goes wrong. This balance between human guidance and machine work is becoming more important in modern workplaces.","sum":"While (A) grows, some (B) skills remain important for solving problems.","gloss":"자동화가 늘어도, 문제 해결에는 여전히 수동적(육체적) 기술이 중요하다.","bl":{"A":[{"first":"a","len":10,"sfx":""}],"B":[{"first":"m","len":6,"sfx":""}]},"key":{"A":{"w":"automation","acc":["automation"],"freq":false,"src":[],"note":""},"B":{"w":"manual","acc":["manual"],"freq":false,"src":[],"note":""}},"tr":"기술이 발전하면서, 과거에는 사람이 직접 해야 했던 일을 이제는 기계가 대신 수행할 수 있게 되었다. 이런 도구들은 작업을 더 빠르고 정확하게 끝내는 데 도움을 준다. 하지만 문제가 생길 때를 대비해, 사람들은 여전히 기계를 어떻게 다루는지 이해할 필요가 있다. 이처럼 인간의 조정과 기계의 작업 사이의 균형은 현대 직장에서 점점 더 중요해지고 있다.","ex":{"flow":"기계가 사람이 하던 일을 대신하지만, 고장 났을 때처럼 사람이 기계를 이해하고 직접 다루는 능력은 여전히 중요하다는 내용.","b":{"A":["automation 명) 자동화","machines can now perform tasks that people once had to do","auto(스스로) 어원. 동사 automate, 형용사 automatic"],"B":["manual 형) 손으로 하는, 수동의","human guidance / understand how the machines operate","manu(손) 어원: manufacture. 명사로 \"설명서\""]}}},{"id":"q06","no":6,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How Living Things Adjust to Changing Environments","pas":"In nature, conditions do not stay the same forever. Temperatures shift, food sources move, and new predators may appear. To survive these changes, animals often develop new behaviors—such as traveling to safer areas or changing when they search for food. These small adjustments help them continue living even when their surroundings become difficult.","sum":"Because conditions shift over time, (A) allows species to continue living safely.","gloss":"상황이 변하기 때문에, 적응은 종이 안전하게 삶을 이어가도록 돕는다.","bl":{"A":[{"first":"a","len":10,"sfx":""}]},"key":{"A":{"w":"adaptation","acc":["adaptation"],"freq":false,"src":[],"note":""}},"tr":"자연에서는 환경이 영원히 그대로 유지되지 않는다. 기온이 변하고, 먹이의 위치가 바뀌고, 새로운 포식자가 나타나기도 한다. 이런 변화 속에서 생존하려면 동물들은 더 안전한 곳으로 이동하거나 먹이를 찾는 시간을 바꾸는 등의 새로운 행동을 보이곤 한다. 이러한 작은 조정들은 주변 환경이 어려워져도 계속 살아갈 수 있도록 돕는다.","ex":{"flow":"기온·먹이·포식자가 변하면 동물들은 더 안전한 곳으로 옮기거나 먹이 찾는 시간을 바꾸는 등 행동을 조정해 살아남는다는 내용.","b":{"A":["adaptation 명) 적응","develop new behaviors / These small adjustments","동사 adapt. allows(단수 동사)의 주어 → 명사. adoption(채택)과 구분"]}}},{"id":"q07","no":7,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Perfect Choices Are Hard to Find","pas":"When people make decisions, they often hope to find an option that solves every problem. However, most choices come with both benefits and disadvantages. A plan that works well today may cause new issues later, and an easy option might not help in the long run.","sum":"People often learn that (A) of their choices are completely perfect.","gloss":"","bl":{"A":[{"first":"n","len":4,"sfx":""}]},"key":{"A":{"w":"none","acc":["none"],"freq":false,"src":[],"note":""}},"tr":"사람들은 결정을 내릴 때 모든 문제를 해결해 줄 완벽한 선택지를 찾고 싶어한다. 하지만 대부분의 선택에는 장점과 단점이 함께 존재한다. 오늘은 잘 맞는 계획도 시간이 지나면 새로운 문제를 만들 수 있고, 쉬운 선택은 장기적으로 도움이 되지 않을 수도 있다.","ex":{"flow":"모든 문제를 해결하는 선택을 바라지만, 대부분의 선택엔 장단점이 함께 있다는 내용. \"완벽한 선택은 하나도 없다\".","b":{"A":["none 대) 아무것도 ~않다","most choices come with both benefits and disadvantages","none of + 복수 명사 + are/is. 부정어가 빈칸에 들어가 \"완벽하지 않다\"는 뜻이 됨"]}}},{"id":"q08","no":8,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"How Small Signals Affect Communication","pas":"During conversations, people often pay attention to words, but communication is more than the sentences we speak. A person’s tone, pauses, or small changes in facial expression can influence how a message is understood. These soft signals may show interest, discomfort, or hesitation even when nothing is said directly. Understanding these quiet hints helps people connect better and avoid misunderstandings.","sum":"Because tone and expression guide (A), their (B) influence shapes the meaning of a conversation.","gloss":"목소리와 표정이 이해(해석)의 틀을 제시하기 때문에, 그 미묘한 영향이 대화의 의미를 형성한다.","bl":{"A":[{"first":"i","len":14,"sfx":""}],"B":[{"first":"s","len":6,"sfx":""}]},"key":{"A":{"w":"interpretation","acc":["interpretation"],"freq":false,"src":[],"note":""},"B":{"w":"subtle","acc":["subtle"],"freq":false,"src":[],"note":""}},"tr":"대화를 할 때 사람들은 보통 말로 표현된 내용에 집중한다. 하지만 소통은 말만으로 이루어지지 않는다. 사람의 목소리 톤, 잠깐의 멈춤, 표정의 작은 변화는 메시지가 어떻게 받아들여지는지에 영향을 준다. 이런 미세한 신호들은 직접 말하지 않아도 관심, 불편함, 망설임을 드러낼 수 있다. 이 작은 단서를 이해하면 오해를 줄이고 더 잘 소통할 수 있다.","ex":{"flow":"대화에서 말뿐 아니라 어조·멈춤·표정의 작은 변화가 메시지가 이해되는 방식에 영향을 준다는 내용.","b":{"A":["interpretation 명) 해석, 이해","can influence how a message is understood","guide + 명사(목적어). 6회 7번과 같은 단어"],"B":["subtle 형) 미묘한, 은근한","These soft signals / quiet hints","발음 [서틀], b는 묵음. 명사 subtlety"]}}},{"id":"q09","no":9,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Our Minds Do Not Always See Things Clearly","pas":"People like to believe they understand situations exactly as they are. However, emotions, stress, and past experiences can affect the way they interpret events. For example, when someone feels nervous, they may think a small problem is much bigger than it truly is. Because of these influences, people sometimes respond to situations based on their feelings rather than the actual facts.","sum":"Emotions can cause a (A) of how people see situations.","gloss":"","bl":{"A":[{"first":"d","len":10,"sfx":""}]},"key":{"A":{"w":"distortion","acc":["distortion"],"freq":false,"src":[],"note":""}},"tr":"사람들은 상황을 있는 그대로 명확하게 이해한다고 믿고 싶어한다. 하지만 감정, 스트레스, 과거 경험이 사건을 해석하는 방식에 영향을 줄 수 있다. 예를 들어, 누군가 긴장하면 작은 문제도 실제보다 훨씬 크게 느껴질 수 있다. 이러한 요인들 때문에 사람들은 때때로 사실보다는 감정에 따라 상황에 반응하기도 한다.","ex":{"flow":"감정·스트레스·과거 경험이 사건을 해석하는 방식에 영향을 줘, 긴장하면 작은 문제도 크게 보이는 등 사실이 아니라 감정에 따라 반응한다는 내용.","b":{"A":["distortion 명) 왜곡","think a small problem is much bigger than it truly is","a + 명사. 동사 distort. dis+tort(비틀다)"]}}},{"id":"q10","no":10,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Seeing Your Role in a Problem Leads to Real Change","pas":"When people deal with difficulties, they sometimes focus only on what others did wrong. This may protect their feelings for a moment, but it does not help them solve the issue. Real improvement begins when individuals look at their own part—such as a habit they can fix or a step they can take differently next time. By understanding how their choices influence the situation, they gain more control over future outcomes.","sum":"People grow when they become (A) for their choices and take (B) of their role in a situation.","gloss":"사람들은 자신의 선택에 책임감이 있거나 상황에서의 역할에 주인의식을 가질 때 성장한다.","bl":{"A":[{"first":"r","len":11,"sfx":""}],"B":[{"first":"o","len":9,"sfx":""}]},"key":{"A":{"w":"responsible","acc":["responsible"],"freq":false,"src":[],"note":""},"B":{"w":"ownership","acc":["ownership"],"freq":false,"src":[],"note":""}},"tr":"사람들은 어려움을 겪을 때 다른 사람이 잘못한 부분만 바라보기도 한다. 이런 태도는 잠시 마음을 편하게 해주지만, 문제 해결에는 도움이 되지 않는다. 진짜 변화는 스스로 고칠 수 있는 습관이나 다음에 다르게 할 수 있는 행동처럼, 자기 역할을 바라볼 때 시작된다. 자신의 선택이 상황에 어떤 영향을 주는지 이해하면, 앞으로의 결과를 더 잘 통제할 수 있게 된다.","ex":{"flow":"어려울 때 남의 잘못에만 집중하면 문제가 풀리지 않고, 자신의 몫을 돌아볼 때 진짜 개선이 시작된다는 내용.","b":{"A":["responsible 형) 책임 있는","look at their own part / how their choices influence the situation","be responsible for ~ = ~에 책임이 있다. 명사 responsibility"],"B":["ownership 명) 주인의식, 소유","a habit they can fix or a step they can take differently","take ownership of ~ = ~을 자기 일로 책임지다"]}}},{"id":"q11","no":11,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"When Creativity Works Best at the “Wrong” Time","pas":"People have different times of day when they feel most energetic—some in the morning, some at night, and others in the afternoon. It’s usually helpful to do important or difficult tasks when you feel at your strongest. However, creative work can be different. Research suggests that people often get better ideas during the time of day when they feel less focused. When the mind is not fully alert, it becomes looser and more open, allowing creative thoughts to appear more easily.","sum":"The (A) time to (B) creativity","gloss":"","bl":{"A":[{"first":"o","len":7,"sfx":""}],"B":[{"first":"s","len":5,"sfx":""}]},"key":{"A":{"w":"optimal","acc":["optimal"],"freq":false,"src":[],"note":""},"B":{"w":"spark","acc":["spark"],"freq":true,"src":[],"note":"창의력을 촉발시킬 수 있는 최적의 시간"}},"tr":"사람마다 가장 에너지가 높은 시간대가 다르다. 중요하거나 집중이 필요한 일은 보통 이런 “잘 되는 시간”에 하는 것이 좋다. 하지만 창의적인 작업은 다르게 작동할 수 있다. 연구에 따르면 사람들은 집중력이 떨어지는 시간대에 더 좋은 아이디어를 떠올리는 경우가 많다. 머리가 완전히 깨어 있지 않을 때 오히려 생각이 느슨해져서 창의적인 발상이 자연스럽게 흐르는 것이다.","ex":{"flow":"중요한 일은 가장 에너지가 높은 시간에 하는 게 좋지만, 창의적인 일은 덜 집중될 때 마음이 느슨하고 열려 아이디어가 더 잘 떠오른다는 내용. 요약문은 제목형.","b":{"A":["optimal 형) 최적의","the time of day when they feel less focused","optimum과 같은 어원. 유의어 ideal, best"],"B":["spark 동) 촉발하다, 불러일으키다","allowing creative thoughts to appear more easily","to + 동사 원형. 명사로 \"불꽃\"(1회 18번 small sparks)"]}}},{"id":"q12","no":12,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Some Students Struggle With Reading Tasks","pas":"In every classroom, some students read texts smoothly while others find it more difficult. Many factors can affect reading, such as trouble recognizing letters quickly or understanding long sentences. When students feel stressed or rushed, the task becomes even harder, and they may avoid reading altogether.","sum":"Some students face challenges because a reading (A) makes understanding texts harder.","gloss":"일부 학생들은 읽기 장애 때문에 글 이해가 더 어렵다.","bl":{"A":[{"first":"d","len":10,"sfx":""}]},"key":{"A":{"w":"disability","acc":["disability"],"freq":false,"src":[],"note":""}},"tr":"모든 교실에서 어떤 학생은 글을 자연스럽게 읽지만, 다른 학생은 더 어렵게 느끼기도 한다. 글자를 빠르게 알아보거나 긴 문장을 이해하는 데 어려움이 있는 등 여러 요인이 읽기 능력에 영향을 줄 수 있다. 학생들이 스트레스를 받거나 시간이 부족하면 읽기는 더 힘들어지고, 아예 읽기를 피하게 될 수도 있다.","ex":{"flow":"글자를 빨리 알아보지 못하거나 긴 문장 이해가 어려운 등 여러 이유로 읽기를 힘들어하는 학생이 있다는 내용.","b":{"A":["disability 명) 장애","trouble recognizing letters quickly or understanding long sentences","a reading disability = 읽기 장애. dis(부정)+ability"]}}},{"id":"q13","no":13,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Appreciating Small Things Improves Well-Being","pas":"People often focus on big goals, thinking that only major successes will make their lives fulfilling. However, noticing simple things—like a warm meal, a peaceful moment, or support from a friend—can lift the mind more than expected. When individuals take time to reflect on these everyday positives, their mood becomes calmer and their stress decreases. This gentle shift shows that emotional well-being grows when people pay attention to what is already good in their lives.","sum":"Noticing everyday positives helps people feel (A) and leads to lasting (B).","gloss":"일상의 작은 좋은 점을 바라보면 사람들은 감사하게 느끼고 더 지속되는 만족을 얻게 된다.","bl":{"A":[{"first":"g","len":8,"sfx":""}],"B":[{"first":"c","len":11,"sfx":""}]},"key":{"A":{"w":"grateful","acc":["grateful"],"freq":false,"src":[],"note":""},"B":{"w":"contentment","acc":["contentment"],"freq":true,"src":["[1학년] 2023년 2학기 중간 객관식 13번"],"note":""}},"tr":"사람들은 종종 큰 목표나 큰 성공만이 삶을 만족스럽게 만든다고 생각한다. 하지만 따뜻한 식사, 조용한 시간, 친구의 작은 도움 같은 일상의 사소한 것들이 예상보다 더 마음을 밝힐 때가 있다. 이런 일상의 좋은 순간들을 돌아보는 시간은 마음을 차분하게 하고 스트레스를 줄여준다. 이러한 변화는 이미 삶 속에 있는 좋은 것들을 바라볼 때 정서적 행복이 자란다는 사실을 보여준다.","ex":{"flow":"큰 성공만 바라기보다 따뜻한 식사, 평화로운 순간, 친구의 지지 같은 일상의 좋은 것을 알아차리면 마음이 차분해지고 행복이 자란다는 내용.","b":{"A":["grateful 형) 고마워하는, 감사하는","take time to reflect on these everyday positives / what is already good","feel + 형용사. great와 철자 혼동 주의(greatful ✗). 명사 gratitude"],"B":["contentment 명) 만족, 자족","mood becomes calmer / emotional well-being grows","lasting + 명사. 형용사 content(만족하는)"]}}},{"id":"q14","no":14,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Competing With Others Can Shape Behavior","pas":"In many situations, people pay close attention to how others around them perform. Seeing someone work harder or achieve something first often pushes individuals to try a little more themselves. This reaction can help them improve their skills, but it can also create stress if they worry too much about doing better than everyone else. Understanding this balance helps people use competition in a healthy way instead of letting it control their emotions.","sum":"Watching others succeed often creates a sense of (A) that pushes people to try harder.","gloss":"","bl":{"A":[{"first":"r","len":7,"sfx":""}]},"key":{"A":{"w":"rivalry","acc":["rivalry"],"freq":false,"src":[],"note":"다른 사람이 성공하는 것을 보면 경쟁심(rivalry) 이 생겨 더 노력하게 된다."}},"tr":"여러 상황에서 사람들은 주변 사람들이 어떻게 행동하는지에 큰 관심을 가진다. 누군가 더 열심히 하거나 먼저 성공하는 모습을 보면, 자신도 조금 더 노력해 보려는 마음이 생기기도 한다. 이런 반응은 실력을 향상시키는 데 도움이 되지만, 다른 사람보다 앞서야 한다는 압박이 너무 커지면 스트레스를 만들 수도 있다. 이 균형을 이해하면 사람들은 감정에 휘둘리지 않고 건강하게 경쟁을 활용할 수 있다.","ex":{"flow":"주변 사람이 더 열심히 하거나 먼저 이루는 것을 보면 더 노력하게 되지만, 지나치면 스트레스가 된다는 내용.","b":{"A":["rivalry 명) 경쟁(의식)","Competing With Others / doing better than everyone else","a sense of rivalry = 경쟁심. 명사 rival(경쟁자)"]}}},{"id":"q15","no":15,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 각각 1단어 영어로 쓰시오.","title":"Why Limits Can Sometimes Improve Creativity","pas":"Many people think they need complete freedom to come up with new ideas. However, having too many options can make it harder to choose a direction. When people work with only a few tools or a small amount of time, they often discover unexpected solutions. These boundaries push them to think differently and find new ways to solve problems.","sum":"While freedom feels (A), a (B) sometimes produces more original thinking.","gloss":"","bl":{"A":[{"first":"h","len":7,"sfx":""}],"B":[{"first":"c","len":10,"sfx":""}]},"key":{"A":{"w":"helpful","acc":["helpful"],"freq":false,"src":[],"note":""},"B":{"w":"constraint","acc":["constraint"],"freq":false,"src":[],"note":"자유가 (창의적 사고에) 도움이 되는 반면에, 제약(constraint) 은 때때로 더 독창적인 사고를 이끈다."}},"tr":"많은 사람들은 완전한 자유가 있어야 새로운 아이디어가 나온다고 생각한다. 하지만 선택지가 너무 많으면 오히려 방향을 잡기 어려워질 수 있다. 적은 도구나 짧은 시간처럼 제한된 조건 속에서 사람들은 예상치 못한 해결책을 발견하곤 한다. 이런 경계들은 사람들에게 다르게 생각하고 새로운 방식으로 문제를 해결하도록 밀어준다.","ex":{"flow":"완전한 자유가 필요하다고 생각하지만 선택지가 너무 많으면 방향을 정하기 어렵고, 도구나 시간이 제한될 때 뜻밖의 해결책을 찾는다는 내용.","b":{"A":["helpful 형) 도움이 되는","Many people think they need complete freedom","feel + 형용사. 4회 17번(ideal)과 같은 구조"],"B":["constraint 명) 제약, 제한","only a few tools or a small amount of time / These boundaries","동사 constrain. a + 명사. 4회 17번 restrictive와 같은 맥락"]}}},{"id":"q16","no":16,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How Stress Affects Attention and Clear Thinking","pas":"When people try to focus on a task, their minds work best in a calm environment. However, when someone feels worried or overloaded, it becomes harder to pay attention. They may forget simple steps, lose track of time, or misunderstand instructions. As stress increases, the brain uses more energy to handle emotions, leaving less energy for thinking clearly.","sum":"High stress can leave a person’s attention (A).","gloss":"높은 스트레스는 사람의 주의력을 손상된 상태로 만들 수 있다.","bl":{"A":[{"first":"i","len":8,"sfx":""}]},"key":{"A":{"w":"impaired","acc":["impaired"],"freq":false,"src":[],"note":""}},"tr":"사람들이 어떤 일에 집중하려 할 때, 차분한 환경에서 가장 잘 집중한다. 하지만 걱정이 많거나 부담이 커지면 주의를 유지하기 어려워진다. 간단한 절차를 잊거나, 시간을 놓치거나, 지시를 잘못 이해할 수도 있다. 스트레스가 높아질수록 뇌는 감정을 처리하는 데 더 많은 에너지를 쓰고, 그만큼 명확한 사고에 쓸 에너지가 줄어든다.","ex":{"flow":"걱정되거나 일이 너무 많으면 주의를 기울이기 어렵고, 뇌가 감정 처리에 에너지를 써서 명확히 생각할 힘이 줄어든다는 내용.","b":{"A":["impaired 형) 손상된, 약해진","harder to pay attention / forget simple steps / less energy for thinking clearly","leave + 목적어 + 형용사(~한 상태로 두다). 1회 3번과 같은 단어"]}}},{"id":"q17","no":17,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Rare Opportunities Feel More Valuable","pas":"People often pay more attention to things that do not appear every day. When a resource, chance, or experience is limited, individuals think about it more carefully and treat it with greater respect. For example, students may work harder when they know they have only a short time to complete a project. This shows that limited opportunities can influence how people behave and what they value.","sum":"People value rare chances because they (A) appear in daily life.","gloss":"사람들은 희소한 기회를 소중히 여긴다. 왜냐하면 그런 기회들은 거의 나타나지 않기 때문이다.","bl":{"A":[{"first":"s","len":8,"sfx":""},{"first":"h","len":6,"sfx":""}]},"key":{"A":{"w":"scarcely / hardly","acc":["scarcely","hardly"],"freq":false,"src":[],"note":""}},"tr":"사람들은 매일 볼 수 없는 것에 더 큰 관심을 기울이곤 한다. 자원이나 기회, 경험이 제한되어 있을 때, 사람들은 그것을 더 신중하게 생각하고 더 소중히 여긴다. 예를 들어, 학생들은 프로젝트를 끝낼 시간이 짧을 때 더 열심히 노력할 수 있다. 이것은 제한된 기회가 사람들의 행동과 가치 판단에 영향을 준다는 사실을 보여준다.","ex":{"flow":"흔하지 않은 자원·기회·경험은 더 신중하게 다루고 더 소중히 여기게 된다는 내용.","b":{"A":["scarcely / hardly 부) 거의 ~않다","things that do not appear every day / limited","두 단어 모두 정답(s 8칸, h 6칸). 부정어라 not과 함께 쓰지 않음. 형용사 scarce(1회 7번 scarcity)"]}}},{"id":"q18","no":18,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"Why Steady Habits Improve Learning","pas":"Many people try to learn new skills by studying a lot in a short period of time. However, this method often makes the information difficult to remember. When people practice a little every day, their minds have more time to absorb the material. This steady routine helps them build stronger understanding and keeps them from feeling overwhelmed.","sum":"Learning becomes easier when people study with (A).","gloss":"","bl":{"A":[{"first":"r","len":10,"sfx":""}]},"key":{"A":{"w":"regularity","acc":["regularity"],"freq":false,"src":[],"note":"공부를 규칙적(regularity)으로 할 때 학습이 더 쉬워진다."}},"tr":"많은 사람들은 짧은 시간에 몰아서 공부하려고 한다. 하지만 이런 방식은 정보를 기억하기 어렵게 만든다. 반대로 매일 조금씩 연습하면, 뇌는 내용을 더 잘 흡수할 시간을 갖게 된다. 이런 꾸준한 습관은 이해를 더 깊게 만들고 부담감을 줄여 준다.","ex":{"flow":"짧은 시간에 몰아서 공부하면 기억하기 어렵지만, 매일 조금씩 연습하면 내용을 흡수할 시간이 생겨 더 단단히 이해한다는 내용.","b":{"A":["regularity 명) 규칙성, 꾸준함","practice a little every day / This steady routine","with + 명사. 형용사 regular, 부사 regularly"]}}},{"id":"q19","no":19,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":null,"pas":"Students work to get good grades even when they have no interest in their studies. People seek job advancement even when they are happy with the jobs they already have. It’s like being in a crowded football stadium, watching the crucial play. A spectator several rows in front stands up to get a better view, and a chain reaction follows. Soon everyone is standing, just to be able to see as well as before. Everyone is on their feet rather than sitting, but no one’s position has improved. And if someone refuses to stand, he might just as well not be at the game at all. When people pursue goods that are positional, they can’t help being in the rat race. To choose not to run is to lose.","sum":"Limitless and Fierce (A) for Pursuing Positional Things","gloss":"","bl":{"A":[{"first":"S","len":8,"sfx":""}]},"key":{"A":{"w":"struggle","acc":["struggle"],"freq":true,"src":[],"note":"지위적인 것들을 좇기 위한 끝없고 치열한 고군분투(경쟁)"}},"tr":"학생들은 공부에 아무 흥미가 없어도 좋은 성적을 받기 위해 노력한다. 사람들은 지금 하는 일에 이미 만족하고 있어도 승진을 원한다. 이건 마치 꽉 찬 축구 경기장에서 결정적인 순간을 보는 것과 같다. 앞줄에 있던 관중 한 명이 더 잘 보기 위해 일어서면, 그게 연쇄반응을 일으킨다. 곧 모두가 전에 보던 만큼이라도 보려고 일어서게 된다. 결국 모두가 앉아 있을 때보다 더 나아진 사람은 아무도 없는데, 다들 그냥 서 있는 상태가 되어버린다. 그리고 만약 어떤 사람이 굳이 안 일어서겠다고 하면, 그냥 경기장에서 빠져 있는 거나 다름없다. 사람들이 포지션(서열적 가치)을 가진 것들을 좇기 시작하면, 그 경쟁에서 벗어날 수가 없다. 경주에 참여하지 않겠다는 선택은 곧 ‘지는 것’이기 때문이다.","ex":{"flow":"[고난도 · 모의고사 지문] 경기장에서 앞사람이 일어서면 모두가 일어서게 되듯, 남보다 앞서야 의미가 있는 \"지위재\"를 좇으면 경쟁에서 빠질 수 없고, 달리지 않기로 하면 지는 것이라는 내용. 요약문은 제목형.","b":{"A":["Struggle 명) 고군분투, 투쟁","the rat race / To choose not to run is to lose","제목 속 명사이므로 대문자 S로 주어짐. Limitless and Fierce(끝없고 치열한)가 꾸미는 명사"]}}},{"id":"q20","no":20,"inst":"다음 글의 주제를 완성할 때, 빈칸 (A)에 들어갈 말로 가장 적절한 것을 주어진 철자로 시작하여 철자 수에 맞추어 1단어 영어로 쓰시오.","title":"How Guidance Helps People Grow Confident","pas":"When people try to learn something new, they often feel unsure at the beginning. A few kind words, clear instructions, or helpful feedback can make a big difference. These small forms of support show learners that they are capable of improving, even if the task feels difficult at first. With steady encouragement, individuals begin to trust their abilities and try challenges they once avoided.","sum":"Support and encouragement can (A) people to believe in their abilities.","gloss":"지원과 격려는 사람들에게 자신의 능력을 믿도록 힘을 준다(부여한다).","bl":{"A":[{"first":"e","len":7,"sfx":""}]},"key":{"A":{"w":"empower","acc":["empower"],"freq":false,"src":[],"note":""}},"tr":"사람들은 새로운 것을 배우려고 할 때 처음에는 자신이 없을 수 있다. 하지만 따뜻한 말, 명확한 설명, 도움 되는 피드백은 큰 변화를 만든다. 이런 작은 지원은 처음엔 어려워 보여도 스스로 발전할 수 있다는 느낌을 준다. 꾸준한 격려는 사람들이 자신의 능력을 믿고, 예전에 피했던 도전에도 나서는 힘을 준다.","ex":{"flow":"새로운 것을 배울 때 처음엔 불안하지만, 친절한 말·분명한 안내·도움이 되는 피드백이 할 수 있다는 믿음을 준다는 내용.","b":{"A":["empower 동) 힘을 주다, 권한을 주다","show learners that they are capable / begin to trust their abilities","can + 동사 원형. empower + 목적어 + to 동사원형. 명사 empowerment"]}}}]}]}],"pass":70};
